-- ── 3. functions ────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.add_contact(p_athlete_id text, p_display_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_whatsapp text DEFAULT NULL::text, p_source text DEFAULT 'proof'::text, p_tier text DEFAULT 'free'::text)
 RETURNS TABLE(aid text, akey text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_athlete_id is null or btrim(p_athlete_id) = '' then
    raise exception 'athlete id required';
  end if;

  insert into public.hab_contacts (athlete_id, email, whatsapp, display_name, source, tier)
  values (p_athlete_id, nullif(btrim(coalesce(p_email, '')), ''),
                        nullif(btrim(coalesce(p_whatsapp, '')), ''),
                        nullif(btrim(coalesce(p_display_name, '')), ''),
                        coalesce(p_source, 'proof'), coalesce(p_tier, 'free'))
  on conflict (athlete_id) do update
    set email        = coalesce(excluded.email, hab_contacts.email),
        whatsapp     = coalesce(excluded.whatsapp, hab_contacts.whatsapp),
        display_name = coalesce(excluded.display_name, hab_contacts.display_name),
        source       = excluded.source,
        tier         = excluded.tier,
        updated_at   = now();

  return query select p_athlete_id, null::text;
end; $function$;

CREATE OR REPLACE FUNCTION public.assess_member()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select exists (select 1 from public.assess_accounts a where a.user_id = auth.uid() and a.revoked_at is null) $function$;

CREATE OR REPLACE FUNCTION public.assess_publish(p_token text, p_key text, p_body jsonb, p_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_token is null or length(p_token) < 40 or not exists (
       select 1 from public.assess_publish_keys k
       where k.key_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex')) then
    raise exception 'not allowed';
  end if;
  insert into public.assess_content (key, body, version, updated_at)
  values (p_key, p_body, p_version, now())
  on conflict (key) do update set body = excluded.body, version = excluded.version, updated_at = now();
end $function$;

CREATE OR REPLACE FUNCTION public.assess_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin new.updated_at := now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.career_backfill(p_athlete text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text; v_n integer := 0;
begin
  if public.career_rules_now() is null then
    raise exception 'Career Mode has no rulebook yet: run the seed first (python scripts/career_seed.py)';
  end if;
  for v_id in
    select distinct z.id from (
      select a.athlete_id as id from public.athlete_progress a
      union select s.athlete_id from public.session_history s
      union select l.athlete_id from public.library_sessions l
      union select p.athlete_id from public.programs p
      union select f.athlete_id from public.career_facts f) z
     where p_athlete is null or z.id = p_athlete
     order by 1
  loop
    perform public.career_observe_proof(v_id);
    perform public.career_observe_session(v_id);
    perform public.career_observe_library(v_id);
    perform public.career_derive(v_id);
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('athletes', v_n,
           'facts', coalesce((select jsonb_object_agg(x.kind, x.n) from (
                               select f.kind, count(*) as n from public.career_facts f
                                where f.void_at is null and (p_athlete is null or f.athlete_id = p_athlete)
                                group by f.kind order by f.kind) x), '{}'::jsonb),
           'void', (select count(*) from public.career_facts f where f.void_at is not null and (p_athlete is null or f.athlete_id = p_athlete)));
end $function$;

CREATE OR REPLACE FUNCTION public.career_canon(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case when jsonb_typeof(p) = 'array'
              then coalesce((select jsonb_agg(e.v order by e.v::text) from jsonb_array_elements(p) as e(v)), '[]'::jsonb)
              else p end
$function$;

CREATE OR REPLACE FUNCTION public.career_cfg(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with d as (
    select f.day, f.value -> 'live' as ids, lag(f.value -> 'live') over (order by f.day) as prev
      from public.career_facts f
     where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null
  )
  select jsonb_build_object(
    'roster', coalesce((select jsonb_agg(jsonb_build_object('from', d.day::text, 'ids', d.ids) order by d.day)
                          from d where d.prev is distinct from d.ids), '[]'::jsonb),
    'custom', coalesce((select jsonb_agg(jsonb_build_object('id', c.value))
                          from (select f.value -> 'custom' as cl from public.career_facts f
                                 where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null
                                 order by f.day desc limit 1) z,
                               jsonb_array_elements_text(coalesce(z.cl, '[]'::jsonb)) c), '[]'::jsonb))
$function$;

CREATE OR REPLACE FUNCTION public.career_compare(p_season date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_x jsonb; v_r jsonb; v_xp jsonb; v_rp jsonb; v_now jsonb := public.career_rules_now(); v_settle date;
  v_s date; v_t date := current_date; v_wk date; a record;
  v_log jsonb; v_cfg jsonb; v_cl jsonb; v_cc jsonb; v_rows jsonb := '[]'::jsonb; v_bad integer := 0; v_n integer := 0; v_settled integer := 0;
  p_season_xp bigint; c_season_xp bigint; p_week bigint; c_week bigint; p_all bigint; c_all bigint;
  v_probe jsonb; v_facts jsonb; v_row_ok boolean; v_diff jsonb; v_closed integer;
begin
  select x.rules into v_x from public.xp_rules x where x.id = 1;
  v_r := public.career_habit_rules();
  if v_x is null or v_r is null then
    raise exception 'nothing to compare: xp_rules or the Career Mode rulebook is missing';
  end if;
  v_xp := public.career_paid_rules(v_x, v_now);
  v_rp := public.career_paid_rules(v_r, v_now);
  v_settle := public.career_settled_before(v_now);
  v_s := coalesce(p_season, (select s.starts_on from public.current_season() s), '1970-01-01'::date);
  v_wk := greatest(v_t - 6, v_s);
  select coalesce(jsonb_agg(k.key order by k.key), '[]'::jsonb) into v_diff
    from jsonb_object_keys(v_r) as k(key)
   where k.key <> 'questRuns'
     and public.career_canon(public.career_scoring(k.key, v_r -> k.key)) is distinct from public.career_canon(public.career_scoring(k.key, v_x -> k.key));
  for a in
    select ap.athlete_id, ap.data from public.athlete_progress ap
     where ap.data ? (ap.athlete_id || '_hab_log') order by ap.athlete_id
  loop
    v_n := v_n + 1;
    v_log := public.hab_log_of(a.data, a.athlete_id);
    v_cfg := public.hab_cfg_of(a.data, a.athlete_id);
    v_cl := public.career_log(a.athlete_id);
    v_cc := public.career_cfg(a.athlete_id);
    p_season_xp := public.hab_xp(v_log, v_s, v_t, v_xp) + public.hab_bonus_xp(v_log, v_cfg, v_s, v_s, v_t, v_x);
    c_season_xp := public.hab_xp(v_cl, v_s, v_t, v_rp) + public.hab_bonus_xp(v_cl, v_cc, v_s, v_s, v_t, v_r);
    p_week := public.hab_xp(v_log, v_wk, v_t, v_xp) + public.hab_bonus_xp(v_log, v_cfg, v_s, v_wk, v_t, v_x);
    c_week := public.hab_xp(v_cl, v_wk, v_t, v_rp) + public.hab_bonus_xp(v_cl, v_cc, v_s, v_wk, v_t, v_r);
    p_all := public.hab_xp(v_log, '1970-01-01', v_t, v_xp) + public.hab_bonus_xp(v_log, v_cfg, '1970-01-01', '1970-01-01', v_t, v_x);
    c_all := public.hab_xp(v_cl, '1970-01-01', v_t, v_rp) + public.hab_bonus_xp(v_cl, v_cc, '1970-01-01', '1970-01-01', v_t, v_r);
    v_probe := public.career_probe(v_log, v_cfg, v_s, v_t, v_x);
    select jsonb_build_object(
             'perfect', count(*) filter (where f.kind = 'perfect_day' and f.day between v_s and v_t),
             'on_target', count(*) filter (where f.kind = 'day_on_target' and f.day between v_s and v_t),
             'comebacks', count(*) filter (where f.kind = 'comeback' and f.day between v_s and v_t
                                             and public.career_day(f.value ->> 'prev') >= v_s))
      into v_facts
      from public.career_facts f where f.athlete_id = a.athlete_id and f.void_at is null;
    -- the closed days whose log and facts differ (only once the XP switch is on: before it, nothing settles)
    v_closed := case when v_settle is null then 0 else
      (select count(*)::int from (
         select coalesce(pl.key, cl.key) as k
           from (select e.key, e.value from jsonb_each(coalesce(v_log, '{}'::jsonb)) e
                  where e.key ~ '^\d{4}-\d{2}-\d{2}$' and jsonb_typeof(e.value) = 'object' and e.key < v_settle::text) pl
           full join (select e.key, e.value from jsonb_each(coalesce(v_cl, '{}'::jsonb)) e where e.key < v_settle::text) cl
             on cl.key = pl.key
          where pl.value is distinct from cl.value) z) end;
    v_row_ok := p_season_xp = c_season_xp and p_week = c_week and p_all = c_all and v_probe = v_facts;
    if not v_row_ok and v_closed > 0 then
      v_settled := v_settled + 1;
    elsif not v_row_ok then
      v_bad := v_bad + 1;
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'athlete_id', a.athlete_id, 'ok', v_row_ok,
      'settled', case when not v_row_ok and v_closed > 0 then true end, 'closed', nullif(v_closed, 0),
      'season', jsonb_build_object('proof', p_season_xp, 'career', c_season_xp),
      'week', jsonb_build_object('proof', p_week, 'career', c_week),
      'all', jsonb_build_object('proof', p_all, 'career', c_all),
      'probe', jsonb_build_object('proof', v_probe, 'facts', v_facts))));
  end loop;
  return jsonb_build_object('ok', v_bad = 0 and jsonb_array_length(v_diff) = 0, 'season_start', v_s, 'today', v_t,
                            'xp_switch', public.career_switch_day(v_now, 'xp'), 'settled_before', v_settle,
                            'athletes', v_n, 'matched', v_n - v_bad - v_settled, 'settled', v_settled,
                            'rules_equal', jsonb_array_length(v_diff) = 0, 'rules_differ_on', v_diff, 'rows', v_rows);
end $function$;

CREATE OR REPLACE FUNCTION public.career_compute(p_athlete text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now(); v_hr jsonb; v_paid jsonb; v_log jsonb; v_cfg jsonb;
  v_name text; v_start date; v_s date; v_wfrom date; v_today date := current_date;
  c_d bigint; c_b bigint; s_d bigint; s_b bigint; w_d bigint; w_b bigint;
  c_f jsonb; c_r numeric; s_f jsonb; s_r numeric; w_r numeric; v_cxp bigint; v_sxp bigint;
begin
  if v_rules is null or p_athlete is null then return null; end if;
  v_hr := public.career_habit_rules();
  v_paid := public.career_paid_rules(v_hr, v_rules);
  v_log := public.career_log(p_athlete);
  v_cfg := public.career_cfg(p_athlete);
  select s.name, s.starts_on into v_name, v_start from public.current_season() s;
  v_s := coalesce(v_start, '1970-01-01'::date);
  v_wfrom := greatest(v_today - 6, v_s);
  c_d := public.hab_xp(v_log, null, v_today, v_paid);
  c_b := public.hab_bonus_xp(v_log, v_cfg, null, null, v_today, v_hr);
  s_d := public.hab_xp(v_log, v_s, v_today, v_paid);
  s_b := public.hab_bonus_xp(v_log, v_cfg, v_s, v_s, v_today, v_hr);
  w_d := public.hab_xp(v_log, v_wfrom, v_today, v_paid);
  w_b := public.hab_bonus_xp(v_log, v_cfg, v_s, v_wfrom, v_today, v_hr);
  with p as (select x.* from public.career_facts_paid(p_athlete) x where x.day <= v_today)
  select coalesce((select jsonb_object_agg(z.kind, jsonb_build_object('n', z.n, 'xp', z.xp))
                     from (select p.kind, count(*) as n, sum(p.xp) as xp from p group by p.kind) z), '{}'::jsonb),
         coalesce((select sum(p.xp) from p), 0),
         coalesce((select jsonb_object_agg(z.kind, jsonb_build_object('n', z.n, 'xp', z.xp))
                     from (select p.kind, count(*) as n, sum(p.xp) as xp from p where p.day >= v_s and not p.career_only group by p.kind) z),
                  '{}'::jsonb),
         coalesce((select sum(p.xp) from p where p.day >= v_s and not p.career_only), 0),
         coalesce((select sum(p.xp) from p where p.day >= v_wfrom and not p.career_only), 0)
    into c_f, c_r, s_f, s_r, w_r;
  v_cxp := (c_d + c_b + round(c_r))::bigint;
  v_sxp := (s_d + s_b + round(s_r))::bigint;
  return jsonb_build_object(
    'career', jsonb_build_object('habits', jsonb_build_object('daily', c_d, 'bonus', c_b, 'xp', c_d + c_b),
                                 'facts', c_f, 'facts_xp', round(c_r)::bigint, 'xp', v_cxp)
              || public.career_level(v_cxp, v_rules),
    'season', jsonb_build_object('name', v_name, 'starts_on', v_start, 'points', v_sxp,
                                 'parts', jsonb_build_object('habits', jsonb_build_object('daily', s_d, 'bonus', s_b, 'xp', s_d + s_b),
                                                             'facts', s_f, 'facts_xp', round(s_r)::bigint, 'xp', v_sxp)),
    'week', jsonb_build_object('from', v_wfrom, 'points', (w_d + w_b + round(w_r))::bigint));
end $function$;

CREATE OR REPLACE FUNCTION public.career_cycle_wins(p_athlete text, p_from date, p_to date, p_plan text[], p_rules jsonb)
 RETURNS TABLE(lift text, name text, gain numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_min numeric := coalesce(public.career_num(p_rules #> '{fact,effort_win,min_gain}'), 0.02);
  v_limit integer := coalesce(public.career_num(p_rules #> '{fact,effort_win,limit}')::int, 3);
  x record; v_cur text := null; v_out jsonb := '[]'::jsonb; v_g numeric;
  a_name text; a_w numeric; a_n numeric; a_ng boolean; a_idx numeric; a_first integer;
  has_b boolean := false; b_w numeric; b_n numeric; b_ng boolean; b_r numeric; b_idx numeric;
begin
  for x in
    select es.*, dense_rank() over (order by es.f_d, es.f_pd, es.f_o, es.lift) as met
      from (select e0.*, first_value(e0.d) over w0 as f_d, first_value(e0.plan_day) over w0 as f_pd, first_value(e0.ord) over w0 as f_o
              from public.career_entry_sets(p_athlete, p_from, p_to, p_plan) e0
             where e0.lift <> ''
            window w0 as (partition by e0.lift order by e0.d, e0.plan_day, e0.ord)) es
     order by es.lift, es.d, es.plan_day, es.ord
  loop
    if v_cur is distinct from x.lift then
      if v_cur is not null and has_b then
        v_g := public.career_win_gain(a_w, a_n, a_ng, a_idx, b_w, b_n, b_ng, b_idx, v_min);
        if v_g is not null then
          v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'g', v_g, 'met', a_first));
        end if;
      end if;
      v_cur := x.lift; a_name := x.name; a_w := x.b_w; a_n := x.b_n; a_ng := x.b_n_given; a_idx := x.b_idx; a_first := x.met;
      has_b := false;
    elsif not has_b then
      has_b := true; b_w := x.b_w; b_n := x.b_n; b_ng := x.b_n_given; b_r := x.b_r; b_idx := x.b_idx;
    elsif (x.b_idx is not null and (b_idx is null or x.b_idx > b_idx))
       or (x.b_idx is null and b_idx is null and x.b_r is not null and (b_r is null or x.b_r < b_r)) then
      b_w := x.b_w; b_n := x.b_n; b_ng := x.b_n_given; b_r := x.b_r; b_idx := x.b_idx;
    end if;
  end loop;
  if v_cur is not null and has_b then
    v_g := public.career_win_gain(a_w, a_n, a_ng, a_idx, b_w, b_n, b_ng, b_idx, v_min);
    if v_g is not null then
      v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'g', v_g, 'met', a_first));
    end if;
  end if;
  return query
    select y.l, y.nm, y.g from jsonb_to_recordset(v_out) as y(l text, nm text, g numeric, met integer)
     order by y.g desc, y.met
     limit v_limit;
end $function$;

CREATE OR REPLACE FUNCTION public.career_day(p text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p is null or p !~ '^\d{4}-\d{2}-\d{2}' then return null; end if;
  return left(p, 10)::date;
exception when others then
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_derive(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now();
  v_close integer; v_share numeric; v_away integer; v_window integer;
  v_paused date; v_want jsonb := '[]'::jsonb; w record; c record; x record;
  v_ref text; v_closed boolean; v_run integer := 0; v_armed boolean := false; v_prev_broken boolean := false; v_prev_to date;
  v_done integer; v_planned integer; v_recs jsonb; v_raw text; v_first date; v_status text;
begin
  if v_rules is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  v_close := coalesce(public.career_num(v_rules #> '{week,close_after_days}')::int, 1);
  v_share := coalesce(public.career_num(v_rules #> '{fact,cycle_finished,min_share}'), 0.8);
  v_away := coalesce(public.career_num(v_rules #> '{fact,training_return,weeks_away}')::int, 2);
  v_window := coalesce(public.career_num(v_rules #> '{fact,retest_done,window_days}')::int, 7);
  select s.since, s.status into v_paused, v_status from public.athlete_status s where s.athlete_id = p_athlete;
  select min(sh.completed_on) into v_first from public.session_history sh where sh.athlete_id = p_athlete and sh.hidden_at is null;

  -- ── weeks, in the order they happened, from the week of the athlete's first session ──
  for w in
    with wk as (select * from public.career_weeks(p_athlete)),
    s as (select sh.day::text as pday, sh.completed_on as d, 'd' || sh.day || '|' || sh.completed_on::text as ref
            from public.session_history sh where sh.athlete_id = p_athlete and sh.hidden_at is null)
    select wk.*,
           (select count(*) from s where s.d between wk.wfrom and wk.wto and s.pday = any (wk.plan))::int as nsess,
           (select bool_and(exists (select 1 from s where s.d between wk.wfrom and wk.wto and s.pday = pd)) from unnest(wk.plan) pd) as held,
           (select max(z.fd) from (select min(s.d) as fd from s where s.d between wk.wfrom and wk.wto and s.pday = any (wk.plan)
                                    group by s.pday) z) as held_on,
           (select bool_and(exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'full_log'
                                       and f.ref = s.ref and f.void_at is null)
                            and exists (select 1 from public.career_facts f where f.athlete_id = p_athlete and f.kind = 'checkin_done'
                                           and f.ref = s.ref and f.void_at is null))
              from s where s.d between wk.wfrom and wk.wto and s.pday = any (wk.plan)) as by_book
      from wk
     order by wk.wfrom, wk.cycle_index
  loop
    if v_first is null or w.wto < v_first then
      continue;              -- before their first session: a week they never started is neither held nor broken
    end if;
    v_ref := 'c' || w.cycle_num || '|w' || w.week;
    v_closed := current_date > w.wto + v_close;
    if w.held then
      if v_armed then
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'training_return', 'ref', v_ref, 'day', w.held_on,
                    'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week)));
        v_armed := false;
      end if;
      if v_prev_broken and w.wfrom - v_prev_to <= 8 then
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'bounce_back', 'ref', v_ref, 'day', w.held_on,
                    'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week)));
      end if;
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'week_held', 'ref', v_ref, 'day', w.held_on,
                  'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week, 'sessions', w.nsess, 'plan', cardinality(w.plan))));
      if w.by_book then         -- every session that week fully logged and checked in first
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'week_by_the_book', 'ref', v_ref, 'day', w.held_on,
                    'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week)));
      end if;
      v_run := 0; v_prev_broken := false; v_prev_to := w.wto;
    elsif v_closed then
      if v_paused is not null and w.wto >= v_paused then
        continue;            -- a week Amir paused the athlete for (or one after they left) is neither broken nor away (P2)
      end if;
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'week_broken', 'ref', v_ref, 'day', w.wto,
                  'value', jsonb_build_object('cycle', w.cycle_num, 'week', w.week, 'sessions', w.nsess, 'plan', cardinality(w.plan))));
      if w.nsess = 0 then
        v_run := v_run + 1;
        if v_run >= v_away then v_armed := true; end if;
      else
        v_run := 0;
      end if;
      v_prev_broken := true; v_prev_to := w.wto;
    end if;
    -- a week still running and not yet held: nothing yet
  end loop;

  -- ── cycles that have ended: finished, the roadmap, the effort wins ──
  for c in
    select distinct on (cw.cycle_index) cw.cycle_index, cw.cycle_num, cw.weeks, cw.cstart, cw.cend, cw.plan, cw.is_last
      from public.career_weeks(p_athlete) cw
     order by cw.cycle_index
  loop
    if current_date <= c.cend + v_close then continue; end if;
    select count(*) into v_done from public.session_history s
     where s.athlete_id = p_athlete and s.hidden_at is null and s.completed_on between c.cstart and c.cend and s.day::text = any (c.plan);
    v_planned := cardinality(c.plan) * c.weeks;
    if v_planned > 0 and v_done::numeric / v_planned >= v_share then
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'cycle_finished', 'ref', 'c' || c.cycle_num, 'day', c.cend + 1,
                  'value', jsonb_build_object('cycle', c.cycle_num, 'done', v_done, 'planned', v_planned)));
      if c.is_last then
        v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'roadmap_finished', 'ref', 'roadmap', 'day', c.cend + 1,
                    'value', jsonb_build_object('cycle', c.cycle_num)));
      end if;
    end if;
    for x in select * from public.career_cycle_wins(p_athlete, c.cstart, c.cend, c.plan, v_rules) loop
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'effort_win', 'ref', 'c' || c.cycle_num || '|' || x.lift,
                  'day', c.cend + 1, 'value', jsonb_build_object('cycle', c.cycle_num, 'lift', x.name, 'gain', round(x.gain, 4))));
    end loop;
  end loop;

  -- ── every whole month since the first session (month_with_amir); none while a former athlete ──
  if v_first is not null then
    for x in
      select g as n, (v_first + make_interval(months => g))::date as on_day
        from generate_series(1, 1200) g
       where (v_first + make_interval(months => g))::date <= case when v_status = 'former' then least(current_date, v_paused) else current_date end
    loop
      v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'month_with_amir', 'ref', x.n::text, 'day', x.on_day,
                  'value', jsonb_build_object('month', x.n)));
    end loop;
  end if;

  -- ── each lift's best gain over its first session (lift_gain) ──
  for x in select * from public.career_lift_gains(p_athlete) loop
    v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'lift_gain', 'ref', x.lift, 'day', x.d,
                'value', jsonb_build_object('lift', x.name, 'pct', x.pct)));
  end loop;

  -- ── the Personal Records: a new best (personal_best), a retest (retest_done, retest_beaten) ──
  select a.data -> (p_athlete || '_1rm') into v_recs from public.athlete_progress a where a.athlete_id = p_athlete;
  if jsonb_typeof(v_recs) = 'string' then
    v_raw := v_recs #>> '{}';
    begin
      v_recs := v_raw::jsonb;
    exception when others then
      v_recs := '[]'::jsonb;
    end;
  end if;
  if jsonb_typeof(v_recs) is distinct from 'array' then v_recs := '[]'::jsonb; end if;

  with rec as (
    select r0.e ->> 'lift' as lift, public.career_day(r0.e ->> 'd') as d, r0.e, r0.ord, coalesce(public.career_js_num(r0.e -> 't'), 0) as t
      from jsonb_array_elements(v_recs) with ordinality r0(e, ord)
     where jsonb_typeof(r0.e) = 'object' and public.career_truthy(r0.e -> 'lift') and public.career_truthy(r0.e -> 'd')
  ),
  eff as (     -- one entry speaks for each day of a lift: the newest write (ceilingLifts(), fillRecords())
    select distinct on (rec.lift, rec.d) rec.* from rec where rec.d is not null order by rec.lift, rec.d, rec.t desc, rec.ord
  ),
  kept as (select eff.* from eff where not public.career_truthy(eff.e -> 'del') and coalesce(public.career_num(eff.e -> 'kg'), 0) > 0)
  select v_want || coalesce(jsonb_agg(jsonb_build_object('kind', 'personal_best', 'ref', k.lift || '|' || k.d::text, 'day', k.d,
                                                         'value', jsonb_build_object('lift', k.lift, 'kg', public.career_num(k.e -> 'kg')))), '[]'::jsonb)
    into v_want
    from kept k
   where public.career_truthy(k.e -> 'auto')
     and exists (select 1 from kept k2 where k2.lift = k.lift and k2.d < k.d);   -- a lift's first number is not a best: nothing to beat

  -- retests: a test-flagged lift (exTestSpec(): true, or "<n>RM" up to 10) logged in its cycle's test week, the last [fact.retest_done]
  -- window_days of the cycle (inRetestWindow()) and after its end while it is still the current cycle, judged on its best estimate that
  -- week; beaten when that tops the lift's previous test, or its best earlier record when there was none.
  for x in
    with cyc as (select distinct on (cw.cycle_index) cw.* from public.career_weeks(p_athlete) cw order by cw.cycle_index),
    src as (
      select cyc.cycle_index, cyc.cycle_num, cyc.cend, cyc.is_current, cyc.plan,
             case when cyc.is_current then (select pr.data from public.programs pr where pr.athlete_id = p_athlete)
                  else (select v.data from public.program_versions v
                         where v.athlete_id = p_athlete and jsonb_typeof(v.data -> 'currentCycleIndex') = 'number'
                           and public.career_num(v.data -> 'currentCycleIndex') = cyc.cycle_index
                         order by v.saved_at desc limit 1) end as data
        from cyc
    ),
    flagged as (
      select distinct src.cycle_index, src.cycle_num, src.cend, src.is_current, ex.v ->> 'name' as name,
             public.career_norm(ex.v ->> 'name') as lift
        from src,
             jsonb_array_elements(case when jsonb_typeof(src.data -> 'workouts' -> 'days') = 'array'
                                       then src.data -> 'workouts' -> 'days' else '[]'::jsonb end) as dd(v),
             jsonb_array_elements(case when jsonb_typeof(dd.v -> 'blocks') = 'array' then dd.v -> 'blocks' else '[]'::jsonb end) as bb(v),
             jsonb_array_elements(case when jsonb_typeof(bb.v -> 'exercises') = 'array' then bb.v -> 'exercises' else '[]'::jsonb end) as ex(v)
       where ex.v ->> 'type' = 'standard' and public.career_truthy(ex.v -> 'name')
         and (ex.v -> 'test' = 'true'::jsonb
              or ((ex.v ->> 'test') ~* '^\d+\s*rm$' and (substring(ex.v ->> 'test' from '^(\d+)'))::int between 1 and 10))
    ),
    evidence as (
      select f.cycle_index, f.cycle_num, f.name, f.lift, es.d, es.best_est as est
        from flagged f
        join lateral public.career_entry_sets(p_athlete, f.cend - v_window, case when f.is_current then current_date else f.cend end, null) es
          on es.lift = f.lift
      union all
      select f.cycle_index, f.cycle_num, f.name, f.lift, public.career_day(r.e ->> 'd'), public.career_num(r.e -> 'kg')
        from flagged f, jsonb_array_elements(v_recs) r(e)
       where jsonb_typeof(r.e) = 'object' and public.career_truthy(r.e -> 'test') and not public.career_truthy(r.e -> 'del')
         and public.career_norm(r.e ->> 'lift') = f.lift
         and public.career_day(r.e ->> 'd') between f.cend - v_window and case when f.is_current then current_date else f.cend end
    )
    select distinct on (ev.lift, ev.cycle_index) ev.*
      from evidence ev
     order by ev.lift, ev.cycle_index, ev.est desc nulls last, ev.d
  loop
    v_want := v_want || jsonb_build_array(jsonb_build_object('kind', 'retest_done', 'ref', x.lift || '|c' || x.cycle_num, 'day', x.d,
                'value', jsonb_strip_nulls(jsonb_build_object('lift', x.name, 'cycle', x.cycle_num, 'est', x.est))));
  end loop;
  -- beaten: against this lift's previous retest, else its best record before the retest day
  with t as (
    select (e.v ->> 'ref') as ref, (e.v ->> 'day')::date as d, e.v -> 'value' as v, public.career_norm(e.v #>> '{value,lift}') as lift,
           (e.v #>> '{value,cycle}')::int as cyc, public.career_num(e.v #> '{value,est}') as est
      from jsonb_array_elements(v_want) as e(v) where e.v ->> 'kind' = 'retest_done'
  ),
  recs as (
    select public.career_norm(r1.e ->> 'lift') as lift, public.career_day(r1.e ->> 'd') as d, public.career_num(r1.e -> 'kg') as kg
      from jsonb_array_elements(v_recs) r1(e)
     where jsonb_typeof(r1.e) = 'object' and not public.career_truthy(r1.e -> 'del') and coalesce(public.career_num(r1.e -> 'kg'), 0) > 0
  ),
  judged as (
    select t.*,
           (select t2.est from t t2 where t2.lift = t.lift and t2.cyc < t.cyc and t2.est is not null order by t2.cyc desc limit 1) as prev_test,
           (select max(r.kg) from recs r where r.lift = t.lift and r.d < t.d) as prev_best
      from t
  )
  select v_want || coalesce(jsonb_agg(jsonb_build_object('kind', 'retest_beaten', 'ref', j.ref, 'day', j.d,
                                                         'value', j.v || jsonb_build_object('beat', coalesce(j.prev_test, j.prev_best)))), '[]'::jsonb)
    into v_want
    from judged j
   where j.est is not null and coalesce(j.prev_test, j.prev_best) is not null and j.est > coalesce(j.prev_test, j.prev_best);

  perform public.career_sync(p_athlete, array['week_held', 'week_broken', 'bounce_back', 'training_return', 'week_by_the_book',
                                              'cycle_finished', 'roadmap_finished', 'effort_win', 'month_with_amir', 'lift_gain',
                                              'personal_best', 'retest_beaten'], v_want, 'server');
  perform public.career_sync(p_athlete, array['retest_done'], v_want, 'training');
end $function$;

CREATE OR REPLACE FUNCTION public.career_derive_days(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb := public.career_rules_now(); v_want jsonb; v_lapse integer; v_stick integer; v_settle date;
begin
  if v_rules is null or p_athlete is null then return; end if;
  v_lapse := coalesce((v_rules #>> '{habits,lapse_days}')::int, 3);
  v_stick := coalesce((v_rules #>> '{habits,comeback_stick}')::int, 7);
  v_settle := public.career_settled_before(v_rules);
  with hd as (select * from public.career_habit_days(p_athlete)),
  q as (select hd.d, lag(hd.d) over (order by hd.d) as prev from hd where hd.on_target),
  isl as (select hd.d, hd.d - (row_number() over (order by hd.d))::int as grp from hd where hd.on_target),
  runs as (select min(isl.d) as s, count(*)::int as len from isl group by isl.grp)
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_want from (
    select jsonb_build_object('kind', 'day_on_target', 'ref', hd.d::text, 'day', hd.d,
                              'value', jsonb_build_object('done', hd.ndone, 'of', hd.nlive)) as x
      from hd where hd.on_target
    union all
    select jsonb_build_object('kind', 'perfect_day', 'ref', hd.d::text, 'day', hd.d, 'value', jsonb_build_object('of', hd.nlive))
      from hd where hd.perfect
    union all
    select jsonb_build_object('kind', 'comeback', 'ref', q.d::text, 'day', q.d,
                              'value', jsonb_build_object('prev', q.prev, 'gone', q.d - q.prev - 1))
      from q where v_lapse > 0 and q.prev is not null and q.d - q.prev - 1 >= v_lapse
    union all
    select jsonb_build_object('kind', 'comeback_stuck', 'ref', q.d::text, 'day', q.d + v_stick - 1,
                              'value', jsonb_build_object('held', r.len))
      from q join runs r on r.s = q.d
     where v_lapse > 0 and v_stick > 0 and q.prev is not null and q.d - q.prev - 1 >= v_lapse and r.len >= v_stick
  ) s;
  perform public.career_sync(p_athlete, array['day_on_target', 'perfect_day'], v_want, 'proof', null, v_settle);
  perform public.career_sync(p_athlete, array['comeback', 'comeback_stuck'], v_want, 'server', null, v_settle);
end $function$;

CREATE OR REPLACE FUNCTION public.career_digits(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select translate(coalesce(p, ''),
                   U&'\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\066B\060C',
                   '01234567890123456789..')
$function$;

CREATE OR REPLACE FUNCTION public.career_entry_sets(p_athlete text, p_from date, p_to date, p_plan text[])
 RETURNS TABLE(d date, plan_day integer, ord integer, name text, lift text, b_w numeric, b_n numeric, b_n_given boolean, b_r numeric, b_idx numeric, best_est numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  s record; e jsonb; eo integer; st jsonb;
  w numeric; n numeric; n_given boolean; r numeric; rir numeric; idx numeric; rpe numeric; eff numeric; est numeric;
  has_best boolean; bw numeric; bn numeric; bng boolean; br numeric; bidx numeric; best numeric;
begin
  for s in
    select sh.completed_on, sh.day, sh.log from public.session_history sh
     where sh.athlete_id = p_athlete and sh.hidden_at is null and jsonb_typeof(sh.log) = 'array'
       and sh.completed_on between coalesce(p_from, '-infinity'::date) and coalesce(p_to, 'infinity'::date)
       and (p_plan is null or sh.day::text = any (p_plan))
     order by sh.completed_on, sh.day
  loop
    eo := 0;
    for e in select x.value from jsonb_array_elements(s.log) x loop
      eo := eo + 1;
      if jsonb_typeof(e) <> 'object' or public.career_truthy(e -> 'circuit') or not public.career_truthy(e -> 'ex') then continue; end if;
      has_best := false; bw := null; bn := null; bng := false; br := null; bidx := null; best := null;
      for st in select y.value from jsonb_array_elements(case when jsonb_typeof(e -> 'sets') = 'array' then e -> 'sets' else '[]'::jsonb end) y loop
        -- histSetLogged(): a weight, an RPE or a tick
        if jsonb_typeof(st) <> 'object'
           or not (public.career_truthy(st -> 'w') or public.career_truthy(st -> 'r') or public.career_truthy(st -> 'd')) then
          continue;
        end if;
        w := public.career_kg(st -> 'w');
        if st ? 'n' and jsonb_typeof(st -> 'n') <> 'null' and not (jsonb_typeof(st -> 'n') = 'string' and st ->> 'n' = '') then
          n_given := true; n := public.career_js_num(st -> 'n');
        elsif public.career_truthy(e -> 'reps') then
          n_given := true; n := public.career_js_num(e -> 'reps');
        else
          n_given := false; n := null;
        end if;
        r := case when public.career_truthy(st -> 'r') then public.career_js_num(st -> 'r') end;
        rir := case when r >= 6 and r <= 10 then 10 - r else 0 end;
        idx := case when n is not null and n <> 0 then case when w is not null then w * (1 + (n + rir) / 30) else n + rir end end;
        if not has_best
           or (idx is not null and (bidx is null or idx > bidx))
           or (idx is null and bidx is null and r is not null and (br is null or r < br)) then
          has_best := true; bw := w; bn := n; bng := n_given; br := r; bidx := idx;
        end if;
        rpe := public.career_js_num(st -> 'r');
        est := null;
        if w is not null and n is not null and n > 0 and rpe > 0 then
          eff := n + greatest(0, 10 - rpe);
          if eff <= 10 then
            est := round((case when eff <= 1 then w else w * (1 + eff / 30) end) / 2.5) * 2.5;
          end if;
        end if;
        if est is not null and (best is null or est > best) then best := est; end if;
      end loop;
      if has_best then
        d := s.completed_on; plan_day := s.day; ord := eo; name := e ->> 'ex'; lift := public.career_norm(e ->> 'ex');
        b_w := bw; b_n := bn; b_n_given := bng; b_r := br; b_idx := bidx; best_est := best;
        return next;
      end if;
    end loop;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.career_facts_paid(p_athlete text)
 RETURNS TABLE(kind text, ref text, day date, xp numeric, career_only boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with r as (select public.career_rules_now() as j),
  f as (
    select f.kind, f.ref, f.day, f.value from public.career_facts f
     where f.athlete_id = p_athlete and f.void_at is null
       and f.kind not in ('habit_done', 'habit_day', 'day_on_target', 'perfect_day', 'workout_tick', 'comeback')
  ),
  priced as (
    select f.*,
           case when r.j -> 'fact' -> f.kind ->> 'xp_from' = 'value' then coalesce(public.career_num(f.value -> 'xp'), 0)
                else coalesce(public.career_num(r.j -> 'fact' -> f.kind -> 'xp'), 0) end as xp,
           coalesce(r.j -> 'fact' -> f.kind -> 'career_only' = 'true'::jsonb, false) as conly,
           r.j -> 'fact' -> f.kind ->> 'limit_per' as per,
           coalesce(public.career_num(r.j -> 'fact' -> f.kind -> 'limit'), 0) as lim
      from f, r
  ),
  weeks as (select * from public.career_weeks(p_athlete)),
  keyed as (
    select p.*,
           case p.per
             when 'plan_day_week' then
               coalesce((select 'c' || w.cycle_num || '|w' || w.week from weeks w
                          where p.day between w.wfrom and w.wto and (p.value ->> 'plan_day') = any (w.plan)
                          order by w.cstart desc limit 1),
                        'iso:' || to_char(p.day, 'IYYY-IW')) || '|d' || coalesce(p.value ->> 'plan_day', '')
             when 'week' then 'iso:' || to_char(p.day, 'IYYY-IW')
             when 'cycle' then split_part(p.ref, '|', 1)
           end as grp
      from priced p
  ),
  ranked as (
    select k.*, row_number() over (partition by case when k.per = 'plan_day_week' then 'session' else k.kind end, k.grp
                                   order by k.xp desc, k.day, k.ref) as rn
      from keyed k
  )
  select ranked.kind, ranked.ref, ranked.day, ranked.xp, ranked.conly
    from ranked
   where ranked.grp is null or ranked.rn <= ranked.lim
$function$;

CREATE OR REPLACE FUNCTION public.career_facts_xp(p_athlete text, p_from date, p_to date)
 RETURNS TABLE(kind text, n bigint, xp numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select p.kind, count(*), sum(p.xp)
    from public.career_facts_paid(p_athlete) p
   where p.day between coalesce(p_from, '-infinity'::date) and coalesce(p_to, 'infinity'::date)
     and not (p.career_only and p_from is not null)
   group by p.kind
$function$;

CREATE OR REPLACE FUNCTION public.career_habit_days(p_athlete text)
 RETURNS TABLE(d date, ndone integer, nlive integer, on_target boolean, perfect boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
with
  rr as (select public.career_habit_rules() as p_rules),
  bonusmult as (
    select coalesce((rr.p_rules ->> 'customXp')::numeric, 25) as cx,
           coalesce((rr.p_rules ->> 'streakQualifyPct')::numeric, 80) as qpct,
           coalesce((rr.p_rules ->> 'gateV2')::boolean, false) as gate2
      from rr
  ),
  hday as (
    select f.day, f.value from public.career_facts f
     where f.athlete_id = p_athlete and f.kind = 'habit_day' and f.void_at is null
  ),
  dl as (
    select h.day as d,
           coalesce((select jsonb_object_agg(substr(x.ref, 12), x.value -> 'v') from public.career_facts x
                      where x.athlete_id = p_athlete and x.kind = 'habit_done' and x.void_at is null and x.day = h.day),
                    '{}'::jsonb) as vals,
           h.value -> 'live' as ids
      from hday h
  ),
  lastday as (select h.value from hday h order by h.day desc limit 1),
  habits as (
    select t.key as hid, t.value::numeric as tgt, b.cx as fallback
      from rr, jsonb_each_text(coalesce(rr.p_rules -> 'targets', '{}'::jsonb)) t, bonusmult b
    union all
    select c.value, 1::numeric, b.cx
      from lastday, jsonb_array_elements_text(coalesce(lastday.value -> 'custom', '[]'::jsonb)) c, bonusmult b
  ),
  weighted as (
    select h.hid, h.tgt, coalesce((rr.p_rules -> 'weights' ->> h.hid)::numeric, h.fallback) as w
      from habits h, rr
  ),
  daylive as (
    select dl.d, w.hid, w.tgt, w.w,
           jsonb_exists(coalesce(rr.p_rules -> 'unearnable', '[]'::jsonb), w.hid) as lockd
      from dl cross join weighted w cross join rr
     where jsonb_exists(dl.ids, w.hid)
  ),
  perday as (
    select dl.d, dl.vals,
           count(dv.hid) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt)::int as ndone,
           count(dv.hid)::int as nlive,
           coalesce(sum(dv.w) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt), 0) as wdone,
           coalesce(sum(dv.w) filter (
             where (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                    and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
                or not dv.lockd), 0) as glive,
           coalesce(sum(
             case when jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt
                  then dv.w
                  when dv.lockd then 0
                  when dv.tgt > 0 and jsonb_typeof(dl.vals -> dv.hid) = 'number'
                       and (dl.vals ->> dv.hid)::numeric > 0
                  then dv.w * least((dl.vals ->> dv.hid)::numeric / dv.tgt, 1)
                  else 0 end), 0) as gpart,
           count(dv.hid) filter (
             where not (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
               and not dv.lockd)::int as gmiss
    from dl left join daylive dv on dv.d = dl.d
    group by dl.d, dl.vals
  ),
  qualday as (
    select p.d
    from perday p, bonusmult b
    where case when b.gate2
               then (p.glive > 0 and round(p.gpart / p.glive * 100) >= b.qpct)
                     or (p.gmiss <= 1 and p.gpart > 0)
               else p.glive > 0 and round(p.wdone / p.glive * 100) >= b.qpct
          end
  )
select p.d, p.ndone, p.nlive, (q.d is not null), (p.nlive > 0 and p.ndone >= p.nlive)
  from perday p left join qualday q on q.d = p.d
$function$;

CREATE OR REPLACE FUNCTION public.career_habit_rules()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with r as (select public.career_rules_now() as j),
  b as (select c.body from public.career_catalogue c where c.kind = 'badge' and c.body ->> 'origin' = 'proof'),
  a as (select c.body from public.career_catalogue c where c.kind = 'achievement' and c.body ->> 'origin' = 'proof'),
  m as (select c.body from public.career_catalogue c where c.kind = 'mission' and c.body ->> 'origin' = 'proof')
  select case when r.j is null then null else jsonb_build_object(
    'completionBonus',  r.j #> '{habits,completion_bonus}',
    'customXp',         r.j #> '{habits,weights,custom}',
    'maxCustom',        r.j #> '{habits,max_custom}',
    'weights',          coalesce(r.j #> '{habits,weights}', '{}'::jsonb) - 'custom',
    'targets',          coalesce(r.j #> '{habits,targets}', '{}'::jsonb),
    'streakQualifyPct', r.j #> '{habits,qualify_pct}',
    'gateV2',           r.j #> '{habits,one_miss_door}',
    'unearnable',       coalesce(r.j #> '{habits,locked}', '[]'::jsonb),
    'lapseDays',        r.j #> '{habits,lapse_days}',
    'comebackXp',       r.j #> '{fact,comeback,xp}',
    'comebackStick',    r.j #> '{habits,comeback_stick}',
    'tiers', coalesce((select jsonb_agg(jsonb_build_object('days', t.value -> 'at', 'mult', t.value -> 'mult') order by t.ord)
                         from b, jsonb_array_elements(b.body -> 'tiers') with ordinality t(value, ord)
                        where b.body ->> 'kind' = 'per_habit_best_run'), '[]'::jsonb),
    'milestones', coalesce((select jsonb_agg(x.ms) from (
                     select jsonb_build_object('code', b.body -> 'proof_codes' -> (t.ord - 1)::int, 'need', t.value -> 'at',
                                               'xp', t.value -> 'xp', 'measure', b.body -> 'proof_measure') as ms
                       from b, jsonb_array_elements(b.body -> 'tiers') with ordinality t(value, ord)
                      where b.body ? 'proof_measure'
                     union all
                     select jsonb_build_object('code', a.body -> 'proof_code', 'need', a.body -> 'proof_need',
                                               'xp', a.body -> 'xp', 'measure', a.body -> 'proof_measure')
                       from a where a.body ? 'proof_measure') x), '[]'::jsonb),
    'quests', coalesce((select jsonb_agg(jsonb_build_object('id', m.body -> 'proof_id', 'kind', m.body -> 'proof_kind',
                                                            'need', m.body -> 'proof_need', 'xp', m.body -> 'proof_xp'))
                          from m where m.body ? 'proof_kind'), '[]'::jsonb),
    'questRuns', coalesce((select x.rules -> 'questRuns' from public.xp_rules x where x.id = 1), '[]'::jsonb)
  ) end
  from r
$function$;

CREATE OR REPLACE FUNCTION public.career_js_num(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text;
begin
  if p is null then return null; end if;
  case jsonb_typeof(p)
    when 'number' then return (p #>> '{}')::numeric;
    when 'boolean' then return case when p = 'true'::jsonb then 1 else 0 end;
    when 'null' then return 0;
    when 'string' then
      t := btrim(p #>> '{}');
      if t = '' then return 0; end if;
      if t ~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$' then return t::numeric; end if;
      return null;
    else return null;
  end case;
end $function$;

CREATE OR REPLACE FUNCTION public.career_keep_levels(p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now(); a record; v_rows jsonb := '[]'::jsonb;
  v_record integer; v_now integer; v_best integer; v_xp bigint; v_raw bigint; v_lv integer; v_kept bigint; v_had jsonb;
begin
  if v_rules is null or public.career_switch_day(v_rules, 'xp') is null then
    raise exception 'career_keep_levels: the XP switch is not on (rulebook.toml → [switch] xp)';
  end if;
  for a in
    select z.id,
           coalesce(nullif(btrim(concat_ws(' ', p.data #>> '{athlete,firstName}', p.data #>> '{athlete,lastName}')), ''), o.display_name) as name,
           exists (select 1 from public.athlete_progress ap where ap.athlete_id = z.id and ap.data ? (z.id || '_hab_log')) as has_log
      from (select ap.athlete_id as id from public.athlete_progress ap where ap.data ? (ap.athlete_id || '_hab_log')
            union select r.athlete_id from public.hab_season_results r
            union select f.athlete_id from public.career_facts f where f.void_at is null) z
      left join public.programs p on p.athlete_id = z.id
      left join public.leaderboard_optin o on o.athlete_id = z.id
     order by z.id
  loop
    v_record := (select max(r.level) from public.hab_season_results r where r.athlete_id = a.id);
    v_now := case when a.has_log then public.hab_proof_level(a.id) end;
    v_best := greatest(coalesce(v_record, 0), coalesce(v_now, 0));
    select f.value into v_had from public.career_facts f
     where f.athlete_id = a.id and f.kind = 'level_kept' and f.ref = 'xp-switch' and f.void_at is null;
    v_xp := coalesce((public.career_score(a.id, null, null, current_date) ->> 'xp')::bigint, 0);
    v_raw := v_xp - coalesce(public.career_num(v_had -> 'xp'), 0)::bigint;          -- the career without the level kept
    v_lv := (public.career_level(v_raw, v_rules) ->> 'level')::int;
    v_kept := coalesce(public.career_num(v_had -> 'xp'), 0)::bigint;
    if v_had is null and v_best > v_lv then
      v_kept := public.career_level_floor(v_best, v_rules) - v_raw;
      insert into public.career_facts (athlete_id, kind, ref, day, value, source)
      values (a.id, 'level_kept', 'xp-switch', p_day,
              jsonb_strip_nulls(jsonb_build_object('xp', v_kept, 'level', v_best, 'was', v_lv,
                                                   'proof_record', v_record, 'proof_now', v_now)), 'server')
      on conflict (athlete_id, kind, ref) do update
         set day = excluded.day, value = excluded.value, source = excluded.source, void_at = null, updated_at = now();
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'athlete_id', a.id, 'name', a.name, 'proof_now', v_now, 'proof_record', v_record,
      'career_xp', v_raw, 'career_level', v_lv, 'kept_xp', nullif(v_kept, 0),
      'level', (public.career_level(v_raw + v_kept, v_rules) ->> 'level')::int)));
  end loop;
  return v_rows;
end $function$;

CREATE OR REPLACE FUNCTION public.career_kg(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text; m text[]; k numeric;
begin
  if p is null or jsonb_typeof(p) not in ('string', 'number') then return null; end if;
  if not public.career_truthy(p) then return null; end if;        -- String(v || ''): 0 and '' read as nothing
  t := regexp_replace(public.career_digits(p #>> '{}'), ',', '.');  -- the first comma only, as String.replace does
  m := regexp_match(t, '^\s*([1-4])\s*[×xX*]\s*([0-9]+(?:\.[0-9]+)?)');
  if m is not null then
    k := m[2]::numeric;
    return case when k > 0 then k end;
  end if;
  m := regexp_match(t, '[0-9]+(?:\.[0-9]+)?');
  if m is null then return null; end if;
  k := m[1]::numeric;
  return case when k > 0 then k end;
end $function$;

CREATE OR REPLACE FUNCTION public.career_level(p_xp bigint, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_base numeric := coalesce(public.career_num(p_rules #> '{level,base}'), 300);
  v_growth numeric := coalesce(public.career_num(p_rules #> '{level,growth}'), 0.55);
  v_per integer := greatest(1, coalesce(public.career_num(p_rules #> '{level,levels_per_rank}')::int, 5));
  v_prestige integer := greatest(1, coalesce(public.career_num(p_rules #> '{level,prestige_after}')::int, 50));
  v_ranks jsonb := coalesce(p_rules #> '{level,ranks}', '[]'::jsonb);
  v_xp numeric := greatest(coalesce(p_xp, 0), 0);
  lv integer := 1; spent numeric := 0; cost numeric; i integer; star integer; within integer; nm text;
begin
  cost := greatest(10, round(v_base * power(1, v_growth) / 10) * 10);
  while lv < 100000 and v_xp - spent >= cost loop
    spent := spent + cost;
    lv := lv + 1;
    cost := greatest(10, round(v_base * power(lv, v_growth) / 10) * 10);
  end loop;
  i := lv - 1; star := i / v_prestige; within := i % v_prestige;
  nm := coalesce(v_ranks ->> least(within / v_per, greatest(jsonb_array_length(v_ranks) - 1, 0)), '');
  return jsonb_build_object('level', lv,
                            'rank', case when star > 0 then '★' || star || ' ' else '' end || nm || ' ' || (within % v_per + 1),
                            'xp_in_level', (v_xp - spent)::bigint, 'level_cost', cost::bigint, 'to_next', (cost - (v_xp - spent))::bigint);
end $function$;

CREATE OR REPLACE FUNCTION public.career_level_floor(p_level integer, p_rules jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_base numeric := coalesce(public.career_num(p_rules #> '{level,base}'), 300);
  v_growth numeric := coalesce(public.career_num(p_rules #> '{level,growth}'), 0.55);
  lv integer := 1; total numeric := 0;
begin
  while lv < least(coalesce(p_level, 1), 100000) loop
    total := total + greatest(10, round(v_base * power(lv, v_growth) / 10) * 10);
    lv := lv + 1;
  end loop;
  return total::bigint;
end $function$;

CREATE OR REPLACE FUNCTION public.career_lift_gains(p_athlete text)
 RETURNS TABLE(lift text, name text, pct numeric, d date)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  x record; v_cur text := null; v_out jsonb := '[]'::jsonb;
  a_name text; a_w numeric; a_n numeric; a_ng boolean; a_idx numeric; best_idx numeric; best_d date;
begin
  for x in
    select es.* from public.career_entry_sets(p_athlete, null, null, null) es
     where es.lift <> '' order by es.lift, es.d, es.plan_day, es.ord
  loop
    if v_cur is distinct from x.lift then
      if v_cur is not null and best_idx is not null then
        v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'p', round((best_idx / a_idx - 1) * 100, 1), 'dd', best_d));
      end if;
      v_cur := x.lift; a_name := x.name; a_w := x.b_w; a_n := x.b_n; a_ng := x.b_n_given; a_idx := x.b_idx;
      best_idx := null; best_d := null;
    elsif a_ng and x.b_n_given and coalesce(a_idx, 0) > 0 and coalesce(x.b_idx, 0) > a_idx and x.b_idx > coalesce(best_idx, 0)
          and ((a_w is null) = (x.b_w is null))
          and ((a_w is not null and round((x.b_w - a_w) * 2) / 2 > 0) or coalesce(x.b_n, 0) > coalesce(a_n, 0)) then
      best_idx := x.b_idx; best_d := x.d;
    end if;
  end loop;
  if v_cur is not null and best_idx is not null then
    v_out := v_out || jsonb_build_array(jsonb_build_object('l', v_cur, 'nm', a_name, 'p', round((best_idx / a_idx - 1) * 100, 1), 'dd', best_d));
  end if;
  return query select y.l, y.nm, y.p, y.dd from jsonb_to_recordset(v_out) as y(l text, nm text, p numeric, dd date);
end $function$;

CREATE OR REPLACE FUNCTION public.career_log(p_athlete text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(x.day::text, x.vals), '{}'::jsonb)
    from (select d.day,
                 coalesce((select jsonb_object_agg(substr(f.ref, 12), f.value -> 'v') from public.career_facts f
                            where f.athlete_id = p_athlete and f.kind = 'habit_done' and f.void_at is null and f.day = d.day),
                          '{}'::jsonb) as vals
            from (select distinct f.day from public.career_facts f
                   where f.athlete_id = p_athlete and f.kind in ('habit_day', 'habit_done') and f.void_at is null) d) x
$function$;

CREATE OR REPLACE FUNCTION public.career_norm(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select btrim(regexp_replace(lower(coalesce(p, '')), '\s+', ' ', 'g'))
$function$;

CREATE OR REPLACE FUNCTION public.career_num(p jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare t text;
begin
  if p is null then return null; end if;
  if jsonb_typeof(p) = 'number' then return (p #>> '{}')::numeric; end if;
  if jsonb_typeof(p) = 'string' then
    t := btrim(p #>> '{}');
    if t ~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)$' then return t::numeric; end if;
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_observe_library(p_athlete text, p_slug text DEFAULT NULL::text, p_on date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_want jsonb;
begin
  if public.career_rules_now() is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  select coalesce(jsonb_agg(jsonb_build_object('kind', 'library_session', 'ref', ls.slug || '|' || ls.completed_on::text,
                                               'day', ls.completed_on,
                                               'value', jsonb_strip_nulls(jsonb_build_object('slug', ls.slug, 'counts_as', ls.counts_as,
                                                                                             'minutes', ls.duration_min)))), '[]'::jsonb)
    into v_want
    from public.library_sessions ls
   where ls.athlete_id = p_athlete and (p_slug is null or (ls.slug = p_slug and ls.completed_on = p_on));
  perform public.career_sync(p_athlete, array['library_session'], v_want, 'training',
                             case when p_slug is null then null else array[p_slug || '|' || p_on::text] end);
end $function$;

CREATE OR REPLACE FUNCTION public.career_observe_proof(p_athlete text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := public.career_rules_now();
  v_data jsonb; v_log jsonb; v_cfg jsonb; v_want jsonb;
begin
  if v_rules is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  select a.data into v_data from public.athlete_progress a where a.athlete_id = p_athlete;
  v_log := public.hab_log_of(v_data, p_athlete);
  if jsonb_typeof(v_log) is distinct from 'object' then v_log := '{}'::jsonb; end if;
  v_cfg := public.hab_cfg_of(v_data, p_athlete);
  if jsonb_typeof(v_cfg) is distinct from 'object' then v_cfg := '{}'::jsonb; end if;

  with dl as (
    select public.career_day(e.key) as d, e.value as vals
      from jsonb_each(v_log) e
     where e.key ~ '^\d{4}-\d{2}-\d{2}$' and jsonb_typeof(e.value) = 'object' and public.career_day(e.key) is not null
  ),
  hv as (select dl.d, h.key as hid, h.value as v from dl, jsonb_each(dl.vals) h),
  weighted as (
    select t.key as hid from jsonb_each(coalesce(v_rules #> '{habits,targets}', '{}'::jsonb)) t
    union all
    select c.value ->> 'id'
      from jsonb_array_elements(case when jsonb_typeof(v_cfg -> 'custom') = 'array' then v_cfg -> 'custom' else '[]'::jsonb end) c
     where c.value ->> 'id' is not null
  ),
  roster as (
    select r.value
      from jsonb_array_elements(case when jsonb_typeof(v_cfg -> 'roster') = 'array' then v_cfg -> 'roster' else '[]'::jsonb end) r(value)
  ),
  dayroster as (
    select dl.d,
           (select r.value -> 'ids' from roster r
             where public.career_day(r.value ->> 'from') <= dl.d
             order by public.career_day(r.value ->> 'from') desc limit 1) as ids
      from dl
  ),
  custom as (
    select coalesce(jsonb_agg(c.value ->> 'id'), '[]'::jsonb) as ids
      from jsonb_array_elements(case when jsonb_typeof(v_cfg -> 'custom') = 'array' then v_cfg -> 'custom' else '[]'::jsonb end) c
     where c.value ->> 'id' is not null
  ),
  onlist as (
    select coalesce(jsonb_agg(w.hid), '[]'::jsonb) as ids from weighted w where coalesce(v_cfg -> 'on' ->> w.hid, 'true') <> 'false'
  )
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_want from (
    select jsonb_build_object('kind', 'habit_done', 'ref', hv.d::text || '|' || hv.hid, 'day', hv.d,
                              'value', jsonb_build_object('v', hv.v)) as x
      from hv
    union all
    select jsonb_build_object('kind', 'habit_day', 'ref', dr.d::text, 'day', dr.d,
                              'value', jsonb_build_object('live', case when dr.ids is not null then dr.ids else o.ids end,
                                                          'custom', c.ids))
      from dayroster dr, onlist o, custom c
    union all
    select jsonb_build_object('kind', 'workout_tick', 'ref', hv.d::text, 'day', hv.d, 'value', jsonb_build_object('habit', hv.hid))
      from hv
     where jsonb_typeof(hv.v) = 'number'
       and jsonb_exists(coalesce(v_rules #> '{habits,locked}', '[]'::jsonb), hv.hid)
       and (hv.v #>> '{}')::numeric >= coalesce(public.career_num(v_rules #> array['habits', 'targets', hv.hid]), 1)
  ) s;
  perform public.career_sync(p_athlete, array['habit_done', 'habit_day', 'workout_tick'], v_want, 'proof', null,
                             public.career_settled_before(v_rules));
  perform public.career_derive_days(p_athlete);
end $function$;

CREATE OR REPLACE FUNCTION public.career_observe_session(p_athlete text, p_day integer DEFAULT NULL::integer, p_on date DEFAULT NULL::date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if public.career_rules_now() is null or p_athlete is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('career:' || p_athlete));
  perform public.career_sync(p_athlete, array['session_finished', 'session_finished_early', 'full_log', 'checkin_done'],
                             public.career_session_want(p_athlete, p_day, p_on), 'training',
                             case when p_day is null then null else array['d' || p_day || '|' || p_on::text] end);
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_library()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if tg_op in ('UPDATE', 'DELETE') then
      perform public.career_observe_library(old.athlete_id, old.slug, old.completed_on);
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      perform public.career_observe_library(new.athlete_id, new.slug, new.completed_on);
    end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not read a Library session of %: % (%). The save itself went through.',
                  coalesce(new.athlete_id, old.athlete_id), sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_programme()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    perform public.career_derive(new.athlete_id);
  exception when others then
    raise warning 'Career Mode (shadow) could not read the programme of %: % (%). The save itself went through.',
                  new.athlete_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id text := coalesce(new.athlete_id, old.athlete_id); v_habits boolean := true; v_records boolean := true;
begin
  if tg_op = 'UPDATE' and new.athlete_id = old.athlete_id then
    v_habits := (new.data -> (v_id || '_hab_log')) is distinct from (old.data -> (v_id || '_hab_log'))
             or (new.data -> (v_id || '_hab_cfg')) is distinct from (old.data -> (v_id || '_hab_cfg'));
    v_records := (new.data -> (v_id || '_1rm')) is distinct from (old.data -> (v_id || '_1rm'));
    if not v_habits and not v_records then return null; end if;
  end if;
  begin
    if tg_op = 'UPDATE' and new.athlete_id is distinct from old.athlete_id then
      perform public.career_observe_proof(old.athlete_id);
    end if;
    if v_habits then perform public.career_observe_proof(v_id); end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not read the Proof log of %: % (%). The save itself went through.', v_id, sqlerrm, sqlstate;
  end;
  begin
    if tg_op = 'UPDATE' and new.athlete_id is distinct from old.athlete_id then
      perform public.career_derive(old.athlete_id);
    end if;
    if v_records then perform public.career_derive(v_id); end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not work out the training facts of %: % (%). The save itself went through.', v_id, sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_on_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  begin
    if tg_op in ('UPDATE', 'DELETE') then
      perform public.career_observe_session(old.athlete_id, old.day, old.completed_on);
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      perform public.career_observe_session(new.athlete_id, new.day, new.completed_on);
    end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not read a session of %: % (%). The save itself went through.',
                  coalesce(new.athlete_id, old.athlete_id), sqlerrm, sqlstate;
  end;
  begin
    if tg_op in ('INSERT', 'UPDATE') then
      perform public.career_derive(new.athlete_id);
    end if;
    if tg_op = 'DELETE' or (tg_op = 'UPDATE' and new.athlete_id is distinct from old.athlete_id) then
      perform public.career_derive(old.athlete_id);
    end if;
  exception when others then
    raise warning 'Career Mode (shadow) could not work out the training facts of %: % (%). The save itself went through.',
                  coalesce(new.athlete_id, old.athlete_id), sqlerrm, sqlstate;
  end;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.career_paid_rules(p_habit_rules jsonb, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when p_habit_rules is null or public.career_switch_day(p_rules, 'xp') is null then p_habit_rules
              else jsonb_set(p_habit_rules, '{weights}',
                             coalesce(p_habit_rules -> 'weights', '{}'::jsonb)
                             || coalesce((select jsonb_object_agg(l.value, 0)
                                            from jsonb_array_elements_text(case when jsonb_typeof(p_habit_rules -> 'unearnable') = 'array'
                                                                                then p_habit_rules -> 'unearnable' else '[]'::jsonb end) l),
                                         '{}'::jsonb)) end
$function$;

CREATE OR REPLACE FUNCTION public.career_probe(p_log jsonb, p_cfg jsonb, p_season date, p_to date, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_base jsonb; v_days integer := greatest(p_to - p_season + 1, 0); v_perfect bigint; v_on bigint; v_back bigint;
begin
  v_base := p_rules || jsonb_build_object('tiers', '[]'::jsonb, 'milestones', '[]'::jsonb, 'quests', '[]'::jsonb,
                                          'questRuns', '[]'::jsonb, 'comebackXp', 0);
  v_perfect := public.hab_bonus_xp(p_log, p_cfg, p_season, p_season, p_to,
                 v_base || jsonb_build_object('milestones', (select coalesce(jsonb_agg(jsonb_build_object('code', 'zzp' || g, 'need', g,
                                                             'xp', 1, 'measure', 'perfectDays')), '[]'::jsonb)
                                                               from generate_series(1, v_days) g)));
  v_on := public.hab_bonus_xp(p_log, p_cfg, p_season, p_season, p_to,
            v_base || jsonb_build_object(
              'quests', (select jsonb_agg(jsonb_build_object('id', 'zzq' || g, 'kind', 'qualify', 'need', g, 'xp', 1)) from generate_series(1, 7) g),
              'questRuns', (select coalesce(jsonb_agg(jsonb_build_object('start', (p_season + 7 * k)::text,
                                                                         'ids', (select jsonb_agg('zzq' || g) from generate_series(1, 7) g))), '[]'::jsonb)
                              from generate_series(0, v_days / 7) k)));
  v_back := public.hab_bonus_xp(p_log, p_cfg, p_season, p_season, p_to, v_base || jsonb_build_object('comebackXp', 1));
  return jsonb_build_object('perfect', v_perfect, 'on_target', v_on, 'comebacks', v_back);
end $function$;

CREATE OR REPLACE FUNCTION public.career_rules_now()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select r.rules from public.career_rules r order by r.version desc limit 1
$function$;

CREATE OR REPLACE FUNCTION public.career_score(p_athlete text, p_season date, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb := public.career_habit_rules(); v_paid jsonb; v_log jsonb; v_cfg jsonb; v_daily bigint := 0; v_bonus bigint := 0;
        v_facts jsonb; v_rest numeric;
begin
  if v_rules is null then return null; end if;
  v_paid := public.career_paid_rules(v_rules, public.career_rules_now());
  v_log := public.career_log(p_athlete);
  v_cfg := public.career_cfg(p_athlete);
  v_daily := public.hab_xp(v_log, p_from, p_to, v_paid);
  v_bonus := public.hab_bonus_xp(v_log, v_cfg, p_season, p_from, p_to, v_rules);
  select coalesce(jsonb_object_agg(x.kind, jsonb_build_object('n', x.n, 'xp', x.xp)), '{}'::jsonb), coalesce(sum(x.xp), 0)
    into v_facts, v_rest
    from public.career_facts_xp(p_athlete, p_from, p_to) x;
  return jsonb_build_object('habits', jsonb_build_object('daily', v_daily, 'bonus', v_bonus, 'xp', v_daily + v_bonus),
                            'facts', v_facts, 'facts_xp', round(v_rest)::bigint,
                            'xp', (v_daily + v_bonus + round(v_rest))::bigint);
end $function$;

CREATE OR REPLACE FUNCTION public.career_scored(p_athlete text, p_recompute boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare v_stamp text; v_old text; v_score jsonb;
begin
  if p_athlete is null or public.career_rules_now() is null then return null; end if;
  v_stamp := public.career_stamp(p_athlete);
  select c.stamp, c.score into v_old, v_score from public.career_scores c where c.athlete_id = p_athlete;
  if v_old = v_stamp then return v_score; end if;
  if v_old is not null and not p_recompute then return v_score || '{"stale": true}'::jsonb; end if;
  v_score := public.career_compute(p_athlete);
  if v_score is null then return null; end if;
  insert into public.career_scores as c (athlete_id, stamp, score, updated_at) values (p_athlete, v_stamp, v_score, now())
  on conflict on constraint career_scores_pkey do update set stamp = excluded.stamp, score = excluded.score, updated_at = now();
  return v_score;
end $function$;

CREATE OR REPLACE FUNCTION public.career_scores_for(p_ids text[], p_budget interval DEFAULT '00:00:02.5'::interval)
 RETURNS TABLE(athlete_id text, score jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
declare v_t0 timestamptz := clock_timestamp(); v_id text; v_stamp text; v_old text; v_cached jsonb; v_score jsonb;
begin
  if public.career_rules_now() is null then return; end if;
  for v_id in select distinct x.id from unnest(coalesce(p_ids, '{}'::text[])) as x(id) where x.id is not null order by 1 loop
    v_stamp := public.career_stamp(v_id);
    v_old := null; v_cached := null;
    select c.stamp, c.score into v_old, v_cached from public.career_scores c where c.athlete_id = v_id;
    if v_old is not null and (v_old = v_stamp or clock_timestamp() - v_t0 > p_budget) then
      athlete_id := v_id; score := v_cached; return next;
      continue;
    end if;
    v_score := public.career_compute(v_id);
    if v_score is null then continue; end if;
    insert into public.career_scores as c (athlete_id, stamp, score, updated_at) values (v_id, v_stamp, v_score, now())
    on conflict on constraint career_scores_pkey do update set stamp = excluded.stamp, score = excluded.score, updated_at = now();
    athlete_id := v_id; score := v_score; return next;
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public.career_scoring(p_key text, p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when jsonb_typeof(p) = 'array' and p_key = 'milestones' then
      (select coalesce(jsonb_agg(jsonb_build_object('code', e.v -> 'code', 'need', e.v -> 'need', 'xp', e.v -> 'xp', 'measure', e.v -> 'measure')), '[]'::jsonb)
         from jsonb_array_elements(p) as e(v))
    when jsonb_typeof(p) = 'array' and p_key = 'quests' then
      (select coalesce(jsonb_agg(jsonb_build_object('id', e.v -> 'id', 'kind', e.v -> 'kind', 'need', e.v -> 'need', 'xp', e.v -> 'xp')), '[]'::jsonb)
         from jsonb_array_elements(p) as e(v))
    when jsonb_typeof(p) = 'array' and p_key = 'tiers' then
      (select coalesce(jsonb_agg(jsonb_build_object('days', e.v -> 'days', 'mult', e.v -> 'mult')), '[]'::jsonb)
         from jsonb_array_elements(p) as e(v))
    else p end
$function$;

CREATE OR REPLACE FUNCTION public.career_seed(p_version integer, p_rules jsonb, p_catalogue jsonb, p_source text, p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_newest integer; v_n integer; v_old jsonb := public.career_rules_now(); v_which text; v_was date; v_will text;
  v_xp_on date; v_turn_on boolean; v_same boolean; v_backfill jsonb; v_levels jsonb; v_out jsonb;
begin
  if p_version is null or p_version < 1 then
    raise exception 'the rulebook version must be a whole number from 1';
  end if;
  if jsonb_typeof(p_rules) is distinct from 'object' or public.career_num(p_rules -> 'version') is distinct from p_version then
    raise exception 'the rulebook must be an object whose version is %', p_version;
  end if;
  if jsonb_typeof(p_catalogue) is distinct from 'array' then
    raise exception 'the catalogue must be a JSON array of {kind, id, body}';
  end if;
  select max(r.version) into v_newest from public.career_rules r;
  if v_newest is not null and p_version < v_newest then
    raise exception 'rulebook version % is older than the one loaded (%): nothing was changed', p_version, v_newest;
  end if;
  foreach v_which in array array['xp', 'catalogue'] loop
    v_will := p_rules #>> array['switch', v_which];
    v_was := public.career_switch_day(v_old, v_which);
    if v_will is not null and v_will <> 'off' and v_will !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'rulebook.toml → [switch] % must be "off" or a day (YYYY-MM-DD), found %: nothing was changed', v_which, v_will;
    end if;
    if v_will ~ '^\d{4}-\d{2}-\d{2}$' and v_will::date > current_date then
      raise exception 'rulebook.toml → [switch] % is %, a day still to come: turn a switch on on the day it happens. Nothing was changed', v_which, v_will;
    end if;
    if v_was is not null and coalesce(v_will, 'off') = 'off' then
      raise exception 'the % switch is on (since %) and is never turned back off: it would take every athlete''s level back. Nothing was changed (the way back is scripts/career/rollback_stage69.sql, on Amir''s word)', v_which, v_was;
    end if;
  end loop;
  if public.career_switch_day(p_rules, 'catalogue') is not null and public.career_switch_day(p_rules, 'xp') is null then
    raise exception 'the catalogue switch (phase 3) needs the XP switch (phase 2) on first: nothing was changed';
  end if;
  v_xp_on := public.career_switch_day(p_rules, 'xp');
  v_turn_on := v_xp_on is not null and public.career_switch_day(v_old, 'xp') is null;
  v_same := v_old is not null
        and (v_old - 'version' - 'switch' - 'shadow') = (p_rules - 'version' - 'switch' - 'shadow')
        and (select md5(coalesce(string_agg(c.kind || '|' || c.id || '|' || c.body::text, ',' order by c.kind, c.id), ''))
               from public.career_catalogue c)
          = (select md5(coalesce(string_agg(x.kind || '|' || x.id || '|' || x.body::text, ',' order by x.kind, x.id), ''))
               from jsonb_to_recordset(p_catalogue) as x(kind text, id text, body jsonb));

  begin
    insert into public.career_rules (version, rules, source, loaded_at) values (p_version, p_rules, p_source, now())
    on conflict (version) do update set rules = excluded.rules, source = excluded.source, loaded_at = now();
    delete from public.career_catalogue;
    insert into public.career_catalogue (kind, id, body, version, loaded_at)
    select x.kind, x.id, x.body, p_version, now()
      from jsonb_to_recordset(p_catalogue) as x(kind text, id text, body jsonb);
    get diagnostics v_n = row_count;
    v_backfill := case when v_same then jsonb_build_object('skipped', 'only a switch changed: no fact depends on it')
                       else public.career_backfill(null) end;
    if v_turn_on then
      v_levels := public.career_keep_levels(v_xp_on);
    end if;
    v_out := jsonb_strip_nulls(jsonb_build_object(
      'version', p_version, 'catalogue', v_n, 'backfill', v_backfill,
      'switch', jsonb_build_object('xp', coalesce(v_xp_on::text, 'off'),
                                   'catalogue', coalesce(public.career_switch_day(p_rules, 'catalogue')::text, 'off')),
      'turned_on', case when v_turn_on then 'xp' end,
      'levels', v_levels));
    if p_dry_run then
      raise exception using errcode = 'P0001', message = 'career_seed: dry run';
    end if;
  exception when sqlstate 'P0001' then
    if sqlerrm <> 'career_seed: dry run' then
      raise;
    end if;
    v_out := v_out || jsonb_build_object('dry_run', true, 'note', 'a dry run: everything above was worked out, then undone');
  end;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.career_session_want(p_athlete text, p_day integer DEFAULT NULL::integer, p_on date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with s as (
    select sh.day, sh.completed_on, sh.duration_min, sh.readiness, sh.log,
           'd' || sh.day || '|' || sh.completed_on::text as ref,
           regexp_match(coalesce(sh.status, ''), '^\s*partial\s*\(\s*(\d+)\s+of\s+(\d+)', 'i') as part,
           coalesce(sh.status, '') ~* '^\s*partial' as early
      from public.session_history sh
     where sh.athlete_id = p_athlete and sh.hidden_at is null
       and (p_day is null or (sh.day = p_day and sh.completed_on = p_on))
  ),
  ent as (      -- every set of every exercise of a structured log (a circuit logs rounds, not sets)
    select s.ref, e.o, st.v as st
      from s, jsonb_array_elements(case when jsonb_typeof(s.log) = 'array' then s.log else '[]'::jsonb end) with ordinality as e(v, o),
           jsonb_array_elements(case when jsonb_typeof(e.v) = 'object' and jsonb_typeof(e.v -> 'sets') = 'array'
                                     then e.v -> 'sets' else '[]'::jsonb end) as st(v)
  ),
  asks as (     -- the exercises whose card asks an RPE: the log does not carry the target, so one rated on any set asks it on all
    select ent.ref, ent.o from ent group by ent.ref, ent.o having bool_or(public.career_truthy(ent.st -> 'r'))
  ),
  logged as (
    select s.ref,
           jsonb_typeof(s.log) = 'array' and not s.early
           and exists (select 1 from ent where ent.ref = s.ref)
           and not exists (select 1 from ent where ent.ref = s.ref and not public.career_truthy(ent.st -> 'd'))
           and not exists (select 1 from ent join asks on asks.ref = ent.ref and asks.o = ent.o
                            where ent.ref = s.ref and not public.career_truthy(ent.st -> 'r')) as ok
      from s
  ),
  checkin as (
    select s.ref,
           jsonb_typeof(s.readiness) = 'object'
           and not public.career_truthy(s.readiness -> 'skipped')
           and exists (select 1 from unnest(array['composite', 'score', 'sleep', 'energy', 'soreness', 'stress', 'overall']) as k(key)
                        where jsonb_typeof(s.readiness -> k.key) = 'number') as ok
      from s
  )
  select coalesce(jsonb_agg(x), '[]'::jsonb) from (
    select jsonb_build_object('kind', case when s.early then 'session_finished_early' else 'session_finished' end,
                              'ref', s.ref, 'day', s.completed_on,
                              'value', jsonb_strip_nulls(jsonb_build_object('plan_day', s.day::text, 'minutes', s.duration_min,
                                                                            'done', (s.part)[1]::int, 'of', (s.part)[2]::int))) as x
      from s
    union all
    select jsonb_build_object('kind', 'full_log', 'ref', s.ref, 'day', s.completed_on, 'value', jsonb_build_object('plan_day', s.day::text))
      from s join logged l on l.ref = s.ref where l.ok
    union all
    select jsonb_build_object('kind', 'checkin_done', 'ref', s.ref, 'day', s.completed_on, 'value', jsonb_build_object('plan_day', s.day::text))
      from s join checkin c on c.ref = s.ref where c.ok
  ) z
$function$;

CREATE OR REPLACE FUNCTION public.career_settled_before(p_rules jsonb)
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case when public.career_switch_day(p_rules, 'xp') is null then null
              else current_date - (coalesce((p_rules #>> '{habits,backfill_days}')::int, 3) + 1) end
$function$;

CREATE OR REPLACE FUNCTION public.career_stamp(p_athlete text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select md5(concat_ws('|',
    (select r.version::text || '@' || r.loaded_at::text from public.career_rules r order by r.version desc limit 1),
    (select md5(coalesce(x.rules -> 'questRuns', '[]'::jsonb)::text) from public.xp_rules x where x.id = 1),
    (select s.starts_on::text from public.current_season() s),
    current_date::text,
    (select count(*)::text || '@' || coalesce(max(f.updated_at)::text, '-') from public.career_facts f where f.athlete_id = p_athlete),
    (select p.updated_at::text from public.programs p where p.athlete_id = p_athlete),
    (select count(*)::text || '@' || coalesce(max(v.saved_at)::text, '-') from public.program_versions v where v.athlete_id = p_athlete)))
$function$;

CREATE OR REPLACE FUNCTION public.career_switch_day(p_rules jsonb, p_which text)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v text := p_rules #>> array['switch', p_which]; d date;
begin
  if v is null or v !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  begin
    d := v::date;
  exception when others then
    return null;
  end;
  return case when d <= current_date then d end;
end $function$;

CREATE OR REPLACE FUNCTION public.career_sync(p_athlete text, p_kinds text[], p_want jsonb, p_source text, p_refs text[] DEFAULT NULL::text[], p_settled_before date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_up integer; v_gone integer;
begin
  with w as (
    select distinct on (x.kind, x.ref) x.kind, x.ref, x.day, coalesce(x.value, '{}'::jsonb) as value
      from jsonb_to_recordset(coalesce(p_want, '[]'::jsonb)) as x(kind text, ref text, day date, value jsonb)
     where x.kind = any (p_kinds) and x.ref is not null and x.day is not null
     order by x.kind, x.ref
  ), up as (
    insert into public.career_facts as f (athlete_id, kind, ref, day, value, source)
    select p_athlete, w.kind, w.ref, w.day, w.value, p_source from w
    on conflict (athlete_id, kind, ref) do update
       set day = excluded.day, value = excluded.value, source = excluded.source, void_at = null, updated_at = now()
     where (f.day is distinct from excluded.day or f.value is distinct from excluded.value
            or f.source is distinct from excluded.source or f.void_at is not null)
       and (p_settled_before is null or f.day >= p_settled_before)
    returning 1
  )
  select count(*) into v_up from up;

  with w as (
    select x.kind, x.ref
      from jsonb_to_recordset(coalesce(p_want, '[]'::jsonb)) as x(kind text, ref text, day date, value jsonb)
     where x.kind = any (p_kinds)
  ), gone as (
    update public.career_facts f set void_at = now(), updated_at = now()
     where f.athlete_id = p_athlete and f.kind = any (p_kinds) and f.void_at is null
       and (p_refs is null or f.ref = any (p_refs))
       and (p_settled_before is null or f.day >= p_settled_before)
       and not exists (select 1 from w where w.kind = f.kind and w.ref = f.ref)
    returning 1
  )
  select count(*) into v_gone from gone;
  return v_up + v_gone;
end $function$;

CREATE OR REPLACE FUNCTION public.career_truthy(p jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case jsonb_typeof(p)
           when 'boolean' then p = 'true'::jsonb
           when 'number' then (p #>> '{}')::numeric <> 0
           when 'string' then (p #>> '{}') <> ''
           when 'object' then true
           when 'array' then true
           else false end
$function$;

CREATE OR REPLACE FUNCTION public.career_weeks(p_athlete text)
 RETURNS TABLE(cycle_index integer, cycle_num integer, week integer, weeks integer, wfrom date, wto date, cstart date, cend date, plan text[], is_current boolean, is_last boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with p as (select pr.data from public.programs pr where pr.athlete_id = p_athlete),
  cur as (
    select p.data,
           case when jsonb_typeof(p.data -> 'currentCycleIndex') = 'number'
                     and public.career_num(p.data -> 'currentCycleIndex') = trunc(public.career_num(p.data -> 'currentCycleIndex'))
                then public.career_num(p.data -> 'currentCycleIndex')::int else 0 end as cci,
           case when jsonb_typeof(p.data -> 'cycles') = 'array' then p.data -> 'cycles' else '[]'::jsonb end as cycles,
           case when jsonb_typeof(p.data -> 'programHistory') = 'array' then p.data -> 'programHistory' else '[]'::jsonb end as hist
      from p
  ),
  c as (
    select (x.o - 1)::int as idx,
           coalesce(case when public.career_num(x.c -> 'num') = trunc(public.career_num(x.c -> 'num'))
                         then public.career_num(x.c -> 'num')::int end, x.o::int) as num,
           public.career_day(x.c ->> 'startDate') as s, public.career_day(x.c ->> 'endDate') as e,
           cur.cci, jsonb_array_length(cur.cycles) as ncyc, cur.data, cur.hist
      from cur, jsonb_array_elements(cur.cycles) with ordinality x(c, o)
  ),
  planned as (
    select c.*,
           case when c.idx = c.cci then
             (select array_agg(coalesce(y.d ->> 'id', y.o::text) order by y.o)
                from jsonb_array_elements(case when jsonb_typeof(c.data -> 'workouts' -> 'days') = 'array'
                                               then c.data -> 'workouts' -> 'days' else '[]'::jsonb end) with ordinality y(d, o))
           else coalesce(
             (select array_agg(coalesce(y.d ->> 'id', y.o::text) order by y.o)
                from (select v.data from public.program_versions v
                       where v.athlete_id = p_athlete and jsonb_typeof(v.data -> 'currentCycleIndex') = 'number'
                         and public.career_num(v.data -> 'currentCycleIndex') = c.idx
                       order by v.saved_at desc limit 1) lv,
                     jsonb_array_elements(case when jsonb_typeof(lv.data -> 'workouts' -> 'days') = 'array'
                                               then lv.data -> 'workouts' -> 'days' else '[]'::jsonb end) with ordinality y(d, o)),
             (select array_agg(g::text order by g)
                from (select h.v as h from jsonb_array_elements(c.hist) as h(v)
                       where h.v ->> 'id' = 'prog' || c.num limit 1) hp,
                     generate_series(1, case when jsonb_typeof(hp.h -> 'days') = 'array' then jsonb_array_length(hp.h -> 'days') else 0 end) g),
             (select array_agg(g::text order by g)
                from (select c.hist -> (c.cci - 1 - c.idx) as h where jsonb_array_length(c.hist) = c.cci) hp,
                     generate_series(1, case when jsonb_typeof(hp.h -> 'days') = 'array' then jsonb_array_length(hp.h -> 'days') else 0 end) g))
           end as plan
      from c
     where c.idx <= c.cci
  )
  select pl.idx, pl.num, k::int, t.tot, pl.s + 7 * (k - 1), least(pl.s + 7 * k - 1, pl.e), pl.s, pl.e, pl.plan,
         pl.idx = pl.cci, pl.idx = pl.ncyc - 1
    from planned pl
   cross join lateral (select greatest(1, round((pl.e - pl.s) / 7.0)::int) as tot) t
   cross join lateral generate_series(1, t.tot) k
   where pl.s is not null and pl.e is not null and pl.e >= pl.s and cardinality(pl.plan) > 0
$function$;

CREATE OR REPLACE FUNCTION public.career_win_gain(a_w numeric, a_n numeric, a_ng boolean, a_idx numeric, b_w numeric, b_n numeric, b_ng boolean, b_idx numeric, p_min numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_g numeric; v_dw numeric := 0; v_dn numeric;
begin
  if not a_ng or not b_ng then return null; end if;            -- a hold: only its RPE can move
  v_g := case when coalesce(a_idx, 0) <> 0 and coalesce(b_idx, 0) <> 0 then b_idx / a_idx - 1 else 0 end;
  if v_g < p_min then return null; end if;
  if not (a_w is not null and b_w is not null) and (a_w is not null or b_w is not null) then return null; end if;
  if a_w is not null and b_w is not null then v_dw := round((b_w - a_w) * 2) / 2; end if;   -- winText(): to the half kilo
  v_dn := coalesce(b_n, 0) - coalesce(a_n, 0);
  if not (v_dw > 0 or v_dn > 0) then return null; end if;
  return v_g;
end $function$;

CREATE OR REPLACE FUNCTION public.career_xp_on()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select public.career_switch_day(public.career_rules_now(), 'xp') is not null
$function$;

CREATE OR REPLACE FUNCTION public.check_discount(p_code text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select a.percent
    from public.affiliates a
   where a.active
     and a.code = upper(btrim(left(coalesce(p_code, ''), 64)))
   limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.claim_titles(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(title text, earned_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  perform public.hab_mint_titles(p_athlete_id);
  return query
    select t.title, t.earned_on from public.hab_titles t
    where t.athlete_id = p_athlete_id order by t.earned_on, t.title;
end; $function$;

CREATE OR REPLACE FUNCTION public.clear_quests(p_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text; v_runs jsonb; v_kept jsonb := '[]'::jsonb; r jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  v_key := to_char(p_start, 'YYYY-MM-DD');
  select coalesce(rules -> 'questRuns', '[]'::jsonb) into v_runs from public.xp_rules where id = 1;
  for r in select value from jsonb_array_elements(v_runs) loop
    if r ->> 'start' is distinct from v_key then v_kept := v_kept || jsonb_build_array(r); end if;
  end loop;
  update public.xp_rules
     set rules = jsonb_set(rules, '{questRuns}', v_kept), updated_at = now()
   where id = 1;
  return v_kept;
end; $function$;

CREATE OR REPLACE FUNCTION public.clear_used_first_passwords()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  begin
    update public.athlete_identities
       set initial_password = null, sent_at = coalesce(sent_at, new.last_sign_in_at)
     where user_id = new.id and initial_password is not null
       and password_set_at is not null and new.last_sign_in_at > password_set_at;
    update public.tps_accounts
       set initial_password = null, sent_at = coalesce(sent_at, new.last_sign_in_at)
     where user_id = new.id and initial_password is not null
       and password_set_at is not null and new.last_sign_in_at > password_set_at;
    update public.assess_accounts
       set initial_password = null, sent_at = coalesce(sent_at, new.last_sign_in_at)
     where user_id = new.id and initial_password is not null
       and password_set_at is not null and new.last_sign_in_at > password_set_at;
  exception when others then
    null;   -- never block a sign-in over bookkeeping
  end;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_delete_training_history(p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sessions integer; v_progress integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' then
    raise exception 'which athlete?';
  end if;
  with d as (delete from public.session_history where athlete_id = p_athlete_id returning 1)
    select count(*) into v_sessions from d;
  with d as (delete from public.athlete_progress where athlete_id = p_athlete_id returning 1)
    select count(*) into v_progress from d;
  return jsonb_build_object('sessions', v_sessions, 'progress', v_progress);
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_erase_person(p_kind text, p_key text, p_confirm text DEFAULT NULL::text, p_intake_ids uuid[] DEFAULT '{}'::uuid[], p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  -- Every table that holds a row under an athlete id, in the order they are emptied. A table that is missing here but has an
  -- athlete_id column is caught by the check near the end, which undoes everything and names it.
  -- The first four are in the order publish_cycle() and the dashboard's editor lock them (programs, its versions, the coaching log,
  -- its versions): the same order means the two can wait for each other but never deadlock, and an erasure that starts while a
  -- cycle is being published waits at programs, so the publish's new version rows are committed before they are deleted.
  c_athlete_tables constant text[] := array[
    'programs', 'program_versions', 'coaching_logs', 'coaching_log_versions',
    'session_history', 'athlete_progress', 'hab_notes', 'hab_titles', 'hab_season_results', 'leaderboard_optin',
    'library_sessions', 'messages', 'call_logs', 'cycle_reports', 'athlete_keys', 'hab_contacts', 'athlete_identities', 'athlete_status', 'career_facts', 'career_scores'];
  -- Not clients: the public demo, and the identity coach.html reads the board through (AMIR_ATHLETE_ID there).
  c_protected constant text[] := array['demo', 'amir_ardekani'];
  -- Arabic-Indic (U+0660-0669) and Persian (U+06F0-06F9) digits, and what they fold to.
  c_digits_from constant text := U&'\0660\0661\0662\0663\0664\0665\0666\0667\0668\0669\06F0\06F1\06F2\06F3\06F4\06F5\06F6\06F7\06F8\06F9';
  c_digits_to   constant text := '01234567890123456789';
  v_kind      text    := lower(btrim(coalesce(p_kind, '')));
  v_key       text    := btrim(coalesce(p_key, ''));
  v_word      text;                         -- what the coach must type to confirm
  v_shown     text;                         -- a name for the confirmation text
  v_user      uuid;
  v_users     uuid[]  := '{}';              -- the logins that go with the person
  v_counts    jsonb   := '{}'::jsonb;
  v_total     bigint  := 0;
  v_n         bigint;
  v_emails    text[]  := '{}';
  v_phones    text[]  := '{}';              -- the last 9 digits of each WhatsApp number on their contact record
  v_fullname  text;
  v_cands     jsonb   := '[]'::jsonb;       -- intake forms that look like theirs
  v_unlinked  jsonb   := '[]'::jsonb;       -- affiliate codes whose link to this athlete was cleared
  v_ids       uuid[]  := coalesce(p_intake_ids, '{}');
  v_log_id    bigint;
  v_result    jsonb;
  v_other     text;
  t           text;
  sch         text;
  v_col       text;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  -- NULL is neither a dry run nor a real run: "not null" is null, so every test of the flag below would be skipped while the deletes
  -- still ran and committed (found in review, 2026-10-11). Only an explicit true or false is accepted.
  if p_dry_run is null then
    raise exception 'p_dry_run must be true or false, not null. Nothing was erased.';
  end if;
  if v_kind not in ('athlete', 'course', 'testing') then
    raise exception 'Unknown kind of person "%": use athlete, course or testing.', v_kind;
  end if;
  if v_key = '' then
    raise exception 'Who? The id or username is empty.';
  end if;
  -- One erasure at a time (a double tap, two tabs): the second one waits, then finds nothing.
  perform pg_advisory_xact_lock(hashtext('coach_erase_person'));

  begin   -- everything that changes data is in this block; a dry run ends by raising ZZ100, which undoes all of it
    -- ── who is this, and which logins go with them ──────────────────────────────────────────────────────────────────────
    if v_kind = 'athlete' then
      if lower(v_key) = any (c_protected) then
        raise exception '"%" is not a client (the public demo, or the identity this dashboard reads the board through). It is never erased.', v_key;
      end if;
      v_word := v_key;
      -- The identity row for exactly this id, plus a sign-in on the internal address that NO identity row claims (the row was lost
      -- earlier). Ids are case-sensitive but GoTrue lower-cases the address, so a sign-in whose identity row names another id (a key
      -- typed in another case) is never taken: before this, typing ZZ_Case_A for zz_case_a deleted the login and left the data.
      select coalesce(array_agg(distinct x.id), '{}'::uuid[]) into v_users
        from (select i.user_id as id from public.athlete_identities i where i.athlete_id = v_key
              union
              select u.id from auth.users u
               where lower(u.email) = lower('athlete.' || v_key || '@amirardekani.com')
                 and not exists (select 1 from public.athlete_identities i2 where i2.user_id = u.id)) x;
      select nullif(btrim(concat_ws(' ', p.data -> 'athlete' ->> 'firstName', p.data -> 'athlete' ->> 'lastName')), '')
        into v_shown from public.programs p where p.athlete_id = v_key;
      if v_shown is null then
        select nullif(btrim(c.display_name), '') into v_shown from public.hab_contacts c where c.athlete_id = v_key;
      end if;
      if v_shown is null then
        select nullif(btrim(a.athlete_name), '') into v_shown from public.athlete_progress a where a.athlete_id = v_key;
      end if;
      v_shown := coalesce(v_shown, v_key);
      if exists (select 1 from public.tps_accounts a where a.user_id = any (v_users))
         or exists (select 1 from public.assess_accounts a where a.user_id = any (v_users)) then
        raise exception 'This athlete''s login is also a course or testing-app login. Nothing was erased: sort that out by hand first.';
      end if;
    elsif v_kind = 'course' then
      select a.user_id, a.username into v_user, v_word from public.tps_accounts a where lower(a.username) = lower(v_key);
      if v_user is null then
        raise exception 'There is no course login called "%". Nothing was erased.', v_key;
      end if;
      v_users := array[v_user];
      select nullif(btrim(n.note), '') into v_shown from public.buyer_notes n where n.user_id = v_user;
      v_shown := coalesce(v_shown, v_word);
      if exists (select 1 from public.athlete_identities i where i.user_id = v_user)
         or exists (select 1 from public.assess_accounts a where a.user_id = v_user) then
        raise exception 'This course login is also an athlete or testing-app login. Nothing was erased: sort that out by hand first.';
      end if;
    else
      select a.user_id, a.username into v_user, v_word from public.assess_accounts a where lower(a.username) = lower(v_key);
      if v_user is null then
        raise exception 'There is no testing-app login called "%". Nothing was erased.', v_key;
      end if;
      v_users := array[v_user];
      select nullif(btrim(n.note), '') into v_shown from public.buyer_notes n where n.user_id = v_user;
      v_shown := coalesce(v_shown, v_word);
      if exists (select 1 from public.athlete_identities i where i.user_id = v_user)
         or exists (select 1 from public.tps_accounts a where a.user_id = v_user) then
        raise exception 'This testing-app login is also an athlete or course login. Nothing was erased: sort that out by hand first.';
      end if;
    end if;

    if exists (select 1 from auth.users u
                where u.id = any (v_users)
                  and (lower(coalesce(u.email, '')) = 'amirardekanian@gmail.com' or u.id = auth.uid())) then
      raise exception 'That login is yours, the coach''s. Nothing was erased.';
    end if;

    -- ── the typed confirmation: a real run only ─────────────────────────────────────────────────────────────────────────
    if not p_dry_run and lower(btrim(coalesce(p_confirm, ''))) <> lower(v_word) then
      raise exception 'The confirmation does not match. Type exactly "%" to erase. Nothing was erased.', v_word;
    end if;

    -- ── athlete: the intake forms that look like theirs, then everything under the id ───────────────────────────────────
    if v_kind = 'athlete' then
      -- What identifies them: the emails and WhatsApp numbers on their contact record, and their full name as the programme spells it.
      -- A number is compared by its last 9 digits with Persian and Arabic-Indic digits folded to 0-9, so 0912…, +98912… and ۰۹۱۲… are one.
      select coalesce(array_agg(distinct lower(btrim(c.email))) filter (where nullif(btrim(c.email), '') is not null), '{}'::text[]),
             coalesce(array_agg(distinct right(d.digits, 9)) filter (where length(d.digits) >= 9), '{}'::text[])
        into v_emails, v_phones
        from public.hab_contacts c
        cross join lateral (select regexp_replace(translate(coalesce(c.whatsapp, ''), c_digits_from, c_digits_to), '\D', '', 'g') as digits) d
       where c.athlete_id = v_key;
      select lower(regexp_replace(btrim(concat_ws(' ', p.data -> 'athlete' ->> 'firstName', p.data -> 'athlete' ->> 'lastName')), '\s+', ' ', 'g'))
        into v_fullname from public.programs p
       where p.athlete_id = v_key
         and nullif(btrim(p.data -> 'athlete' ->> 'firstName'), '') is not null
         and nullif(btrim(p.data -> 'athlete' ->> 'lastName'), '') is not null;
      -- 'shared' = the same email or number is also on ANOTHER athlete's contact record (a parent's address for two children): the
      -- dashboard never ticks such a form for you.
      with f as (
        select i.id, i.created_at, i.name, i.programme, i.lang, (i.athlete_id is not distinct from v_key) as linked,
               lower(btrim(coalesce(i.email, ''))) as em,
               case when length(q.digits) >= 9 then right(q.digits, 9) end as ph,
               lower(regexp_replace(btrim(coalesce(i.name, '')), '\s+', ' ', 'g')) as nm
          from public.hab_intake i
          cross join lateral (select regexp_replace(translate(coalesce(i.contact, ''), c_digits_from, c_digits_to), '\D', '', 'g') as digits) q),
      m as (
        select f.*, case when f.linked then 'linked' when f.em <> '' and f.em = any (v_emails) then 'email'
                         when f.ph is not null and f.ph = any (v_phones) then 'whatsapp'
                         when v_fullname is not null and f.nm = v_fullname then 'name' end as how
          from f)
      select coalesce(jsonb_agg(jsonb_build_object(
               'id', m.id, 'created_at', m.created_at, 'name', m.name, 'programme', m.programme, 'lang', m.lang,
               'matched_on', m.how,
               'shared', (m.how = 'email' and exists (select 1 from public.hab_contacts c2
                                                       where c2.athlete_id <> v_key and lower(btrim(coalesce(c2.email, ''))) = m.em))
                      or (m.how = 'whatsapp' and exists (select 1 from public.hab_contacts c2
                                                          cross join lateral (select regexp_replace(translate(coalesce(c2.whatsapp, ''), c_digits_from, c_digits_to), '\D', '', 'g') as digits) q2
                                                         where c2.athlete_id <> v_key and length(q2.digits) >= 9 and right(q2.digits, 9) = m.ph)))
               order by m.created_at), '[]'::jsonb)
        into v_cands from m where m.how is not null;
      -- The forms to erase are the coach's pick (Amir, 2026-10-11): the matches above are only offered, and a form filled in under
      -- another name or number (most Farsi forms: the programme is in Latin letters) is found by hand in the dashboard. So any
      -- form that exists may be named, but not a runaway list, and a form that is already gone stops the erasure.
      if (select count(distinct s.id) from unnest(v_ids) s(id)) > 10 then
        raise exception 'More than 10 intake forms in one erasure is almost certainly a mistake. Nothing was erased.';
      end if;
      if exists (select 1 from unnest(v_ids) s(id)
                  where s.id is null or not exists (select 1 from public.hab_intake i where i.id = s.id)) then
        raise exception 'One of the intake forms does not exist (it may already be gone). Nothing was erased.';
      end if;

      foreach t in array c_athlete_tables loop
        execute format('delete from public.%I where athlete_id = $1', t) using v_key;
        get diagnostics v_n = row_count;
        v_counts := v_counts || jsonb_build_object(t, v_n);
        v_total := v_total + v_n;
      end loop;

      -- The rollback copies the pipeline keeps before a one-off change to live programmes sit in the "backup" schema, outside the list
      -- above (backup.onename_2026_10_09 holds 17 athletes' old progress and session logs from the rename of 2026-10-09). Whatever table
      -- there has an athlete_id column is emptied for this person too, so a table added later is covered without anyone remembering it.
      for t in
        select c.relname::text
          from pg_catalog.pg_attribute a
          join pg_catalog.pg_class c on c.oid = a.attrelid
          join pg_catalog.pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'backup' and a.attname = 'athlete_id' and a.attnum > 0 and not a.attisdropped
           and c.relkind in ('r', 'p')
         order by 1
      loop
        execute format('delete from backup.%I where athlete_id::text = $1', t) using v_key;
        get diagnostics v_n = row_count;
        v_counts := v_counts || jsonb_build_object('backup.' || t, v_n);
        v_total := v_total + v_n;
      end loop;

      -- The forms are counted in v_total only AFTER the "nothing is stored" check below: a mistyped id with forms ticked must raise
      -- that error, not erase the forms and write a receipt.
      delete from public.hab_intake where id = any (v_ids);
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('hab_intake', v_n);

      -- A partner record is a business record and stays; only its link to the erased athlete id goes.
      with u as (update public.affiliates set athlete_id = null where athlete_id = v_key returning code)
        select coalesce(jsonb_agg(code order by code), '[]'::jsonb) into v_unlinked from u;
      -- An application linked to this athlete (stage61) keeps its answers unless the coach ticked it above; only the link goes.
      update public.hab_intake set athlete_id = null, linked_at = null where athlete_id = v_key;

    elsif v_kind = 'course' then
      delete from public.buyer_notes where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('buyer_notes', v_n);
      v_total := v_total + v_n;
      delete from public.tps_accounts where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('tps_accounts', v_n);
      v_total := v_total + v_n;

    else
      -- children first, so each count is the real number (a cascade would delete them uncounted)
      delete from public.assess_notes where account_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_notes', v_n);
      v_total := v_total + v_n;
      delete from public.assess_results where account_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_results', v_n);
      v_total := v_total + v_n;
      delete from public.assess_players where account_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_players', v_n);
      v_total := v_total + v_n;
      delete from public.buyer_notes where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('buyer_notes', v_n);
      v_total := v_total + v_n;
      delete from public.assess_accounts where user_id = v_user;
      get diagnostics v_n = row_count;
      v_counts := v_counts || jsonb_build_object('assess_accounts', v_n);
      v_total := v_total + v_n;
    end if;

    -- ── the sign-in account itself; its sessions, tokens and identities go with it ───────────────────────────────────────
    delete from auth.users where id = any (v_users);
    get diagnostics v_n = row_count;
    v_counts := v_counts || jsonb_build_object('auth_users', v_n);
    v_total := v_total + v_n;

    -- ── nothing may be left ────────────────────────────────────────────────────────────────────────────────────────────
    if exists (select 1 from public.athlete_identities x where x.user_id = any (v_users))
       or exists (select 1 from public.tps_accounts x where x.user_id = any (v_users))
       or exists (select 1 from public.assess_accounts x where x.user_id = any (v_users))
       or exists (select 1 from public.buyer_notes x where x.user_id = any (v_users)) then
      raise exception 'Stopped, nothing was erased: a login row was still there after its sign-in account was deleted.';
    end if;
    -- A table added later that keys its rows on a sign-in (a uuid column called user_id or account_id) and is not emptied by the
    -- cascade from the deleted sign-in: for a buyer this is the only check that such a table was never forgotten.
    for sch, t, v_col in
      select n.nspname::text, c.relname::text, a.attname::text
        from pg_catalog.pg_attribute a
        join pg_catalog.pg_class c on c.oid = a.attrelid
        join pg_catalog.pg_namespace n on n.oid = c.relnamespace
       where n.nspname = 'public' and a.attname in ('user_id', 'account_id') and a.atttypid = 'uuid'::regtype
         and a.attnum > 0 and not a.attisdropped and c.relkind in ('r', 'p')
       order by 1, 2, 3
    loop
      execute format('select count(*) from %I.%I where %I = any ($1)', sch, t, v_col) into v_n using v_users;
      if v_n > 0 then
        raise exception 'Stopped, nothing was erased: the table %.% still holds % row(s) for their sign-in (column %). coach_erase_person does not know that table yet.', sch, t, v_n, v_col;
      end if;
    end loop;
    if v_kind = 'athlete' then
      for sch, t in
        select n.nspname::text, c.relname::text
          from pg_catalog.pg_attribute a
          join pg_catalog.pg_class c on c.oid = a.attrelid
          join pg_catalog.pg_namespace n on n.oid = c.relnamespace
         where n.nspname in ('public', 'backup') and a.attname = 'athlete_id' and a.attnum > 0 and not a.attisdropped
           and c.relkind in ('r', 'p')
         order by 1, 2
      loop
        execute format('select count(*) from %I.%I where athlete_id::text = $1', sch, t) into v_n using v_key;
        if v_n > 0 then
          raise exception 'Stopped, nothing was erased: the table %.% still holds % row(s) for "%". coach_erase_person does not know that table yet.', sch, t, v_n, v_key;
        end if;
      end loop;
    end if;
    -- "Nothing is stored" looks at DATA only: a sign-in account on its own (the identity row was lost earlier) does not count, or a key
    -- typed in another case would take that login and leave the data under the real id.
    if v_total - coalesce((v_counts ->> 'auth_users')::bigint, 0) = 0 then
      if v_kind = 'athlete' then   -- ids are case-sensitive: say so when only the case differs
        select p.athlete_id into v_other from public.programs p where lower(p.athlete_id) = lower(v_key) and p.athlete_id <> v_key limit 1;
        if v_other is null then
          select a.athlete_id into v_other from public.athlete_progress a where lower(a.athlete_id) = lower(v_key) and a.athlete_id <> v_key limit 1;
        end if;
      end if;
      raise exception 'Nothing is stored for "%". Nothing was erased.%', v_key,
        case when v_other is not null then ' (There is an athlete "' || v_other || '": ids are case-sensitive.)' else '' end;
    end if;
    v_total := v_total + coalesce((v_counts ->> 'hab_intake')::bigint, 0);

    -- ── the receipt (a real run only) and the answer ───────────────────────────────────────────────────────────────────
    if not p_dry_run then
      insert into public.erasure_log (erased_by, kind, subject_hash, counts)
      values (auth.jwt() ->> 'email', v_kind,
              encode(sha256(convert_to(v_kind || ':' || lower(v_word), 'UTF8')), 'hex'),
              v_counts || jsonb_build_object('affiliates_unlinked', jsonb_array_length(v_unlinked)))
      returning id into v_log_id;
    end if;
    v_result := jsonb_build_object(
      'ok', true, 'dry_run', p_dry_run, 'kind', v_kind, 'key', v_key, 'shown_as', v_shown, 'confirm_word', v_word,
      'counts', v_counts, 'total', v_total, 'intake_candidates', v_cands, 'intake_erased', (v_counts ->> 'hab_intake')::bigint,
      'affiliates_unlinked', v_unlinked, 'log_id', v_log_id);
    if p_dry_run then
      raise exception using errcode = 'ZZ100', message = v_result::text;
    end if;
  exception when sqlstate 'ZZ100' then
    return sqlerrm::jsonb;       -- the dry run: every change above has been undone, only the counts come back
  end;
  return v_result;
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_hide_session(p_athlete_id text, p_day integer, p_completed_on date, p_hide boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_hide boolean := coalesce(p_hide, true); v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' or p_day is null or p_completed_on is null then
    raise exception 'which session?';
  end if;
  with u as (
    update public.session_history s
       set hidden_at = case when v_hide then now() end,
           hidden_by = case when v_hide then auth.jwt() ->> 'email' end
     where s.athlete_id = p_athlete_id and s.day = p_day and s.completed_on = p_completed_on
       and (s.hidden_at is null) = v_hide
    returning 1)
  select count(*) into v_n from u;
  return jsonb_build_object('changed', v_n, 'hidden', v_hide);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_login_use()
 RETURNS TABLE(app text, key text, signed_in_since boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
    select 'athlete'::text, ai.athlete_id, coalesce(u.last_sign_in_at > ai.password_set_at, false)
      from public.athlete_identities ai join auth.users u on u.id = ai.user_id
     where ai.initial_password is not null
    union all
    select 'course'::text, t.username, coalesce(u.last_sign_in_at > t.password_set_at, false)
      from public.tps_accounts t join auth.users u on u.id = t.user_id
     where t.initial_password is not null
    union all
    select 'testing'::text, a.username, coalesce(u.last_sign_in_at > a.password_set_at, false)
      from public.assess_accounts a join auth.users u on u.id = a.user_id
     where a.initial_password is not null;
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_note_id()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select '__coach__'::text $function$;

CREATE OR REPLACE FUNCTION public.coach_save_spine(p_id text, p_entry jsonb, p_entry_snap jsonb, p_coach jsonb, p_coach_snap jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- The columns the editor owns. Anything else (id, updated_at, Claude's bookkeeping columns) is refused.
  -- stage64: steps (How to do it), and suggested_changes, so a Save that approves or discards Claude's drafts
  -- takes them off the list in the same transaction.
  c_entry text[] := array['name','aliases','pattern','qualities','purpose','tennis','cues','equipment','loads',
                          'easier','harder','alts','video','status','impact','muscles','steps','steps_fa','cues_fa','purpose_fa','tennis_fa'];
  c_coach text[] := array['sfr','flags','notes','credits','cost','suggested_changes'];
  -- SQL NULL and JSON null both mean "nothing for that half"; anything else that is not an object is refused below.
  v_entry   jsonb := coalesce(nullif(p_entry, 'null'::jsonb), '{}'::jsonb);
  v_coach   jsonb := coalesce(nullif(p_coach, 'null'::jsonb), '{}'::jsonb);
  v_esnap   jsonb := coalesce(nullif(p_entry_snap, 'null'::jsonb), '{}'::jsonb);
  v_csnap   jsonb := coalesce(nullif(p_coach_snap, 'null'::jsonb), '{}'::jsonb);
  v_live_e  jsonb;
  v_live_c  jsonb;
  v_clash_e text[];
  v_clash_c text[];
  v_k       text;
  v_set     text;
  v_cols    text;
  v_out_e   jsonb;
  v_out_c   jsonb;
  v_res     jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  -- A double-encoded or otherwise malformed payload must fail loudly: read as "{}" it came back ok:true having
  -- written nothing, and the page would have said Saved.
  if jsonb_typeof(v_entry) <> 'object' or jsonb_typeof(v_coach) <> 'object'
     or jsonb_typeof(v_esnap) <> 'object' or jsonb_typeof(v_csnap) <> 'object' then
    raise exception 'the entry, the coach-only part and their two snapshots must each be a JSON object';
  end if;

  for v_k in select jsonb_object_keys(v_entry) loop
    if not (v_k = any (c_entry)) then raise exception 'exercises.% cannot be written from the editor', v_k; end if;
  end loop;
  for v_k in select jsonb_object_keys(v_coach) loop
    if not (v_k = any (c_coach)) then raise exception 'exercise_coach.% cannot be written from the editor', v_k; end if;
  end loop;

  -- Lock the entry, then its coach-only row (always in this order). A concurrent writer is waited for,
  -- and READ COMMITTED hands back the row as it was committed.
  select to_jsonb(e) into v_live_e from public.exercises e where e.id = p_id for update;
  if v_live_e is null then
    raise exception 'this entry is no longer on the server (%). Refresh.', p_id;
  end if;
  select to_jsonb(c) into v_live_c from public.exercise_coach c where c.id = p_id for update;

  -- A column clashes when it differs from what the page read AND from what the coach is writing.
  select coalesce(array_agg(k order by k), '{}') into v_clash_e
    from jsonb_object_keys(v_entry) k
   where (v_live_e -> k) is distinct from coalesce(v_esnap -> k, 'null'::jsonb)
     and (v_live_e -> k) is distinct from (v_entry -> k);
  if v_live_c is null then
    -- No coach-only row yet. One that appeared since the page read is a clash on every column that
    -- differs from what is being written; a row that is still absent has nothing to clash with.
    v_clash_c := '{}';
  else
    select coalesce(array_agg(k order by k), '{}') into v_clash_c
      from jsonb_object_keys(v_coach) k
     where (v_live_c -> k) is distinct from coalesce(v_csnap -> k, 'null'::jsonb)
       and (v_live_c -> k) is distinct from (v_coach -> k);
  end if;
  if cardinality(v_clash_e) > 0 or cardinality(v_clash_c) > 0 then
    -- Nothing is written. Built key by key: jsonb_strip_nulls is recursive and would drop the live
    -- rows' own null columns, which the page needs to see.
    v_res := jsonb_build_object('ok', false);
    if cardinality(v_clash_e) > 0 then
      v_res := v_res || jsonb_build_object('entry', jsonb_build_object('cols', to_jsonb(v_clash_e), 'live', v_live_e));
    end if;
    if cardinality(v_clash_c) > 0 then
      v_res := v_res || jsonb_build_object('coach', jsonb_build_object('cols', to_jsonb(v_clash_c), 'live', v_live_c));
    end if;
    return v_res;
  end if;

  -- The entry half: only the columns sent, typed from the JSON by the table's own row type.
  if v_entry <> '{}'::jsonb then
    select string_agg(format('%I = r.%I', k, k), ', ') into v_set from jsonb_object_keys(v_entry) k;
    execute format('update public.exercises e set %s, updated_by = %L from jsonb_populate_record(null::public.exercises, $1) r where e.id = $2',
                   v_set, 'coach') using v_entry, p_id;
  end if;

  -- The coach-only half: update the row, or create it with only the columns sent (the rest take their defaults).
  if v_coach <> '{}'::jsonb then
    if v_live_c is null then
      select string_agg(format('%I', k), ', '), string_agg(format('r.%I', k), ', ')
        into v_cols, v_set from jsonb_object_keys(v_coach) k;
      execute format('insert into public.exercise_coach (id, %s) select $2, %s from jsonb_populate_record(null::public.exercise_coach, $1) r',
                     v_cols, v_set) using v_coach, p_id;
    else
      select string_agg(format('%I = r.%I', k, k), ', ') into v_set from jsonb_object_keys(v_coach) k;
      execute format('update public.exercise_coach c set %s from jsonb_populate_record(null::public.exercise_coach, $1) r where c.id = $2',
                     v_set) using v_coach, p_id;
    end if;
  end if;

  select to_jsonb(e) into v_out_e from public.exercises e where e.id = p_id;
  select to_jsonb(c) into v_out_c from public.exercise_coach c where c.id = p_id;
  return jsonb_build_object('ok', true,
    'entry', case when v_entry <> '{}'::jsonb then v_out_e end,
    'coach', case when v_coach <> '{}'::jsonb then v_out_c end);
end; $function$;

CREATE OR REPLACE FUNCTION public.coach_season_levels(p_ids text[])
 RETURNS TABLE(athlete_id text, level integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if public.career_xp_on() then
    return query
      select x.id, coalesce((s.score #>> '{career,level}')::int, 1)
        from unnest(p_ids) as x(id)
        left join public.career_scores_for(p_ids, interval '3 seconds') s on s.athlete_id = x.id;
    return;
  end if;
  return query select x.id, public.hab_proof_level(x.id) from unnest(p_ids) as x(id);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_set_status(p_athlete_id text, p_status text, p_since date DEFAULT NULL::date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_note text := nullif(btrim(coalesce(p_note, '')), ''); v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' then
    raise exception 'which athlete?';
  end if;
  if p_status is null or p_status not in ('active', 'paused', 'former') then
    raise exception 'bad status: %', p_status;
  end if;
  if lower(p_athlete_id) in ('demo', 'amir_ardekani') then
    raise exception '"%" is the public demo or your own identity: it has no status', p_athlete_id;
  end if;
  if not exists (select 1 from public.programs p where p.athlete_id = p_athlete_id)
     and not exists (select 1 from public.hab_contacts c where c.athlete_id = p_athlete_id)
     and not exists (select 1 from public.athlete_progress a where a.athlete_id = p_athlete_id) then
    raise exception 'there is no athlete called "%"', p_athlete_id;
  end if;
  if p_status = 'active' then
    with d as (delete from public.athlete_status where athlete_id = p_athlete_id returning 1)
      select count(*) into v_n from d;
  else
    insert into public.athlete_status as s (athlete_id, status, since, note)
    values (p_athlete_id, p_status, coalesce(p_since, current_date), v_note)
    on conflict (athlete_id) do update
      set status     = excluded.status,
          since      = coalesce(p_since, case when s.status = excluded.status then s.since else current_date end),
          note       = excluded.note,
          updated_at = now();
  end if;
  return jsonb_build_object('athlete_id', p_athlete_id, 'status', p_status);
end $function$;

CREATE OR REPLACE FUNCTION public.coach_set_whatsapp(p_athlete_id text, p_whatsapp text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_wa text := nullif(btrim(coalesce(p_whatsapp, '')), ''); v_tier text; v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if coalesce(btrim(p_athlete_id), '') = '' then
    raise exception 'which athlete?';
  end if;
  if v_wa is not null and length(v_wa) > 40 then
    raise exception 'that is too long for a phone number';
  end if;
  if not exists (select 1 from public.programs p where p.athlete_id = p_athlete_id)
     and not exists (select 1 from public.hab_contacts c where c.athlete_id = p_athlete_id) then
    raise exception 'there is no athlete called "%"', p_athlete_id;
  end if;
  update public.hab_contacts c set whatsapp = v_wa, updated_at = now() where c.athlete_id = p_athlete_id;
  get diagnostics v_n = row_count;
  if v_n = 0 and v_wa is not null then
    select case when p.data -> 'athlete' ->> 'tier' = 'free' then 'free' else 'coached' end
      into v_tier from public.programs p where p.athlete_id = p_athlete_id;
    insert into public.hab_contacts (athlete_id, whatsapp, source, tier)
    values (p_athlete_id, v_wa, 'coach', coalesce(v_tier, 'coached'));
  end if;
  return jsonb_build_object('athlete_id', p_athlete_id, 'whatsapp', v_wa);
end $function$;

CREATE OR REPLACE FUNCTION public.coaching_logs_keep_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.body is distinct from new.body then
    insert into public.coaching_log_versions (athlete_id, body, was_updated_at)
    values (old.athlete_id, old.body, old.updated_at);
  end if;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.coaching_logs_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.contact_list()
 RETURNS TABLE(athlete_id text, email text, whatsapp text, source text, tier text, shown_as text, on_board boolean, days_logged integer, signed_up timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
  select c.athlete_id, c.email, c.whatsapp, c.source, c.tier,
         coalesce(o.display_name, c.display_name),
         (o.athlete_id is not null),
         coalesce((
           select count(*)::int
           from jsonb_each(public.hab_log_of(ap.data, c.athlete_id)) d
           where jsonb_typeof(d.value) = 'object' and d.value <> '{}'::jsonb
         ), 0),
         c.created_at
  from public.hab_contacts c
  left join public.leaderboard_optin o on o.athlete_id = c.athlete_id
  left join public.athlete_progress  ap on ap.athlete_id = c.athlete_id
  order by c.created_at desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.current_athlete_id()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select athlete_id from public.athlete_identities where user_id = auth.uid() $function$;

CREATE OR REPLACE FUNCTION public.current_season()
 RETURNS TABLE(name text, starts_on date)
 LANGUAGE sql
 STABLE
AS $function$
  select s.name, s.starts_on
  from public.seasons s
  where s.starts_on <= current_date
  order by s.starts_on desc, s.id desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.delete_intake(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  delete from public.hab_intake where id = p_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.end_quests(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key   text;
  v_runs  jsonb;
  v_out   jsonb := '[]'::jsonb;
  v_found boolean := false;
  r       jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_start is null or p_end is null then
    raise exception 'give the run''s start day and the day it ends';
  end if;
  v_key := to_char(p_start, 'YYYY-MM-DD');
  select coalesce(rules -> 'questRuns', '[]'::jsonb) into v_runs from public.xp_rules where id = 1 for update;
  for r in select value from jsonb_array_elements(v_runs) loop
    if r ->> 'start' is not distinct from v_key then
      v_found := true;
      if p_end >= p_start then   -- a run that had not begun (end before start) is dropped: nothing was earned in it
        v_out := v_out || jsonb_build_array(r || jsonb_build_object('end', to_char(least(p_end, p_start + 6), 'YYYY-MM-DD')));
      end if;
    else
      v_out := v_out || jsonb_build_array(r);
    end if;
  end loop;
  if not v_found then
    raise exception 'no quest run starts on %', v_key;
  end if;
  update public.xp_rules set rules = jsonb_set(rules, '{questRuns}', v_out), updated_at = now() where id = 1;
  return v_out;
end; $function$;

CREATE OR REPLACE FUNCTION public.forget_contact(p_athlete_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if exists (
    select 1 from public.programs p
     where p.athlete_id = p_athlete_id
       and coalesce(p.data->'athlete'->>'tier', p.data->>'tier', '') <> 'free'
  ) then
    raise exception 'coached athlete: forget would delete their training app data (records, body weight, check-ins). Nothing was deleted.';
  end if;
  delete from public.hab_notes         where athlete_id = p_athlete_id;
  delete from public.leaderboard_optin where athlete_id = p_athlete_id;
  delete from public.athlete_progress  where athlete_id = p_athlete_id;
  delete from public.hab_contacts      where athlete_id = p_athlete_id;
  delete from public.athlete_keys      where athlete_id = p_athlete_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_course()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id   text;
  v_full boolean := false;
  v_open_lessons text[] := array['read-your-card', 'rpe-weights', 'tennis-demands'];
  v_open_tests   text[] := array['broad-jump'];
begin
  if public.is_coach() then
    v_full := true;
  else
    v_id := public.current_athlete_id();
    if v_id is not null then
      select coalesce(p.data->'athlete'->>'tier', '') <> 'free' into v_full
      from public.programs p where p.athlete_id = v_id;
      v_full := coalesce(v_full, false);
    end if;
  end if;

  return jsonb_build_object(
    'full', v_full,
    'lessons', coalesce((
      select jsonb_agg(
        case when v_full or c.id = any(v_open_lessons) then c.body
             else jsonb_strip_nulls(jsonb_build_object('id', c.body->'id', 'order', c.body->'order', 'group', c.body->'group',
               'icon', c.body->'icon', 'title', c.body->'title', 'summary', c.body->'summary',
               'audience', c.body->'audience', 'locked', true)) end
        order by c.sort, c.id)
      from public.course_en c where c.kind = 'lesson'), '[]'::jsonb),
    'tests', coalesce((
      select jsonb_agg(
        case when v_full or c.id = any(v_open_tests) then c.body
             else jsonb_strip_nulls(jsonb_build_object('id', c.body->'id', 'order', c.body->'order', 'icon', c.body->'icon',
               'title', c.body->'title', 'badge', c.body->'badge', 'why', c.body->'why', 'optional', c.body->'optional',
               'player', c.body->'player', 'calc', c.body->'calc', 'locked', true)) end
        order by c.sort, c.id)
      from public.course_en c where c.kind = 'test'), '[]'::jsonb),
    'day', (select c.body from public.course_en c where c.kind = 'testday' limit 1)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_exercises()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id, 'name', e.name, 'aliases', e.aliases, 'pattern', e.pattern,
           'qualities', e.qualities, 'purpose', e.purpose, 'tennis', e.tennis,
           'cues', e.cues, 'equipment', e.equipment, 'loads', e.loads, 'impact', e.impact,
           'easier', e.easier, 'harder', e.harder, 'alts', e.alts, 'video', e.video,
           -- stage64: How to do it, [] when none
           'steps', to_jsonb(coalesce(e.steps, '{}'::text[])),
           -- stage42: muscle names and 1/0.5 only. Never cost, sfr or flags.
           'muscles', coalesce(nullif(c.credits, '{}'::jsonb), e.muscles)
         ) order by e.name), '[]'::jsonb)
  from public.exercises e
  left join public.exercise_coach c on c.id = e.id
  where e.status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.get_exercises_fa()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', e.id, 'name', e.name, 'video', e.video,
           'steps', to_jsonb(coalesce(e.steps_fa, '{}'::text[])), 'cues', e.cues_fa,
           'purpose', e.purpose_fa, 'tennis', e.tennis_fa) order by e.id), '[]'::jsonb)
  from public.exercises e
  where e.status = 'approved'
    and (cardinality(e.steps_fa) > 0 or e.cues_fa is not null or e.purpose_fa is not null or e.tennis_fa is not null);
$function$;

CREATE OR REPLACE FUNCTION public.get_library(p_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_object_agg(kind, cats), '{}'::jsonb)
  from (
    select c.kind,
           jsonb_agg(
             jsonb_build_object(
               'id', c.id, 'title', c.title, 'banner', c.banner, 'icon', c.icon,
               'items', coalesce((
                 select jsonb_agg(l.data order by coalesce(l.sort_order, 2147483647), l.slug)
                 from public.library l
                 where l.kind = c.kind and l.category_id = c.id and l.published
               ), '[]'::jsonb)
             )
             order by coalesce(c.sort_order, 2147483647), c.id
           ) as cats
    from public.library_categories c
    where p_kind is null or c.kind = p_kind
    group by c.kind
  ) t;
$function$;

CREATE OR REPLACE FUNCTION public.get_library_days(p_athlete_id text, p_since date DEFAULT NULL::date)
 RETURNS TABLE(completed_on date, counts_as text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() then
    raise exception 'not your athlete record';
  end if;

  return query
    select distinct s.completed_on, s.counts_as
    from public.library_sessions s
    where s.athlete_id = p_athlete_id
      and s.counts_as is not null
      and (p_since is null or s.completed_on >= p_since)
    order by 1, 2;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_messages(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS SETOF messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return query
    select * from public.messages where athlete_id = p_athlete_id order by created_at asc;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_my_history(p_athlete_id text, p_days integer DEFAULT 180)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if p_athlete_id = 'demo' then
    return '[]'::jsonb;
  end if;
  -- coalesce: a NULL id must be refused, not slip through a NULL comparison.
  if not coalesce(public.is_coach() or p_athlete_id = public.current_athlete_id(), false) then
    raise exception 'not allowed';
  end if;
  select coalesce(jsonb_agg(r order by r.completed_on desc, r.day desc), '[]'::jsonb) into v
  from (
    select s.completed_on, s.day, s.focus, s.session_rpe,
           s.readiness->'composite' as readiness,
           s.readiness as ready,
           s.log,
           case when s.log is null then s.summary end as summary
    from public.session_history s
    where s.athlete_id = p_athlete_id
      and s.hidden_at is null
      and s.completed_on >= current_date - greatest(1, least(coalesce(p_days, 180), 400))
    order by s.completed_on desc, s.day desc
    limit 120
  ) r;
  return v;
end $function$;

CREATE OR REPLACE FUNCTION public.get_profile(p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me text := public.current_athlete_id();
  v_id text := coalesce(nullif(btrim(coalesce(p_athlete_id, '')), ''), v_me);
  v_rules jsonb; v_score jsonb; v_now integer := 0; v_best integer := 0; f record; v_xp date;
begin
  if v_id is null then
    raise exception 'not signed in';
  end if;
  -- the athlete reads their own, the coach anyone's, and so does the SQL editor or the service role (no sign-in claims: a report)
  if not (public.is_coach() or v_id is not distinct from v_me or coalesce(auth.jwt() ->> 'role', '') in ('', 'service_role')) then
    raise exception 'not your profile';
  end if;
  v_rules := public.career_rules_now();
  if v_rules is null then
    return jsonb_build_object('athlete_id', v_id, 'ready', false);
  end if;
  perform public.career_derive(v_id);
  v_score := coalesce(public.career_scored(v_id), '{}'::jsonb);
  v_xp := public.career_switch_day(v_rules, 'xp');
  -- weeks held in a row: only a broken week ends a run (a week between cycles, or one Amir paused, is no week at all)
  for f in select cf.kind from public.career_facts cf
            where cf.athlete_id = v_id and cf.void_at is null and cf.kind in ('week_held', 'week_broken')
            order by cf.day, cf.ref loop
    if f.kind = 'week_held' then v_now := v_now + 1; v_best := greatest(v_best, v_now); else v_now := 0; end if;
  end loop;
  return jsonb_build_object(
    'athlete_id', v_id,
    'ready', true,
    'shadow', v_xp is null,
    'switch', jsonb_build_object('xp', v_xp, 'catalogue', public.career_switch_day(v_rules, 'catalogue')),
    'rules_version', (select max(r.version) from public.career_rules r),
    'career', v_score -> 'career',
    'season', v_score -> 'season',
    'week', v_score -> 'week',
    'since', (select min(cf.day) from public.career_facts cf
               where cf.athlete_id = v_id and cf.void_at is null
                 and cf.kind in ('habit_day', 'session_finished', 'session_finished_early', 'library_session')),
    'kept', (select cf.value from public.career_facts cf
              where cf.athlete_id = v_id and cf.kind = 'level_kept' and cf.ref = 'xp-switch' and cf.void_at is null),
    'numbers', (select jsonb_build_object(
                  'weeks_held', jsonb_build_object('now', v_now, 'best', v_best),
                  'sessions_with_amir', count(*) filter (where cf.kind in ('session_finished', 'session_finished_early')),
                  'personal_bests', count(*) filter (where cf.kind = 'personal_best'),
                  'comebacks', count(*) filter (where cf.kind = 'comeback'),
                  'days_on_target', count(*) filter (where cf.kind = 'day_on_target'),
                  'perfect_days', count(*) filter (where cf.kind = 'perfect_day'))
                  from public.career_facts cf where cf.athlete_id = v_id and cf.void_at is null),
    'titles_owned', coalesce((select jsonb_agg(t.title order by t.earned_on, t.title) from public.hab_titles t where t.athlete_id = v_id), '[]'::jsonb),
    'rules', jsonb_build_object(
      'version', (select max(r.version) from public.career_rules r),
      'level', jsonb_build_object('base', v_rules #> '{level,base}', 'growth', v_rules #> '{level,growth}',
                                  'ranks', v_rules #> '{level,ranks}', 'levels_per_rank', v_rules #> '{level,levels_per_rank}',
                                  'prestige_after', v_rules #> '{level,prestige_after}'),
      'season', jsonb_build_object('title_points', v_rules #> '{season,title_points}'),
      'prices', coalesce((select jsonb_object_agg(k.key, public.career_num(v_rules #> array['fact', k.key, 'xp']))
                            from unnest(array['session_finished', 'session_finished_early', 'full_log', 'checkin_done', 'week_held',
                                              'bounce_back', 'training_return', 'library_session', 'retest_done']) as k(key)
                           where public.career_num(v_rules #> array['fact', k.key, 'xp']) is not null), '{}'::jsonb)),
    'badges', '[]'::jsonb, 'achievements', '[]'::jsonb, 'missions', '[]'::jsonb, 'quest', null, 'moments', '[]'::jsonb
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_program(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_data jsonb;
begin
  -- 'demo' is the public showcase (synthetic athlete), linked openly from the site
  -- and opened by people who have no key and never will.
  if p_athlete_id = 'demo'
     or public.is_coach()
     or p_athlete_id = public.current_athlete_id() then
    select data into v_data from public.programs where athlete_id = p_athlete_id;
    return v_data;
  end if;

  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if v_expected is null or p_key is null or p_key is distinct from v_expected then
    raise exception 'invalid athlete key';
  end if;

  select data into v_data from public.programs where athlete_id = p_athlete_id;
  return v_data;
end $function$;

CREATE OR REPLACE FUNCTION public.get_progress(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_data jsonb;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  select data into v_data from public.athlete_progress where athlete_id = p_athlete_id;
  return coalesce(v_data, '{}'::jsonb);
end; $function$;

CREATE OR REPLACE FUNCTION public.get_qualities()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', q.id, 'name', q.name, 'family', q.family, 'line', q.line,
           'tennis', q.tennis, 'tests', q.tests, 'sort', q.sort
         ) order by q.sort), '[]'::jsonb)
  from public.qualities q
  where q.status = 'approved';
$function$;

CREATE OR REPLACE FUNCTION public.get_quests(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(pool jsonb, runs jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_rules jsonb;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return; end if;
  return query select coalesce(v_rules -> 'quests', '[]'::jsonb),
                      coalesce(v_rules -> 'questRuns', '[]'::jsonb);
end; $function$;

CREATE OR REPLACE FUNCTION public.get_season(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(name text, starts_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return query select * from public.current_season();
end; $function$;

CREATE OR REPLACE FUNCTION public.get_workout_days(p_athlete_id text, p_key text DEFAULT NULL::text, p_since date DEFAULT NULL::date)
 RETURNS SETOF date
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  -- A row exists here only because the athlete pressed "Finish Session", so
  -- every row counts — a partly-finished session still means they showed up.
  -- A row the coach has hidden does not count (stage60).
  return query
    select distinct s.completed_on
    from public.session_history s
    where s.athlete_id = p_athlete_id
      and s.completed_on is not null
      and s.hidden_at is null
      and (p_since is null or s.completed_on >= p_since)
    order by 1;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_bonus_xp(p_log jsonb, p_cfg jsonb, p_season_start date, p_from date, p_to date, p_rules jsonb)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
AS $function$
with
  bonusmult as (
    select coalesce((p_rules ->> 'completionBonus')::numeric, 1.2) as cb,
           coalesce((p_rules ->> 'customXp')::numeric, 25) as cx,
           coalesce((p_rules ->> 'streakQualifyPct')::numeric, 80) as qpct,
           coalesce((p_rules ->> 'gateV2')::boolean, false) as gate2,
           coalesce((p_rules ->> 'lapseDays')::int, 3) as lapse,
           coalesce((p_rules ->> 'comebackXp')::numeric, 0) as cbxp,
           coalesce((p_rules ->> 'comebackStick')::int, 7) as stick
  ),
  dl as (
    select (e.key)::date as d, e.value as vals
    from jsonb_each(coalesce(p_log, '{}'::jsonb)) e
    where e.key ~ '^\d{4}-\d{2}-\d{2}$'
      and jsonb_typeof(e.value) = 'object'
      and (p_season_start is null or (e.key)::date >= p_season_start)
  ),
  habits as (
    select t.key as hid, t.value::numeric as tgt, b.cx as fallback
    from jsonb_each_text(coalesce(p_rules -> 'targets', '{}'::jsonb)) t, bonusmult b
    union all
    select c.value ->> 'id', 1::numeric, b.cx
    from jsonb_array_elements(coalesce(p_cfg -> 'custom', '[]'::jsonb)) c, bonusmult b
    where c.value ->> 'id' is not null
  ),
  weighted as (
    select h.hid, h.tgt,
           coalesce((p_rules -> 'weights' ->> h.hid)::numeric, h.fallback) as w
    from habits h
  ),
  dayroster as (
    select dl.d,
           (select r.value -> 'ids'
              from jsonb_array_elements(coalesce(p_cfg -> 'roster', '[]'::jsonb)) r(value)
             where (r.value ->> 'from')::date <= dl.d
             order by (r.value ->> 'from')::date desc limit 1) as ids
    from dl
  ),
  daylive as (
    select dr.d, w.hid, w.tgt, w.w,
           jsonb_exists(coalesce(p_rules -> 'unearnable', '[]'::jsonb), w.hid) as lockd
    from dayroster dr cross join weighted w
    where case when dr.ids is null
               then coalesce(p_cfg -> 'on' ->> w.hid, 'true') <> 'false'
               else jsonb_exists(dr.ids, w.hid) end
  ),
  done as (
    select w.hid, dl.d from dl cross join weighted w
    where jsonb_typeof(dl.vals -> w.hid) = 'number' and (dl.vals ->> w.hid)::numeric >= w.tgt
  ),
  islands as (
    select hid, d, d - (row_number() over (partition by hid order by d))::int as grp from done
  ),
  runlen as (
    select hid, d, (row_number() over (partition by hid, grp order by d))::int as run from islands
  ),
  hitno as (
    select hid, d, (row_number() over (partition by hid order by d))::int as n from done
  ),
  perday as (
    select dl.d, dl.vals,
           count(dv.hid) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt)::int as ndone,
           count(dv.hid)::int as nlive,
           coalesce(sum(dv.w) filter (
             where jsonb_typeof(dl.vals -> dv.hid) = 'number'
               and (dl.vals ->> dv.hid)::numeric >= dv.tgt), 0) as wdone,
           coalesce(sum(dv.w) filter (
             where (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                    and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
                or not dv.lockd), 0) as glive,
           coalesce(sum(
             case when jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt
                  then dv.w
                  when dv.lockd then 0
                  when dv.tgt > 0 and jsonb_typeof(dl.vals -> dv.hid) = 'number'
                       and (dl.vals ->> dv.hid)::numeric > 0
                  then dv.w * least((dl.vals ->> dv.hid)::numeric / dv.tgt, 1)
                  else 0 end), 0) as gpart,
           count(dv.hid) filter (
             where not (jsonb_typeof(dl.vals -> dv.hid) = 'number'
                        and (dl.vals ->> dv.hid)::numeric >= dv.tgt)
               and not dv.lockd)::int as gmiss
    from dl left join daylive dv on dv.d = dl.d
    group by dl.d, dl.vals
  ),
  qualday as (
    select p.d
    from perday p, bonusmult b
    where case when b.gate2
               then (p.glive > 0 and round(p.gpart / p.glive * 100) >= b.qpct)
                     or (p.gmiss <= 1 and p.gpart > 0)
               else p.glive > 0 and round(p.wdone / p.glive * 100) >= b.qpct
          end
  ),
  qgap as (
    select d, (d - lag(d) over (order by d) - 1) as gone from qualday
  ),
  qisl as (
    select d, d - (row_number() over (order by d))::int as grp from qualday
  ),
  qrun as (
    select grp, min(d) as startd, count(*)::int as runlen from qisl group by grp
  ),
  comeback as (
    select g.d, g.gone, r.runlen
    from qgap g join qrun r on r.startd = g.d, bonusmult b
    where b.lapse > 0 and g.gone >= b.lapse
  ),
  comeback_paid as (
    select sum(b.cbxp) as xp
    from comeback c, bonusmult b
    where (p_from is null or c.d >= p_from) and (p_to is null or c.d <= p_to)
  ),
  cb_run_at as (
    select c.d + i as d, i + 1 as run
    from comeback c, generate_series(0, c.runlen - 1) as i
  ),
  cb_run_no as (
    select d, max(run) over (order by d) as n from cb_run_at
  ),
  cb_stuck_no as (
    select c.d + (b.stick - 1) as d,
           (row_number() over (order by c.d))::int as n
    from comeback c, bonusmult b
    where c.runlen >= b.stick
  ),
  with3 as (select d, (row_number() over (order by d))::int as n from perday where ndone >= 3),
  perfect as (
    select p.d, (row_number() over (order by p.d))::int as n
    from perday p where p.nlive > 0 and p.ndone >= p.nlive
  ),
  tiers as (
    select (t.ord - 1)::int as idx, (t.val ->> 'days')::int as days, (t.val ->> 'mult')::numeric as mult
    from jsonb_array_elements(coalesce(p_rules -> 'tiers', '[]'::jsonb)) with ordinality t(val, ord)
  ),
  tier_cross as (
    select rl.hid, tr.idx, tr.mult, min(rl.d) as crossed
    from runlen rl join tiers tr on rl.run >= tr.days group by rl.hid, tr.idx, tr.mult
  ),
  tier_paid as (
    select sum(greatest(10, round(w.w * b.cb * tc.mult / 10) * 10)) as xp
    from tier_cross tc join weighted w on w.hid = tc.hid cross join bonusmult b
    where (p_from is null or tc.crossed >= p_from) and (p_to is null or tc.crossed <= p_to)
  ),
  ms as (
    select m.val ->> 'code' as code, (m.val ->> 'need')::int as need,
           (m.val ->> 'xp')::numeric as xp, m.val ->> 'measure' as measure
    from jsonb_array_elements(coalesce(p_rules -> 'milestones', '[]'::jsonb)) m(val)
  ),
  ms_cross as (
    select m.code, m.xp, min(rl.d) as crossed
    from ms m join runlen rl on m.measure = 'streak:' || rl.hid and rl.run >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(hn.d) from ms m join hitno hn on m.measure = 'daysHit:' || hn.hid and hn.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(w3.d) from ms m join with3 w3 on m.measure = 'daysWith3' and w3.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(pf.d) from ms m join perfect pf on m.measure = 'perfectDays' and pf.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(cr.d) from ms m join cb_run_no cr on m.measure = 'comebackRun' and cr.n >= m.need group by m.code, m.xp
    union all
    select m.code, m.xp, min(cs.d) from ms m join cb_stuck_no cs on m.measure = 'comebacksStuck' and cs.n >= m.need group by m.code, m.xp
  ),
  ms_paid as (
    select sum(xp) as xp from ms_cross
    where (p_from is null or crossed >= p_from) and (p_to is null or crossed <= p_to)
  ),
  qruns as (
    select rstart,
           least(rstart + 6, coalesce(next_start - 1, rstart + 6), coalesce(own_end, rstart + 6)) as rend,
           ids
    from (
      select (r.val ->> 'start')::date as rstart,
             r.val -> 'ids' as ids,
             case when r.val ->> 'end' ~ '^\d{4}-\d{2}-\d{2}$' then (r.val ->> 'end')::date end as own_end,
             lead((r.val ->> 'start')::date) over (order by (r.val ->> 'start')::date) as next_start
      from jsonb_array_elements(coalesce(p_rules -> 'questRuns', '[]'::jsonb)) r(val)
      where r.val ->> 'start' ~ '^\d{4}-\d{2}-\d{2}$'
    ) q
  ),
  rq as (
    select qr.rstart, qr.rend, pq.val as quest
    from qruns qr
    join jsonb_array_elements(coalesce(p_rules -> 'quests', '[]'::jsonb)) pq(val)
      on jsonb_exists(qr.ids, pq.val ->> 'id')
  ),
  dh as (
    select qr.rstart, w.hid, dl.d,
           (row_number() over (partition by qr.rstart, w.hid order by dl.d))::int as n
    from qruns qr join dl on dl.d between qr.rstart and qr.rend cross join weighted w
    where jsonb_typeof(dl.vals -> w.hid) = 'number' and (dl.vals ->> w.hid)::numeric >= w.tgt
  ),
  tot as (
    select qr.rstart, w.hid, dl.d,
           sum(case when jsonb_typeof(dl.vals -> w.hid) = 'number'
                    then (dl.vals ->> w.hid)::numeric else 0 end)
             over (partition by qr.rstart, w.hid order by dl.d) as acc
    from qruns qr join dl on dl.d between qr.rstart and qr.rend cross join weighted w
  ),
  qd as (
    select qr.rstart, q.d,
           (row_number() over (partition by qr.rstart order by q.d))::int as n
    from qruns qr join qualday q on q.d between qr.rstart and qr.rend
  ),
  pfw as (
    select qr.rstart, p.d,
           (row_number() over (partition by qr.rstart order by p.d))::int as n
    from qruns qr join perday p on p.d between qr.rstart and qr.rend
    where p.nlive > 0 and p.ndone >= p.nlive
  ),
  quest_cross as (
    select rq.rstart, rq.quest ->> 'id' as qid, (rq.quest ->> 'xp')::numeric as xp, min(dh.d) as crossed
    from rq join dh on dh.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'daysHit:' || dh.hid and dh.n >= (rq.quest ->> 'need')::int
    group by 1,2,3
    union all
    select rq.rstart, rq.quest ->> 'id', (rq.quest ->> 'xp')::numeric, min(tot.d)
    from rq join tot on tot.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'total:' || tot.hid and tot.acc >= (rq.quest ->> 'need')::numeric
    group by 1,2,3
    union all
    select rq.rstart, rq.quest ->> 'id', (rq.quest ->> 'xp')::numeric, min(qd.d)
    from rq join qd on qd.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'qualify' and qd.n >= (rq.quest ->> 'need')::int
    group by 1,2,3
    union all
    select rq.rstart, rq.quest ->> 'id', (rq.quest ->> 'xp')::numeric, min(pfw.d)
    from rq join pfw on pfw.rstart = rq.rstart
      and rq.quest ->> 'kind' = 'perfect' and pfw.n >= (rq.quest ->> 'need')::int
    group by 1,2,3
  ),
  quest_paid as (
    select sum(xp) as xp from quest_cross
    where (p_from is null or crossed >= p_from) and (p_to is null or crossed <= p_to)
  )
select (coalesce((select xp from tier_paid), 0)
      + coalesce((select xp from ms_paid), 0)
      + coalesce((select xp from quest_paid), 0)
      + coalesce((select xp from comeback_paid), 0))::bigint;
$function$;

CREATE OR REPLACE FUNCTION public.hab_career_level(p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb; v_data jsonb; v_xp bigint;
begin
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return 1; end if;
  select data into v_data from public.athlete_progress where athlete_id = p_athlete_id;
  if v_data is null then return 1; end if;
  v_xp := public.hab_xp(public.hab_log_of(v_data, p_athlete_id),
                        '1970-01-01'::date, current_date, v_rules)
        + public.hab_bonus_xp(public.hab_log_of(v_data, p_athlete_id),
                              public.hab_cfg_of(v_data, p_athlete_id),
                              '1970-01-01'::date, '1970-01-01'::date, current_date, v_rules);
  return public.hab_level(v_xp, v_rules);
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_cfg_of(p_data jsonb, p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare t text;
begin
  if p_data is null then return null; end if;
  t := p_data ->> (p_athlete_id || '_hab_cfg');
  if t is null or btrim(t) = '' then return null; end if;
  begin
    return t::jsonb;
  exception when others then
    return null;
  end;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_clean_note(p_body text, p_max integer DEFAULT 200)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare t text;
begin
  t := coalesce(p_body, '');
  t := regexp_replace(t, '[<>"''\\]', '', 'g');
  t := regexp_replace(t, '\s+', ' ', 'g');
  t := btrim(t);
  return left(t, greatest(1, p_max));
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_close_season(p_ended_on date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_name text; v_start date; v_title text; v_rules jsonb; v_n integer := 0; v_need numeric;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;

  select name, starts_on into v_name, v_start from public.current_season();
  if v_start is null then return 0; end if;
  if p_ended_on < v_start then
    raise exception 'a season cannot end (%) before it started (%)', p_ended_on, v_start;
  end if;
  if p_ended_on > current_date then
    raise exception 'cannot archive a season that has not finished yet (ends %, today is %)',
                    p_ended_on, current_date;
  end if;
  v_title := 't_sn_' || to_char(v_start, 'YYYYMMDD');

  if public.career_xp_on() then
    v_rules := public.career_rules_now();
    v_need := coalesce(public.career_num(v_rules #> '{season,title_points}'), 2000);
    with who as (
      select distinct f.athlete_id as id from public.career_facts f where f.void_at is null
    ),
    scored as (
      select w.id,
             (public.career_score(w.id, v_start, v_start, p_ended_on) ->> 'xp')::bigint as pts,
             (public.career_score(w.id, null, null, p_ended_on) ->> 'xp')::bigint as cxp
        from who w
    )
    insert into public.hab_season_results (athlete_id, starts_on, season_name, ended_on, level, xp)
    select s.id, v_start, v_name, p_ended_on, (public.career_level(s.cxp, v_rules) ->> 'level')::int, s.pts
      from scored s
     where s.pts > 0
    on conflict (athlete_id, starts_on) do nothing;
    get diagnostics v_n = row_count;

    insert into public.hab_titles (athlete_id, title)
    select r.athlete_id, v_title
      from public.hab_season_results r
     where r.starts_on = v_start and r.xp >= v_need
    on conflict (athlete_id, title) do nothing;
    return v_n;
  end if;

  select rules into v_rules from public.xp_rules where id = 1;

  with scored as (
    select a.athlete_id,
           public.hab_xp(public.hab_log_of(a.data, a.athlete_id), v_start, p_ended_on, v_rules)
         + public.hab_bonus_xp(public.hab_log_of(a.data, a.athlete_id),
                               public.hab_cfg_of(a.data, a.athlete_id),
                               v_start, v_start, p_ended_on, v_rules) as xp
    from public.athlete_progress a
    where a.data ? (a.athlete_id || '_hab_log')
  )
  insert into public.hab_season_results (athlete_id, starts_on, season_name, ended_on, level, xp)
  select s.athlete_id, v_start, v_name, p_ended_on,
         public.hab_level(s.xp::bigint, v_rules), s.xp
  from scored s
  where s.xp > 0
  on conflict (athlete_id, starts_on) do nothing;
  get diagnostics v_n = row_count;

  insert into public.hab_titles (athlete_id, title)
  select r.athlete_id, v_title
  from public.hab_season_results r
  where r.starts_on = v_start and r.level >= 5
  on conflict (athlete_id, title) do nothing;

  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.hab_hash(p_s text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare h bigint := 0; i int;
begin
  for i in 1 .. length(p_s) loop
    h := (h * 31 + ascii(substr(p_s, i, 1))) % 2147483647;
  end loop;
  return h;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_level(p_xp bigint, p_rules jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  base numeric := coalesce((p_rules ->> 'base')::numeric, 300);
  growth numeric := coalesce((p_rules ->> 'growth')::numeric, 0.55);
  lv int := 1; spent numeric := 0; cost numeric;
begin
  cost := greatest(10, round(base * power(1, growth) / 10) * 10);
  while lv < 5000 and coalesce(p_xp, 0) - spent >= cost loop
    spent := spent + cost;
    lv := lv + 1;
    cost := greatest(10, round(base * power(lv, growth) / 10) * 10);
  end loop;
  return lv;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_log_of(p_data jsonb, p_athlete_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare t text;
begin
  if p_data is null then return null; end if;
  t := p_data ->> (p_athlete_id || '_hab_log');
  if t is null or btrim(t) = '' then return null; end if;
  begin
    return t::jsonb;
  exception when others then
    return null;
  end;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_mint_titles(p_athlete_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb; v_level int;
begin
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null or v_rules -> 'passTrack' is null then return; end if;
  v_level := public.hab_season_level(p_athlete_id);
  insert into public.hab_titles (athlete_id, title)
  select p_athlete_id, t ->> 'id'
  from jsonb_array_elements(v_rules -> 'passTrack') t
  where t ->> 'kind' = 'title'
    and (t ->> 'lv') is not null
    and (t ->> 'lv')::int > 0
    and v_level >= (t ->> 'lv')::int
  on conflict (athlete_id, title) do nothing;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_notes_floor()
 RETURNS date
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select current_date - 8;
$function$;

CREATE OR REPLACE FUNCTION public.hab_notes_prune()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  delete from public.hab_notes where day < public.hab_notes_floor();
  return null;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_proof_level(p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_rules jsonb; v_data jsonb; v_start date; v_xp bigint;
begin
  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return 1; end if;
  select data into v_data from public.athlete_progress where athlete_id = p_athlete_id;
  if v_data is null then return 1; end if;
  select s.starts_on into v_start from public.current_season() s;
  v_start := coalesce(v_start, '1970-01-01'::date);
  v_xp := public.hab_xp(public.hab_log_of(v_data, p_athlete_id), v_start, current_date, v_rules)
        + public.hab_bonus_xp(public.hab_log_of(v_data, p_athlete_id), public.hab_cfg_of(v_data, p_athlete_id),
                              v_start, v_start, current_date, v_rules);
  return public.hab_level(v_xp, v_rules);
end $function$;

CREATE OR REPLACE FUNCTION public.hab_rank_label(p_level integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  names text[] := array['ROOKIE','CONTENDER','GRINDER','OPERATOR','ENFORCER',
                        'PREDATOR','MACHINE','RELENTLESS','UNTOUCHABLE','IMMORTAL'];
  subs int := 5;
  per_cycle int := 50;
  i int := greatest(0, coalesce(p_level, 1) - 1);
  star int; within int; nm text; sub int;
begin
  star := i / per_cycle;
  within := i % per_cycle;
  nm := names[(within / subs) + 1];
  sub := (within % subs) + 1;
  return case when star > 0 then '★' || star || ' ' else '' end || nm || ' ' || sub;
end; $function$;

CREATE OR REPLACE FUNCTION public.hab_season_level(p_athlete_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if public.career_xp_on() then
    return coalesce((public.career_scored(p_athlete_id) #>> '{career,level}')::int, 1);
  end if;
  return public.hab_proof_level(p_athlete_id);
end $function$;

CREATE OR REPLACE FUNCTION public.hab_xp(p_log jsonb, p_from date, p_to date, p_rules jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  r record; r2 record;
  d date; v numeric; tgt numeric; w numeric;
  bonus numeric := coalesce((p_rules ->> 'completionBonus')::numeric, 1.2);
  custom numeric := coalesce((p_rules ->> 'customXp')::numeric, 25);
  maxcustom int := coalesce((p_rules ->> 'maxCustom')::int, 2147483647);
  ncustom int;
  total numeric := 0;
begin
  if p_log is null or jsonb_typeof(p_log) <> 'object' then return 0; end if;
  for r in select key, value from jsonb_each(p_log) loop
    if jsonb_typeof(r.value) <> 'object' then continue; end if;
    begin
      d := r.key::date;
    exception when others then
      continue;
    end;
    if p_from is not null and d < p_from then continue; end if;
    if p_to   is not null and d > p_to   then continue; end if;
    ncustom := 0;
    for r2 in select key, value from jsonb_each(r.value) loop
      if jsonb_typeof(r2.value) <> 'number' then continue; end if;
      v := (r2.value #>> '{}')::numeric;
      if v <= 0 then continue; end if;
      tgt := coalesce((p_rules -> 'targets' ->> r2.key)::numeric, 1);
      if tgt <= 0 then tgt := 1; end if;
      if (p_rules -> 'weights' ->> r2.key) is null then
        ncustom := ncustom + 1;
        if ncustom > maxcustom then continue; end if;
        w := custom;
      else
        w := (p_rules -> 'weights' ->> r2.key)::numeric;
      end if;
      if v >= tgt then
        total := total + round(w * bonus);
      else
        total := total + round(w * (v / tgt));
      end if;
    end loop;
  end loop;
  return total::bigint;
end; $function$;

CREATE OR REPLACE FUNCTION public.hide_note(p_athlete_id text, p_day date, p_hidden boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  update public.hab_notes n set hidden = p_hidden, updated_at = now()
   where n.athlete_id = p_athlete_id and n.day = p_day;
end; $function$;

CREATE OR REPLACE FUNCTION public.history_detail(e jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when jsonb_typeof(e->'rx') = 'object' then nullif(concat_ws(' · ',
        case when coalesce(e->'rx'->>'rounds', '') <> '' then '×' || (e->'rx'->>'rounds') || ' Rounds' end,
        nullif(concat_ws(' × ', nullif(e->'rx'->>'sets', ''),
               nullif(coalesce(e->'rx'->>'reps', e->'rx'->>'time', e->'rx'->>'distance', e->'rx'->>'work', '')
                      || case when e->'rx'->'side' = 'true'::jsonb then '/side' else '' end, '')), ''),
        case when coalesce(e->'rx'->>'rpe', '') <> '' then 'RPE ' || (e->'rx'->>'rpe') end,
        case when jsonb_typeof(e->'items') = 'array' then
          (select string_agg(i->>'name', ', ' order by n) from jsonb_array_elements(e->'items') with ordinality x(i, n)) end
      ), '')
    else nullif(concat_ws(' · ',
        nullif(e->>'rounds', ''),
        case when jsonb_typeof(e->'chips') = 'array' then
          (select string_agg(coalesce(ch->>'label', ch #>> '{}'), ' · ' order by n)
             from jsonb_array_elements(e->'chips') with ordinality x(ch, n)) end,
        nullif(e->>'detail', ''),
        case when jsonb_typeof(e->'items') = 'array' then
          (select string_agg(i->>'name', ', ' order by n) from jsonb_array_elements(e->'items') with ordinality x(i, n)) end
      ), '')
  end
$function$;

CREATE OR REPLACE FUNCTION public.intake_list()
 RETURNS TABLE(id uuid, created_at timestamp with time zone, lang text, name text, email text, contact text, programme text, status text, handled_at timestamp with time zone, payload jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
  select i.id, i.created_at, i.lang, i.name, i.email, i.contact,
         i.programme, i.status, i.handled_at, i.payload
  from public.hab_intake i
  order by i.created_at desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.is_coach()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select coalesce(auth.jwt() ->> 'email', '') = 'amirardekanian@gmail.com' $function$;

CREATE OR REPLACE FUNCTION public.leaderboard_top(p_athlete_id text, p_key text DEFAULT NULL::text, p_scope text DEFAULT 'season'::text, p_limit integer DEFAULT 10)
 RETURNS TABLE(pos integer, display_name text, title text, xp bigint, level integer, rank_label text, is_me boolean, joined boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected text; v_rules jsonb; v_from date; v_to date; v_joined boolean;
  v_season_start date;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  select exists (select 1 from public.leaderboard_optin o where o.athlete_id = p_athlete_id)
    into v_joined;

  if public.career_xp_on() then
    return query
    with board as (
      select o.athlete_id as aid, o.display_name as dname, o.title as ttl from public.leaderboard_optin o
    ),
    sc as (
      select s.athlete_id as aid, s.score
        from public.career_scores_for((select array_agg(b.aid) from board b), interval '2.5 seconds') s
    ),
    scored as (
      select b.aid, b.dname, b.ttl,
             coalesce(case when p_scope = 'week' then (sc.score #>> '{week,points}')::bigint
                           else (sc.score #>> '{season,points}')::bigint end, 0) as x,
             coalesce((sc.score #>> '{career,level}')::int, 1) as lv,
             coalesce(sc.score #>> '{career,rank}', public.hab_rank_label(1)) as rk
        from board b left join sc on sc.aid = b.aid
    ),
    ranked as (
      select row_number() over (order by s.x desc, lower(s.dname) asc) as rn, s.*
        from scored s
    )
    select r.rn::int, r.dname, r.ttl, r.x, r.lv, r.rk, (r.aid = p_athlete_id), v_joined
      from ranked r
     where r.rn <= greatest(1, p_limit) or r.aid = p_athlete_id
     order by r.rn;
    return;
  end if;

  select rules into v_rules from public.xp_rules where id = 1;
  if v_rules is null then return; end if;

  select s.starts_on into v_season_start from public.current_season() s;
  v_season_start := coalesce(v_season_start, '1970-01-01'::date);
  v_to := current_date;

  if p_scope = 'week' then
    v_from := greatest(current_date - 6, v_season_start);
  else
    v_from := v_season_start;
  end if;

  return query
  with scored as (
    select o.athlete_id as aid,
           o.display_name as dname,
           o.title as ttl,
           ( public.hab_xp(public.hab_log_of(ap.data, o.athlete_id), v_from, v_to, v_rules)
           + public.hab_bonus_xp(public.hab_log_of(ap.data, o.athlete_id),
                                 public.hab_cfg_of(ap.data, o.athlete_id),
                                 v_season_start, v_from, v_to, v_rules) ) as x
    from public.leaderboard_optin o
    left join public.athlete_progress ap on ap.athlete_id = o.athlete_id
  ),
  ranked as (
    select row_number() over (order by s.x desc, lower(s.dname) asc) as rn, s.*
    from scored s
  )
  select r.rn::int,
         r.dname,
         r.ttl,
         r.x,
         public.hab_level(r.x, v_rules),
         public.hab_rank_label(public.hab_level(r.x, v_rules)),
         (r.aid = p_athlete_id),
         v_joined
  from ranked r
  where r.rn <= greatest(1, p_limit) or r.aid = p_athlete_id
  order by r.rn;
end $function$;

CREATE OR REPLACE FUNCTION public.library_sessions_for(p_athlete_id text, p_days integer DEFAULT 10)
 RETURNS TABLE(completed_on date, slug text, title text, category_id text, duration_min integer, counts_as text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  return query
    select s.completed_on, s.slug, s.title, s.category_id, s.duration_min, s.counts_as
    from public.library_sessions s
    where s.athlete_id = p_athlete_id
      and s.completed_on >= current_date - greatest(coalesce(p_days, 10), 1)
    order by s.completed_on desc, s.title;
end;
$function$;

CREATE OR REPLACE FUNCTION public.library_touch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$;

CREATE OR REPLACE FUNCTION public.log_library_session(p_athlete_id text, p_slug text, p_on date DEFAULT NULL::date)
 RETURNS TABLE(logged_on date, counted_as text, workout_title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item   jsonb;
  v_cat    text;
  v_when   date := coalesce(p_on, current_date);
  v_counts text;
  v_title  text;
  v_dur    int;
begin
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() then
    raise exception 'not your athlete record';
  end if;
  if p_slug is null or btrim(p_slug) = '' then
    raise exception 'slug required';
  end if;
  if v_when > current_date or v_when < current_date - 1 then
    raise exception 'completed_on must be today or yesterday';
  end if;

  select l.data, l.category_id into v_item, v_cat
  from public.library l
  where l.slug = p_slug and l.kind = 'workout' and l.published;

  if v_item is null then
    raise exception 'no published workout at that slug';
  end if;

  -- Whitelist, not a cast. One entry per habit a library workout may tick, and
  -- every id here must exist in HABITS in habits.html. 'breathe' joined the list
  -- with the Breath section (2026-09-12). Anything unrecognised counts for
  -- nothing: fail closed, so a new workout can never inflate a score by accident.
  v_counts := case v_item ->> 'countsAs'
                when 'strength' then 'strength'
                when 'mobility' then 'mobility'
                when 'breathe'  then 'breathe'
                else null
              end;
  v_title  := v_item ->> 'title';
  v_dur    := nullif(regexp_replace(coalesce(v_item ->> 'duration', ''), '\D', '', 'g'), '')::int;

  insert into public.library_sessions
    (athlete_id, slug, completed_on, counts_as, title, category_id, duration_min)
  values
    (p_athlete_id, p_slug, v_when, v_counts, v_title, v_cat, v_dur)
  on conflict (athlete_id, slug, completed_on) do update
    set counts_as    = excluded.counts_as,
        title        = excluded.title,
        category_id  = excluded.category_id,
        duration_min = excluded.duration_min;

  return query select v_when, v_counts, v_title;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_athlete_read(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  update public.messages set read_by_athlete = true
    where athlete_id = p_athlete_id and sender = 'coach' and read_by_athlete = false;
end; $function$;

CREATE OR REPLACE FUNCTION public.move_buyer_label()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(new.label), '') is not null then
    insert into public.buyer_notes (user_id, app, note)
    values (new.user_id, tg_argv[0], left(btrim(new.label), 80))
    on conflict (user_id) do update set note = excluded.note, updated_at = now();
  end if;
  new.label := null;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.programme_fingerprint(p_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with recursive walk(path, val) as (
    select k, p.data->k from public.programs p,
           unnest(array['athlete','sport','currentCycleIndex','cycles','workouts','notes']) k
     where p.athlete_id = p_id
    union all
    select w.path || '/' || c.k, c.v from walk w cross join lateral (
      select e.key as k, e.value as v
        from jsonb_each(case when jsonb_typeof(w.val) = 'object' then w.val else '{}'::jsonb end) e
      union all
      select (a.idx - 1)::text, a.value
        from jsonb_array_elements(case when jsonb_typeof(w.val) = 'array' then w.val else '[]'::jsonb end)
             with ordinality a(value, idx)) c)
  select jsonb_build_object(
           'fp', md5(string_agg(path || '=' || (val #>> '{}'), E'\n' order by path collate "C")),
           'leaves', count(*), 'chars', coalesce(sum(length(val #>> '{}')), 0))
    from walk where jsonb_typeof(val) not in ('object', 'array', 'null');
$function$;

CREATE OR REPLACE FUNCTION public.programs_keep_versions_from(p_data jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  idx int := 0;
  s   text;
  d   date;
begin
  begin idx := coalesce((p_data ->> 'currentCycleIndex')::int, 0); exception when others then idx := 0; end;
  if idx < 0 then idx := 0; end if;
  -- the previous cycle's start first, then the current cycle's
  foreach s in array array[
      case when idx >= 1 then p_data -> 'cycles' -> (idx - 1) ->> 'startDate' end,
      p_data -> 'cycles' -> idx ->> 'startDate'] loop
    if s is not null then
      begin d := s::date; exception when others then d := null; end;
      if d is not null then return d::timestamptz; end if;
    end if;
  end loop;
  return now() - interval '70 days';
end; $function$;

CREATE OR REPLACE FUNCTION public.programs_version_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  keep_from timestamptz;
begin
  if old.data is distinct from new.data then
    insert into public.program_versions (athlete_id, data, saved_by)
    values (old.athlete_id, old.data, old.updated_by);

    begin
      keep_from := public.programs_keep_versions_from(new.data);
    exception when others then
      keep_from := now() - interval '70 days';
    end;

    delete from public.program_versions v
     where v.athlete_id = old.athlete_id
       and (
            v.id not in (
              select id from public.program_versions
               where athlete_id = old.athlete_id
               order by id desc
               limit 150)
         or (v.saved_at < keep_from
             and v.id not in (
               select id from public.program_versions
                where athlete_id = old.athlete_id
                order by id desc
                limit 20))
       );
  end if;
  new.updated_at := now();
  new.updated_by := coalesce(
    auth.jwt() ->> 'email',
    case when new.updated_by is not distinct from old.updated_by and old.updated_by like '%@%' then 'sql' else new.updated_by end);
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.publish_cycle(p_athlete_id text, p_workouts jsonb, p_notes jsonb, p_new_cycle boolean, p_cycle_patch jsonb DEFAULT NULL::jsonb, p_cycles jsonb DEFAULT NULL::jsonb, p_sport jsonb DEFAULT NULL::jsonb, p_log_section text DEFAULT NULL::text, p_log_profile text DEFAULT NULL::text, p_log_ledger text DEFAULT NULL::text, p_log_new text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_data jsonb; v_who jsonb; v_cci int; v_n int; v_cycle jsonb; v_entry jsonb; v_key text; v_i int;
  v_body text; v_had_log boolean; v_s int; v_e int; v_len int; v_m text[];
  v_prof boolean := false; v_ledger boolean := false; v_out jsonb;
begin
  if jsonb_typeof(p_workouts->'days') is distinct from 'array' then
    raise exception 'publish_cycle: p_workouts must be {"days": [...]}';
  end if;
  if jsonb_typeof(p_notes) is distinct from 'object' then
    raise exception 'publish_cycle: p_notes must be an object, e.g. {"cards": [...]}';
  end if;

  select p.data into v_data from public.programs p where p.athlete_id = p_athlete_id for update;
  if not found then
    raise exception 'publish_cycle: no programme row for % (run /athlete-intake first)', p_athlete_id;
  end if;
  v_who := v_data->'athlete';
  v_cci := coalesce((v_data->>'currentCycleIndex')::int, 0);

  if p_new_cycle then
    if jsonb_typeof(v_data->'workouts'->'days') is distinct from 'array' then
      raise exception 'publish_cycle: % has no workouts to archive; a new athlete publishes with p_new_cycle = false', p_athlete_id;
    end if;
    v_cycle := v_data->'cycles'->v_cci;
    v_n := coalesce((v_cycle->>'num')::int, v_cci + 1);
    v_entry := jsonb_build_object(
      'id', 'prog' || v_n,
      'label', 'Program ' || lpad(v_n::text, 2, '0') || coalesce(' · ' || nullif(v_cycle->>'name', ''), ''),
      'subtitle', coalesce(nullif(concat_ws(' · ', nullif(v_cycle->>'name', ''), nullif(v_cycle->>'weeks', ''),
                    case when coalesce(v_cycle->>'startDate', '') <> ''
                         then (v_cycle->>'startDate') || coalesce(' → ' || nullif(v_cycle->>'endDate', ''), '') end), ''),
                    'Cycle ' || v_n),
      'days', (select coalesce(jsonb_agg(jsonb_build_object(
                  'label', 'Day ' || coalesce(dd->>'id', dn::text),
                  'focus', coalesce(dd->>'focusTag', ''),
                  'exercises', (select coalesce(jsonb_agg(jsonb_build_object(
                                    'name', ex->>'name', 'detail', coalesce(public.history_detail(ex), '')) order by bn, en), '[]'::jsonb)
                                  from jsonb_array_elements(case when jsonb_typeof(dd->'blocks') = 'array' then dd->'blocks' else '[]'::jsonb end)
                                       with ordinality bx(b, bn)
                                  cross join lateral jsonb_array_elements(case when jsonb_typeof(b->'exercises') = 'array' then b->'exercises' else '[]'::jsonb end)
                                       with ordinality exx(ex, en))
                ) order by dn), '[]'::jsonb)
               from jsonb_array_elements(v_data->'workouts'->'days') with ordinality dx(dd, dn)));
    v_data := jsonb_set(v_data, '{programHistory}', jsonb_build_array(v_entry)
              || case when jsonb_typeof(v_data->'programHistory') = 'array' then v_data->'programHistory' else '[]'::jsonb end);
    v_cci := v_cci + 1;
  end if;
  v_data := jsonb_set(v_data, '{currentCycleIndex}', to_jsonb(v_cci));

  if p_cycles is not null then
    if jsonb_typeof(v_data->'cycles') = 'array' and jsonb_array_length(v_data->'cycles') > 0 then
      raise exception 'publish_cycle: % already has a roadmap; change it through p_cycle_patch (a roadmap_amend: line, PRC-17)', p_athlete_id;
    end if;
    v_data := v_data || jsonb_build_object('cycles', p_cycles);
  end if;
  if p_cycle_patch is not null then
    for v_key in select jsonb_object_keys(p_cycle_patch) loop
      v_i := v_key::int;
      if jsonb_typeof(v_data->'cycles') is distinct from 'array' or v_i < 0 or v_i >= jsonb_array_length(v_data->'cycles') then
        raise exception 'publish_cycle: cycle index % is not in the roadmap', v_key;
      end if;
      if jsonb_typeof(p_cycle_patch->v_key) is distinct from 'object' then
        raise exception 'publish_cycle: the patch for cycle % must be an object of fields', v_key;
      end if;
      v_data := jsonb_set(v_data, array['cycles', v_key], (v_data->'cycles'->v_i) || (p_cycle_patch->v_key));
    end loop;
  end if;
  if jsonb_typeof(v_data->'cycles') is distinct from 'array' or v_cci >= jsonb_array_length(v_data->'cycles') then
    raise exception 'publish_cycle: currentCycleIndex % has no cycle in the roadmap', v_cci;
  end if;

  v_data := v_data || jsonb_build_object('workouts', p_workouts, 'notes', p_notes);
  if p_sport is not null then v_data := v_data || jsonb_build_object('sport', p_sport); end if;
  if (v_data->'athlete') is distinct from v_who then
    raise exception 'publish_cycle: the athlete block would change';
  end if;
  update public.programs set data = v_data, updated_by = 'publish_cycle' where athlete_id = p_athlete_id;
  v_out := jsonb_build_object('athlete_id', p_athlete_id, 'currentCycleIndex', v_cci,
             'archived', case when p_new_cycle then v_entry->>'id' end,
             'fingerprint', public.programme_fingerprint(p_athlete_id));

  if coalesce(p_log_section, p_log_profile, p_log_ledger, p_log_new) is not null then
    select l.body into v_body from public.coaching_logs l where l.athlete_id = p_athlete_id for update;
    v_had_log := found;
    if not v_had_log then
      if p_log_new is null then
        raise exception 'publish_cycle: % has no coaching log yet; pass p_log_new', p_athlete_id;
      end if;
      v_body := p_log_new;
    elsif p_log_new is not null then
      raise exception 'publish_cycle: % already has a coaching log; p_log_new is for a first one only', p_athlete_id;
    end if;

    if p_log_profile is not null then
      v_s := strpos(v_body, '```profile');
      if v_s > 0 then
        v_e := strpos(substr(v_body, v_s + 10), '```');
        if v_e = 0 then raise exception 'publish_cycle: the profile block in the log has no closing fence'; end if;
        v_body := substr(v_body, 1, v_s - 1) || p_log_profile || substr(v_body, v_s + v_e + 12);
      else
        v_s := coalesce(nullif(strpos(v_body, E'\n## Exercise Ledger'), 0) + 1,
                        nullif(regexp_instr(v_body, '\|\s*Exercise\s*\|\s*Status'), 0));
        if v_s is null then
          v_s := coalesce(nullif(strpos(v_body, E'\n## '), 0) + 1, length(v_body) + 1);
        end if;
        v_body := substr(v_body, 1, v_s - 1) || '## Athlete profile' || E'\n' || p_log_profile || E'\n\n' || substr(v_body, v_s);
      end if;
      v_prof := true;
    end if;

    if p_log_ledger is not null then
      v_s := regexp_instr(v_body, '\|\s*Exercise\s*\|\s*Status');
      if v_s > 0 then
        v_m := regexp_match(substr(v_body, v_s), '^((?:\|[^\n]*(?:\n|$))+)');
        v_len := length(v_m[1]);
        v_body := substr(v_body, 1, v_s - 1) || rtrim(p_log_ledger, E'\n') || E'\n' || substr(v_body, v_s + v_len);
      else
        v_s := coalesce(nullif(strpos(v_body, E'\n## Roadmap'), 0), nullif(strpos(v_body, E'\n## Cycle'), 0));
        if v_s is null then v_s := length(v_body) + 1; else v_s := v_s + 1; end if;
        v_body := substr(v_body, 1, v_s - 1) || '## Exercise Ledger' || E'\n\n' || rtrim(p_log_ledger, E'\n') || E'\n\n' || substr(v_body, v_s);
      end if;
      v_ledger := true;
    end if;

    if p_log_section is not null then
      v_body := rtrim(v_body, E'\n') || E'\n\n' || p_log_section;
    end if;

    if v_had_log then
      update public.coaching_logs set body = v_body where athlete_id = p_athlete_id;
    else
      insert into public.coaching_logs (athlete_id, body) values (p_athlete_id, v_body);
    end if;
    v_out := v_out || jsonb_build_object('log', jsonb_build_object(
               'md5', md5(v_body), 'length', length(v_body), 'first_log', not v_had_log,
               'profile_replaced', v_prof, 'ledger_replaced', v_ledger,
               'section_at_end', p_log_section is null or right(v_body, length(p_log_section)) = p_log_section));
  end if;
  return v_out;
end
$function$;

CREATE OR REPLACE FUNCTION public.purge_old_notes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  delete from public.hab_notes where day < public.hab_notes_floor();
  get diagnostics v_n = row_count;
  return v_n;
end; $function$;

CREATE OR REPLACE FUNCTION public.roll_call(p_athlete_id text, p_key text DEFAULT NULL::text, p_days integer DEFAULT 7)
 RETURNS TABLE(day date, display_name text, title text, body text, pct smallint, rank_label text, is_me boolean, is_coach boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected text; v_rules jsonb; v_from date; v_season_start date;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  select rules into v_rules from public.xp_rules where id = 1;
  select s.starts_on into v_season_start from public.current_season() s;
  v_from := current_date - greatest(1, least(60, coalesce(p_days, 7)));

  return query
  with visible as (
    select n.athlete_id as aid, n.day as d, o.display_name as dname, o.title as ttl,
           n.body as b, n.pct as p, n.updated_at as ua, false as coach
    from public.hab_notes n
    join public.leaderboard_optin o on o.athlete_id = n.athlete_id
    where not n.hidden and n.day >= v_from and n.day <= current_date + 1
    union all
    select n.athlete_id, n.day, 'AMIR'::text, null::text,
           n.body, n.pct, n.updated_at, true
    from public.hab_notes n
    where n.athlete_id = public.coach_note_id()
      and not n.hidden and n.day >= v_from and n.day <= current_date + 1
  ),
  scored as (
    select v.aid as said,
           public.hab_rank_label(public.hab_level(
             ( public.hab_xp(public.hab_log_of(ap.data, v.aid),
                             v_season_start, current_date, v_rules)
             + public.hab_bonus_xp(public.hab_log_of(ap.data, v.aid),
                                   public.hab_cfg_of(ap.data, v.aid),
                                   v_season_start, v_season_start, current_date, v_rules) ),
             v_rules)) as rlabel
    from (select distinct aid from visible where not coach) v
    left join public.athlete_progress ap on ap.athlete_id = v.aid
  )
  select vi.d, vi.dname, vi.ttl, vi.b, vi.p,
         sc.rlabel, (vi.aid = p_athlete_id), vi.coach
  from visible vi
  left join scored sc on sc.said = vi.aid
  order by vi.d desc, vi.coach desc, vi.ua desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.save_progress(p_athlete_id text, p_athlete_name text, p_data jsonb, p_key text DEFAULT NULL::text, p_drop text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_expected text;
  v_drop     text[];
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  select coalesce(array_agg(k), '{}'::text[])
    into v_drop
    from unnest(coalesce(p_drop, '{}'::text[])) as k
   where left(k, length(p_athlete_id) + 1) =  p_athlete_id || '_'
     and left(k, length(p_athlete_id) + 5) <> p_athlete_id || '_hab_';

  insert into public.athlete_progress (athlete_id, athlete_name, data, updated_at)
  values (p_athlete_id, p_athlete_name, p_data, now())
  on conflict (athlete_id) do update
    set athlete_name = excluded.athlete_name,
        data         = (athlete_progress.data - v_drop) || excluded.data,
        updated_at   = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_session(p_athlete_id text, p_athlete_name text, p_day integer, p_completed_on date, p_session jsonb, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
        v_replace boolean := public.is_coach() and coalesce((p_session->>'replace_log')::boolean, false);
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  insert into public.session_history
    (athlete_id, athlete_name, day, completed_on, status, session_rpe,
     duration_min, readiness, day_note, focus, summary, log, updated_at)
  values (
    p_athlete_id, p_athlete_name, p_day, p_completed_on,
    p_session->>'status', round(nullif(p_session->>'session_rpe','')::numeric)::int,
    round(nullif(p_session->>'duration_min','')::numeric)::int, p_session->'readiness',
    p_session->>'day_note', p_session->>'focus', p_session->>'summary',
    case when jsonb_typeof(p_session->'log') = 'array' then p_session->'log' end,
    now())
  on conflict (athlete_id, day, completed_on) do update
    set athlete_name = excluded.athlete_name, status = excluded.status,
        session_rpe = excluded.session_rpe, duration_min = excluded.duration_min,
        readiness = excluded.readiness, day_note = excluded.day_note,
        focus = excluded.focus, summary = excluded.summary,
        log = case when v_replace then excluded.log else coalesce(excluded.log, session_history.log) end,
        coach_status = case
          when not public.is_coach()
           and ((coalesce(btrim(excluded.day_note), '') <> '' and excluded.day_note is distinct from session_history.day_note)
             or (public.session_ex_notes(excluded.log, excluded.summary) <> ''
             and public.session_ex_notes(excluded.log, excluded.summary)
                 is distinct from public.session_ex_notes(session_history.log, session_history.summary))) then 'new'
          else session_history.coach_status end,
        -- stage60: the phone re-sending a session the coach hid leaves it hidden; the coach saving over it brings it back.
        hidden_at = case when public.is_coach() then null else session_history.hidden_at end,
        hidden_by = case when public.is_coach() then null else session_history.hidden_by end,
        updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.season_list()
 RETURNS TABLE(starts_on date, name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.starts_on, s.name from public.seasons s order by s.starts_on;
$function$;

CREATE OR REPLACE FUNCTION public.season_record(p_athlete_id text, p_key text DEFAULT NULL::text)
 RETURNS TABLE(starts_on date, season_name text, ended_on date, level integer, xp bigint, title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  return query
    select r.starts_on, r.season_name, r.ended_on, r.level, r.xp, t.title
    from public.hab_season_results r
    left join public.hab_titles t
      on t.athlete_id = r.athlete_id
     and t.title = 't_sn_' || to_char(r.starts_on, 'YYYYMMDD')
    where r.athlete_id = p_athlete_id
    order by r.starts_on desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.send_athlete_message(p_athlete_id text, p_body text, p_context text DEFAULT NULL::text, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;
  if coalesce(btrim(p_body), '') = '' then return; end if;
  insert into public.messages (athlete_id, sender, body, context, read_by_athlete, read_by_coach)
  values (p_athlete_id, 'athlete', left(p_body, 2000), p_context, true, false);
end; $function$;

CREATE OR REPLACE FUNCTION public.session_ex_notes(p_log jsonb, p_summary text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(case
    when jsonb_typeof(p_log) = 'array' then
      (select string_agg(btrim(t.e ->> 'note'), E'\n' order by t.ord)
         from jsonb_array_elements(p_log) with ordinality as t(e, ord)
        where coalesce(btrim(t.e ->> 'note'), '') <> '')
    else
      (select string_agg(btrim(r.m[1]), E'\n')
         from regexp_matches(coalesce(p_summary, ''), '(?:^|\n)[ \t]+Note:[ \t]*([^\n]*)', 'g') as r(m)
        where btrim(r.m[1]) <> '')
  end, '');
$function$;

CREATE OR REPLACE FUNCTION public.set_coach_note(p_body text, p_day date DEFAULT CURRENT_DATE)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_body text;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  v_body := public.hab_clean_note(p_body);
  if v_body = '' then
    delete from public.hab_notes n
     where n.athlete_id = public.coach_note_id() and n.day = p_day;
    return;
  end if;
  insert into public.hab_notes (athlete_id, day, body)
  values (public.coach_note_id(), p_day, v_body)
  on conflict (athlete_id, day) do update
    set body = excluded.body, updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.set_day_note(p_athlete_id text, p_key text DEFAULT NULL::text, p_day date DEFAULT NULL::date, p_body text DEFAULT NULL::text, p_pct integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_body text; v_day date;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  if p_athlete_id = public.coach_note_id() then
    raise exception 'reserved id';
  end if;

  if not exists (select 1 from public.leaderboard_optin o where o.athlete_id = p_athlete_id) then
    raise exception 'join the leaderboard before posting';
  end if;

  -- TODAY ONLY, but "today" is the athlete's, not the server's. A one-day
  -- tolerance either side covers every timezone without allowing edits to history.
  v_day := coalesce(p_day, current_date);
  if v_day > current_date + 1 or v_day < current_date - 1 then
    raise exception 'you can only write today''s line';
  end if;

  v_body := public.hab_clean_note(p_body);

  if v_body = '' then
    delete from public.hab_notes n where n.athlete_id = p_athlete_id and n.day = v_day;
    return;
  end if;

  insert into public.hab_notes (athlete_id, day, body, pct)
  values (p_athlete_id, v_day, v_body,
          case when p_pct is null then null
               else greatest(0, least(100, p_pct))::smallint end)
  on conflict (athlete_id, day) do update
    set body = excluded.body, pct = excluded.pct, updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.set_intake_outcome(p_id uuid, p_outcome text, p_athlete_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ath text := nullif(btrim(coalesce(p_athlete_id, '')), ''); v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_outcome is not null and p_outcome not in ('client', 'free', 'not_a_fit', 'no_reply', 'declined', 'other') then
    raise exception 'bad intake outcome: %', p_outcome;
  end if;
  if p_outcome is null or p_outcome not in ('client', 'free') then
    v_ath := null;      -- only an application that became someone keeps the link
  end if;
  if p_outcome = 'client' and v_ath is null then
    raise exception 'pick the athlete this application became';
  end if;
  if v_ath is not null
     and not exists (select 1 from public.programs p where p.athlete_id = v_ath)
     and not exists (select 1 from public.hab_contacts c where c.athlete_id = v_ath) then
    raise exception 'there is no athlete called "%"', v_ath;
  end if;
  update public.hab_intake i
     set outcome    = p_outcome,
         athlete_id = v_ath,
         linked_at  = case when v_ath is null then null
                           when i.athlete_id is not distinct from v_ath then i.linked_at
                           else now() end,
         status     = case when p_outcome is not null and i.status = 'new' then 'handled' else i.status end,
         handled_at = case when p_outcome is not null and i.status = 'new' then now() else i.handled_at end
   where i.id = p_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then
    raise exception 'no such application';
  end if;
  return jsonb_build_object('outcome', p_outcome, 'athlete_id', v_ath);
end $function$;

CREATE OR REPLACE FUNCTION public.set_intake_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_status not in ('new', 'handled', 'archived') then
    raise exception 'bad intake status: %', p_status;
  end if;
  update public.hab_intake
     set status     = p_status,
         handled_at = case when p_status = 'new' then null
                           else coalesce(handled_at, now()) end
   where id = p_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.set_leaderboard_optin(p_athlete_id text, p_display_name text, p_opt_in boolean, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_name text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  if not p_opt_in then
    delete from public.leaderboard_optin where athlete_id = p_athlete_id;
    return;
  end if;

  v_name := btrim(regexp_replace(coalesce(p_display_name, ''), '[<>"''\\]', '', 'g'));
  v_name := left(v_name, 24);
  if v_name = '' then v_name := 'ATHLETE'; end if;

  insert into public.leaderboard_optin (athlete_id, display_name)
  values (p_athlete_id, v_name)
  on conflict (athlete_id) do update
    set display_name = excluded.display_name, updated_at = now();
end; $function$;

CREATE OR REPLACE FUNCTION public.set_quests(p_start date, p_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text; v_runs jsonb; v_kept jsonb := '[]'::jsonb; r jsonb;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  if p_ids is null or array_length(p_ids, 1) is null then
    raise exception 'give at least one quest id, or use clear_quests()';
  end if;
  v_key := to_char(p_start, 'YYYY-MM-DD');
  select coalesce(rules -> 'questRuns', '[]'::jsonb) into v_runs from public.xp_rules where id = 1;
  for r in select value from jsonb_array_elements(v_runs) loop
    if r ->> 'start' is distinct from v_key then v_kept := v_kept || jsonb_build_array(r); end if;
  end loop;
  v_kept := v_kept || jsonb_build_array(jsonb_build_object('start', v_key, 'ids', to_jsonb(p_ids)));
  update public.xp_rules
     set rules = jsonb_set(rules, '{questRuns}', v_kept), updated_at = now()
   where id = 1;
  return v_kept;
end; $function$;

CREATE OR REPLACE FUNCTION public.set_title(p_athlete_id text, p_title text, p_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_expected text; v_rules jsonb; v_entry jsonb; v_need int; v_title text;
begin
  select secret_key into v_expected from public.athlete_keys where athlete_id = p_athlete_id;
  if not public.is_coach() and p_athlete_id is distinct from public.current_athlete_id() and (v_expected is null or p_key is null or p_key is distinct from v_expected) then
    raise exception 'invalid athlete key';
  end if;

  v_title := nullif(btrim(coalesce(p_title, '')), '');

  if v_title is not null then
    select rules into v_rules from public.xp_rules where id = 1;
    select t into v_entry
      from jsonb_array_elements(coalesce(v_rules -> 'passTrack', '[]'::jsonb)) t
      where t ->> 'id' = v_title and t ->> 'kind' = 'title'
      limit 1;

    if v_entry is null then
      if not exists (select 1 from public.hab_titles t
                     where t.athlete_id = p_athlete_id and t.title = v_title) then
        raise exception 'unknown title';
      end if;
    else
      v_need := nullif(v_entry ->> 'lv', '')::int;
      if v_need is not null and v_need > 0 then
        perform public.hab_mint_titles(p_athlete_id);
        if not exists (select 1 from public.hab_titles t
                       where t.athlete_id = p_athlete_id and t.title = v_title) then
          raise exception 'title not earned: % needs level %', v_title, v_need;
        end if;
      else
        insert into public.hab_titles (athlete_id, title)
        values (p_athlete_id, v_title)
        on conflict (athlete_id, title) do nothing;
      end if;
    end if;
  end if;

  update public.leaderboard_optin set title = v_title, updated_at = now()
  where athlete_id = p_athlete_id;
  if not found then raise exception 'join the board first'; end if;
end; $function$;

CREATE OR REPLACE FUNCTION public.spine_credits_ok(c jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select c is null or (jsonb_typeof(c) = 'object' and not exists (
    select 1 from jsonb_each(c) e(k, v)
    where e.k not in ('quads', 'hamstrings', 'glutes', 'adductors', 'calves', 'shins', 'peroneals', 'back',
                      'chest', 'shoulder', 'biceps', 'triceps', 'forearm', 'core', 'neck')
       or jsonb_typeof(e.v) <> 'number' or (e.v #>> '{}')::numeric not in (0.5, 1)))
$function$;

CREATE OR REPLACE FUNCTION public.spine_keep_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o   jsonb := to_jsonb(old);
  n   jsonb;
  ch  jsonb;
  who text := coalesce(auth.jwt() ->> 'email', 'sql');
begin
  if tg_op = 'DELETE' then
    insert into public.spine_versions (tbl, row_id, op, data, saved_by, was_updated_at)
    values (tg_table_name, old.id, 'delete', o, who, nullif(o ->> 'updated_at', '')::timestamptz);
    return old;
  end if;
  n := to_jsonb(new);
  select coalesce(jsonb_object_agg(e.key, n -> e.key), '{}'::jsonb) into ch
    from jsonb_each(o) e
   where e.key not in ('updated_at', 'updated_by')
     and (n -> e.key) is distinct from e.value;
  if ch = '{}'::jsonb then
    return new;
  end if;
  insert into public.spine_versions (tbl, row_id, op, data, changed, saved_by, was_updated_at)
  values (tg_table_name, old.id, 'update', o, ch, who, nullif(o ->> 'updated_at', '')::timestamptz);
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.spine_steps_ok(s text[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  -- One list, 0 to 6 lines, none blank (only spaces, tabs or line breaks count as blank), none over 140 characters.
  select s is null or (coalesce(array_ndims(s), 1) = 1 and coalesce(cardinality(s), 0) <= 6 and not exists (
    select 1 from unnest(s) x where x is null or x !~ '\S' or char_length(x) > 140))
$function$;

CREATE OR REPLACE FUNCTION public.start_season(p_name text, p_starts_on date DEFAULT CURRENT_DATE)
 RETURNS TABLE(name text, starts_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_latest date; v_n integer;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;

  if coalesce(btrim(p_name), '') = '' then
    raise exception 'a season needs a name';
  end if;

  if p_starts_on > current_date then
    raise exception 'a season cannot start in the future (%) — run this on the day it begins', p_starts_on;
  end if;

  select max(s.starts_on) into v_latest from public.seasons s;
  if v_latest is not null and p_starts_on <= v_latest then
    raise exception 'the new season (%) must start after the latest one (%)', p_starts_on, v_latest;
  end if;

  v_n := public.hab_close_season(p_starts_on - 1);
  raise notice 'archived % athlete season record(s)', v_n;

  insert into public.seasons (name, starts_on) values (btrim(p_name), p_starts_on);
  return query select * from public.current_season();
end; $function$;

CREATE OR REPLACE FUNCTION public.submit_intake(p_payload jsonb, p_lang text DEFAULT 'en'::text, p_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_contact text DEFAULT NULL::text, p_programme text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_payload is null or jsonb_typeof(p_payload) is distinct from 'object'
     or p_payload = '{}'::jsonb then
    raise exception 'intake payload must be a non-empty object';
  end if;
  if char_length(p_payload::text) > 60000 then
    raise exception 'intake payload too large';
  end if;

  insert into public.hab_intake (lang, name, email, contact, programme, payload)
  values (
    coalesce(nullif(lower(btrim(p_lang)), ''), 'en'),
    nullif(left(btrim(coalesce(p_name, '')),     200), ''),
    nullif(left(btrim(coalesce(p_email, '')),    200), ''),
    nullif(left(btrim(coalesce(p_contact, '')),  200), ''),
    nullif(left(btrim(coalesce(p_programme, '')),200), ''),
    p_payload)
  returning id into v_id;

  return v_id;
end; $function$;

CREATE OR REPLACE FUNCTION public.touch_affiliates_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
