  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.tps_demo()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with cfg as (
  select array[1]::int[] as weeks,
         array['broad-jump']::text[] as tests,
         array['read-your-card', 'rpe-weights', 'tennis-demands']::text[] as lessons
),
prog_rows as (
  select r.key, r.body from public.tps_content r where r.key ~ '^programme(-[0-9]+)?$'
),
free_weeks as (
  select wk.w from prog_rows p cross join cfg
    cross join lateral jsonb_array_elements(case when jsonb_typeof(p.body->'weeks') = 'array' then p.body->'weeks' else '[]'::jsonb end) as wk(w)
  where (wk.w->>'week') ~ '^[0-9]+$' and (wk.w->>'week')::int = any(cfg.weeks)
),
prog_extra as (
  select coalesce(jsonb_object_agg(ee.key, ee.value order by p.key), '{}'::jsonb) as obj
  from prog_rows p cross join lateral jsonb_each(p.body - 'weeks' - '_notes') as ee(key, value)
),
free_sessions as (
  select ss.s from free_weeks fw
    cross join lateral jsonb_each(case when jsonb_typeof(fw.w->'plans') = 'object' then fw.w->'plans' else '{}'::jsonb end) as pl(age, plan)
    cross join lateral jsonb_array_elements(
      (case when jsonb_typeof(pl.plan->'core') = 'array' then pl.plan->'core' else '[]'::jsonb end) ||
      (case when jsonb_typeof(pl.plan->'addons') = 'array' then pl.plan->'addons' else '[]'::jsonb end)) as ss(s)
),
free_items as (
  select ii.it from free_sessions fs
    cross join lateral jsonb_array_elements(case when jsonb_typeof(fs.s->'groups') = 'array' then fs.s->'groups' else '[]'::jsonb end) as gg(g)
    cross join lateral jsonb_array_elements(case when jsonb_typeof(gg.g->'items') = 'array' then gg.g->'items' else '[]'::jsonb end) as ii(it)
),
used as (
  select fi.it->>'ex' as id from free_items fi where fi.it->>'ex' is not null
  union
  select fi.it->>'alt' from free_items fi where fi.it->>'alt' is not null
),
exercise_map as (
  select coalesce(jsonb_object_agg(ee.key,
    case when u.id is not null then ee.value
         else jsonb_strip_nulls(jsonb_build_object('name', ee.value->'name', 'nameEn', ee.value->'nameEn',
           'slot', ee.value->'slot', 'slotTitle', ee.value->'slotTitle', 'locked', true)) end
    order by r.key), '{}'::jsonb) as obj
  from public.tps_content r
    cross join lateral jsonb_each(case when jsonb_typeof(r.body->'exercises') = 'object' then r.body->'exercises' else '{}'::jsonb end) as ee(key, value)
    left join used u on u.id = ee.key
  where r.key ~ '^exercises(-[0-9]+)?$'
),
lesson_rows as (
  select r.key, ll.l, ll.n from public.tps_content r
    cross join lateral jsonb_array_elements(case when jsonb_typeof(r.body->'lessons') = 'array' then r.body->'lessons' else '[]'::jsonb end) with ordinality as ll(l, n)
  where r.key ~ '^learn(-[0-9]+)?$'
),
lesson_list as (
  select coalesce(jsonb_agg(
    case when lr.l->>'id' = any(cfg.lessons) then lr.l
         else jsonb_strip_nulls(jsonb_build_object('id', lr.l->'id', 'order', lr.l->'order', 'group', lr.l->'group',
           'icon', lr.l->'icon', 'title', lr.l->'title', 'summary', lr.l->'summary', 'audience', lr.l->'audience', 'locked', true)) end
    order by lr.key, lr.n), '[]'::jsonb) as arr
  from lesson_rows lr cross join cfg
),
test_rows as (
  select tt.t, tt.n from public.tps_content r
    cross join lateral jsonb_array_elements(case when jsonb_typeof(r.body->'tests') = 'array' then r.body->'tests' else '[]'::jsonb end) with ordinality as tt(t, n)
  where r.key = 'tests'
),
test_list as (
  select coalesce(jsonb_agg(
    case when tr.t->>'id' = any(cfg.tests) then tr.t
         else jsonb_strip_nulls(jsonb_build_object('id', tr.t->'id', 'icon', tr.t->'icon', 'title', tr.t->'title',
           'badge', tr.t->'badge', 'why', tr.t->'why', 'optional', tr.t->'optional',
           'player', tr.t->'player', 'calc', tr.t->'calc', 'locked', true)) end
    order by tr.n), '[]'::jsonb) as arr
  from test_rows tr cross join cfg
),
missing as (
  select coalesce(jsonb_agg(q.m), '[]'::jsonb) as arr from (
    select 'week ' || uw.wk as m from cfg cross join lateral unnest(cfg.weeks) as uw(wk)
      where not exists (select 1 from free_weeks fw where (fw.w->>'week')::int = uw.wk)
    union all
    select 'test ' || ut.id from cfg cross join lateral unnest(cfg.tests) as ut(id)
      where not exists (select 1 from test_rows tr where tr.t->>'id' = ut.id)
    union all
    select 'lesson ' || ul.id from cfg cross join lateral unnest(cfg.lessons) as ul(id)
      where not exists (select 1 from lesson_rows lr where lr.l->>'id' = ul.id)
  ) q
)
select jsonb_build_object(
  'demo', jsonb_build_object('weeks', to_jsonb(cfg.weeks), 'tests', to_jsonb(cfg.tests),
    'lessons', to_jsonb(cfg.lessons), 'missing', missing.arr),
  'start', (select r.body - '_notes' from public.tps_content r where r.key = 'start'),
  'programme', prog_extra.obj || jsonb_build_object('weeks',
    (select coalesce(jsonb_agg(fw.w order by (fw.w->>'week')::int), '[]'::jsonb) from free_weeks fw)),
  'exercises', jsonb_build_object('exercises', exercise_map.obj),
  'learn', jsonb_build_object('lessons', lesson_list.arr),
  'tests', jsonb_build_object('day', (select r.body->'day' from public.tps_content r where r.key = 'tests'), 'tests', test_list.arr),
  'library', (select r.body - '_notes' from public.tps_content r where r.key = 'library')
)
from cfg, prog_extra, exercise_map, lesson_list, test_list, missing
$function$;

CREATE OR REPLACE FUNCTION public.tps_member()
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select exists (select 1 from public.tps_accounts a where a.user_id = auth.uid() and a.revoked_at is null) $function$;

CREATE OR REPLACE FUNCTION public.tps_publish(p_token text, p_key text, p_body jsonb, p_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_token is null or length(p_token) < 40 or not exists (
       select 1 from public.tps_publish_keys k
       where k.key_hash = encode(sha256(convert_to(p_token, 'UTF8')), 'hex')) then
    raise exception 'not allowed';
  end if;
  insert into public.tps_content (key, body, version, updated_at)
  values (p_key, p_body, p_version, now())
  on conflict (key) do update set body = excluded.body, version = excluded.version, updated_at = now();
end $function$;

CREATE OR REPLACE FUNCTION public.undo_season(p_starts_on date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prev date; v_arch int; v_seas int;
begin
  if not public.is_coach() then
    raise exception 'coach only';
  end if;
  select max(s.starts_on) into v_prev from public.seasons s where s.starts_on < p_starts_on;
  delete from public.seasons where starts_on = p_starts_on;
  get diagnostics v_seas = row_count;
  if v_seas = 0 then return 'no season starts on ' || p_starts_on; end if;
  delete from public.hab_season_results where starts_on = v_prev;
  get diagnostics v_arch = row_count;
  return format('removed season %s and %s archived record(s) for the season starting %s; '
             || 'titles already minted are kept, by design', p_starts_on, v_arch, v_prev);
end; $function$;

-- ── 4. constraints ───────────────────────────────────────────────────────────
alter table public.affiliates add constraint affiliates_code_shape CHECK ((code ~ '^[A-Z0-9]{2,32}$'::text));
alter table public.affiliates add constraint affiliates_percent_range CHECK (((percent >= 1) AND (percent <= 90)));
alter table public.affiliates add constraint affiliates_pkey PRIMARY KEY (code);
alter table public.assess_accounts add constraint assess_accounts_label_check CHECK (((label IS NULL) OR (length(label) <= 80)));
alter table public.assess_accounts add constraint assess_accounts_pkey PRIMARY KEY (user_id);
alter table public.assess_accounts add constraint assess_accounts_username_check CHECK ((username ~ '^[a-z0-9_]{3,32}$'::text));
alter table public.assess_accounts add constraint assess_accounts_username_key UNIQUE (username);
alter table public.assess_content add constraint assess_content_key_check CHECK ((key ~ '^[a-z0-9-]{1,40}$'::text));
alter table public.assess_content add constraint assess_content_pkey PRIMARY KEY (key);
alter table public.assess_notes add constraint assess_notes_body_check CHECK (((length(btrim(body)) >= 1) AND (length(btrim(body)) <= 300)));
alter table public.assess_notes add constraint assess_notes_pkey PRIMARY KEY (id);
alter table public.assess_players add constraint assess_players_birth_month_check CHECK (((birth_month >= 1) AND (birth_month <= 12)));
alter table public.assess_players add constraint assess_players_birth_year_check CHECK (((birth_year >= 1300) AND (birth_year <= 1410)));
alter table public.assess_players add constraint assess_players_hand_check CHECK ((hand = ANY (ARRAY['r'::text, 'l'::text])));
alter table public.assess_players add constraint assess_players_id_account_id_key UNIQUE (id, account_id);
alter table public.assess_players add constraint assess_players_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 60)));
alter table public.assess_players add constraint assess_players_pkey PRIMARY KEY (id);
alter table public.assess_players add constraint assess_players_sex_check CHECK ((sex = ANY (ARRAY['m'::text, 'f'::text])));
alter table public.assess_players add constraint assess_players_squad_check CHECK (((squad IS NULL) OR (length(squad) <= 40)));
alter table public.assess_publish_keys add constraint assess_publish_keys_pkey PRIMARY KEY (key_hash);
alter table public.assess_results add constraint assess_results_day_check CHECK ((day ~ '^1[34][0-9]{2}/(0[1-9]|1[0-2])/(0[1-9]|[12][0-9]|3[01])$'::text));
alter table public.assess_results add constraint assess_results_extra_check CHECK (((extra IS NULL) OR ((jsonb_typeof(extra) = 'object'::text) AND (length((extra)::text) <= 500))));
alter table public.assess_results add constraint assess_results_pkey PRIMARY KEY (player_id, test, day);
alter table public.assess_results add constraint assess_results_test_check CHECK ((test ~ '^[A-Za-z0-9-]{1,20}$'::text));
alter table public.athlete_identities add constraint athlete_identities_athlete_id_key UNIQUE (athlete_id);
alter table public.athlete_identities add constraint athlete_identities_pkey PRIMARY KEY (user_id);
alter table public.athlete_keys add constraint athlete_keys_pkey PRIMARY KEY (athlete_id);
alter table public.athlete_progress add constraint athlete_progress_pkey PRIMARY KEY (athlete_id);
alter table public.athlete_status add constraint athlete_status_pkey PRIMARY KEY (athlete_id);
alter table public.athlete_status add constraint athlete_status_status_check CHECK ((status = ANY (ARRAY['paused'::text, 'former'::text])));
alter table public.buyer_notes add constraint buyer_notes_app_check CHECK ((app = ANY (ARRAY['course'::text, 'testing'::text])));
alter table public.buyer_notes add constraint buyer_notes_note_check CHECK (((note IS NULL) OR (length(note) <= 80)));
alter table public.buyer_notes add constraint buyer_notes_pkey PRIMARY KEY (user_id);
alter table public.call_logs add constraint call_logs_athlete_id_call_date_key UNIQUE (athlete_id, call_date);
alter table public.call_logs add constraint call_logs_pkey PRIMARY KEY (id);
alter table public.career_catalogue add constraint career_catalogue_body_check CHECK ((jsonb_typeof(body) = 'object'::text));
alter table public.career_catalogue add constraint career_catalogue_id_check CHECK ((id ~ '^[a-z][a-z0-9_]*$'::text));
alter table public.career_catalogue add constraint career_catalogue_kind_check CHECK ((kind = ANY (ARRAY['badge'::text, 'achievement'::text, 'title'::text, 'skin'::text, 'mission'::text, 'quest'::text, 'size'::text, 'message'::text, 'tool'::text, 'setting'::text])));
alter table public.career_catalogue add constraint career_catalogue_pkey PRIMARY KEY (kind, id);
alter table public.career_facts add constraint career_facts_kind_check CHECK ((kind ~ '^[a-z][a-z0-9_]*$'::text));
alter table public.career_facts add constraint career_facts_pkey PRIMARY KEY (athlete_id, kind, ref);
alter table public.career_facts add constraint career_facts_source_check CHECK ((source = ANY (ARRAY['training'::text, 'proof'::text, 'coach'::text, 'server'::text])));
alter table public.career_facts add constraint career_facts_value_check CHECK ((jsonb_typeof(value) = 'object'::text));
alter table public.career_rules add constraint career_rules_pkey PRIMARY KEY (version);
