alter table public.career_rules add constraint career_rules_version_check CHECK ((version >= 1));
alter table public.career_scores add constraint career_scores_pkey PRIMARY KEY (athlete_id);
alter table public.career_scores add constraint career_scores_score_check CHECK ((jsonb_typeof(score) = 'object'::text));
alter table public.chat_conversations add constraint chat_conversations_handoff_check CHECK ((handoff = ANY (ARRAY['whatsapp'::text, 'apply'::text])));
alter table public.chat_conversations add constraint chat_conversations_pkey PRIMARY KEY (id);
alter table public.chat_conversations add constraint chat_conversations_site_check CHECK ((site = ANY (ARRAY['en'::text, 'fa'::text])));
alter table public.chat_messages add constraint chat_messages_pkey PRIMARY KEY (id);
alter table public.chat_messages add constraint chat_messages_role_check CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text])));
alter table public.coaching_log_versions add constraint coaching_log_versions_pkey PRIMARY KEY (id);
alter table public.coaching_logs add constraint coaching_logs_pkey PRIMARY KEY (athlete_id);
alter table public.course_en add constraint course_en_id_check CHECK ((id ~ '^[a-z0-9-]{1,40}$'::text));
alter table public.course_en add constraint course_en_kind_check CHECK ((kind = ANY (ARRAY['lesson'::text, 'test'::text, 'testday'::text])));
alter table public.course_en add constraint course_en_pkey PRIMARY KEY (id);
alter table public.cycle_reports add constraint cycle_reports_athlete_id_cycle_key UNIQUE (athlete_id, cycle);
alter table public.cycle_reports add constraint cycle_reports_pkey PRIMARY KEY (id);
alter table public.erasure_log add constraint erasure_log_kind_check CHECK ((kind = ANY (ARRAY['athlete'::text, 'course'::text, 'testing'::text])));
alter table public.erasure_log add constraint erasure_log_pkey PRIMARY KEY (id);
alter table public.exercise_coach add constraint exercise_coach_cost_ok CHECK (((cost IS NULL) OR (cost = ANY (ARRAY['heavy'::text, 'moderate'::text, 'isolation'::text, 'none'::text]))));
alter table public.exercise_coach add constraint exercise_coach_credits_ok CHECK (spine_credits_ok(credits));
alter table public.exercise_coach add constraint exercise_coach_pkey PRIMARY KEY (id);
alter table public.exercise_coach add constraint exercise_coach_suggested_changes_ok CHECK ((jsonb_typeof(suggested_changes) = 'array'::text));
alter table public.exercises add constraint exercises_cues_fa_ok CHECK (((cues_fa IS NULL) OR ((jsonb_typeof(cues_fa) = 'object'::text) AND (jsonb_typeof(COALESCE((cues_fa -> 'good'::text), '[]'::jsonb)) = 'array'::text) AND (jsonb_typeof(COALESCE((cues_fa -> 'bad'::text), '[]'::jsonb)) = 'array'::text))));
alter table public.exercises add constraint exercises_id_check CHECK ((id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text));
alter table public.exercises add constraint exercises_impact_check CHECK (((impact IS NULL) OR (impact = ANY (ARRAY['none'::text, 'running'::text, 'plyometric'::text, 'landing'::text]))));
alter table public.exercises add constraint exercises_loads_check CHECK ((loads <@ ARRAY['ankle-foot'::text, 'calf-achilles'::text, 'knee'::text, 'hip-groin'::text, 'hamstring'::text, 'low-back'::text, 'trunk'::text, 'shoulder'::text, 'elbow-forearm-wrist'::text, 'neck'::text]));
alter table public.exercises add constraint exercises_muscles_ok CHECK (spine_credits_ok(muscles));
alter table public.exercises add constraint exercises_pkey PRIMARY KEY (id);
alter table public.exercises add constraint exercises_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text])));
alter table public.exercises add constraint exercises_steps_fa_ok CHECK (spine_steps_ok(steps_fa));
alter table public.exercises add constraint exercises_steps_ok CHECK (spine_steps_ok(steps));
alter table public.hab_contacts add constraint hab_contacts_pkey PRIMARY KEY (athlete_id);
alter table public.hab_intake add constraint hab_intake_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['client'::text, 'free'::text, 'not_a_fit'::text, 'no_reply'::text, 'declined'::text, 'other'::text]))));
alter table public.hab_intake add constraint hab_intake_pkey PRIMARY KEY (id);
alter table public.hab_notes add constraint hab_notes_pkey PRIMARY KEY (athlete_id, day);
alter table public.hab_season_results add constraint hab_season_results_pkey PRIMARY KEY (athlete_id, starts_on);
alter table public.hab_titles add constraint hab_titles_pkey PRIMARY KEY (athlete_id, title);
alter table public.leaderboard_optin add constraint leaderboard_optin_pkey PRIMARY KEY (athlete_id);
alter table public.library add constraint library_kind_check CHECK ((kind = ANY (ARRAY['workout'::text, 'article'::text])));
alter table public.library add constraint library_pkey PRIMARY KEY (slug);
alter table public.library_categories add constraint library_categories_kind_check CHECK ((kind = ANY (ARRAY['workout'::text, 'article'::text])));
alter table public.library_categories add constraint library_categories_pkey PRIMARY KEY (kind, id);
alter table public.library_sessions add constraint library_sessions_pkey PRIMARY KEY (athlete_id, slug, completed_on);
alter table public.messages add constraint messages_pkey PRIMARY KEY (id);
alter table public.messages add constraint messages_sender_check CHECK ((sender = ANY (ARRAY['coach'::text, 'athlete'::text])));
alter table public.program_versions add constraint program_versions_pkey PRIMARY KEY (id);
alter table public.programs add constraint programs_pkey PRIMARY KEY (athlete_id);
alter table public.qualities add constraint qualities_id_check CHECK ((id ~ '^[a-z]+$'::text));
alter table public.qualities add constraint qualities_pkey PRIMARY KEY (id);
alter table public.qualities add constraint qualities_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'approved'::text])));
alter table public.seasons add constraint seasons_pkey PRIMARY KEY (id);
alter table public.session_history add constraint session_history_pkey PRIMARY KEY (athlete_id, day, completed_on);
alter table public.spine_versions add constraint spine_versions_op_check CHECK ((op = ANY (ARRAY['update'::text, 'delete'::text])));
alter table public.spine_versions add constraint spine_versions_pkey PRIMARY KEY (id);
alter table public.spine_versions add constraint spine_versions_tbl_check CHECK ((tbl = ANY (ARRAY['exercises'::text, 'exercise_coach'::text, 'qualities'::text])));
alter table public.tps_accounts add constraint tps_accounts_label_check CHECK (((label IS NULL) OR (length(label) <= 80)));
alter table public.tps_accounts add constraint tps_accounts_pkey PRIMARY KEY (user_id);
alter table public.tps_accounts add constraint tps_accounts_username_check CHECK ((username ~ '^[a-z0-9_]{3,32}$'::text));
alter table public.tps_accounts add constraint tps_accounts_username_key UNIQUE (username);
alter table public.tps_content add constraint tps_content_key_check CHECK ((key ~ '^[a-z0-9-]{1,40}$'::text));
alter table public.tps_content add constraint tps_content_pkey PRIMARY KEY (key);
alter table public.tps_publish_keys add constraint tps_publish_keys_pkey PRIMARY KEY (key_hash);
alter table public.xp_rules add constraint xp_rules_pkey PRIMARY KEY (id);
alter table public.xp_rules add constraint xp_rules_single_row CHECK ((id = 1));
-- foreign keys, last
alter table public.assess_accounts add constraint assess_accounts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.assess_notes add constraint assess_notes_player_id_account_id_fkey FOREIGN KEY (player_id, account_id) REFERENCES assess_players(id, account_id) ON DELETE CASCADE;
alter table public.assess_players add constraint assess_players_account_id_fkey FOREIGN KEY (account_id) REFERENCES assess_accounts(user_id) ON DELETE CASCADE;
alter table public.assess_results add constraint assess_results_player_id_account_id_fkey FOREIGN KEY (player_id, account_id) REFERENCES assess_players(id, account_id) ON DELETE CASCADE;
alter table public.athlete_identities add constraint athlete_identities_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.buyer_notes add constraint buyer_notes_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.chat_messages add constraint chat_messages_conversation_id_fkey FOREIGN KEY (conversation_id) REFERENCES chat_conversations(id) ON DELETE CASCADE;
alter table public.exercise_coach add constraint exercise_coach_id_fkey FOREIGN KEY (id) REFERENCES exercises(id) ON DELETE CASCADE;
alter table public.tps_accounts add constraint tps_accounts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

-- ── 5. indexes, triggers, row-level security, policies ──────────────────────
CREATE INDEX assess_notes_account ON public.assess_notes USING btree (account_id);
CREATE INDEX assess_players_account ON public.assess_players USING btree (account_id);
CREATE INDEX assess_results_account ON public.assess_results USING btree (account_id);
CREATE INDEX athlete_progress_updated_idx ON public.athlete_progress USING btree (updated_at DESC);
CREATE INDEX call_logs_athlete_date_idx ON public.call_logs USING btree (athlete_id, call_date DESC);
CREATE INDEX call_logs_content_flag_idx ON public.call_logs USING btree (((ai_summary ->> 'content_worthy'::text))) WHERE (ai_summary IS NOT NULL);
CREATE INDEX career_facts_day_idx ON public.career_facts USING btree (athlete_id, day);
CREATE INDEX chat_conversations_started ON public.chat_conversations USING btree (started_at DESC);
CREATE INDEX chat_conversations_visitor ON public.chat_conversations USING btree (visitor, started_at);
CREATE INDEX chat_messages_conv ON public.chat_messages USING btree (conversation_id, id);
CREATE INDEX chat_messages_open_gaps ON public.chat_messages USING btree (at DESC) WHERE (gap AND (gap_handled_at IS NULL));
CREATE INDEX coaching_log_versions_athlete_idx ON public.coaching_log_versions USING btree (athlete_id, id DESC);
CREATE INDEX cycle_reports_athlete_idx ON public.cycle_reports USING btree (athlete_id, cycle);
CREATE INDEX hab_contacts_created_idx ON public.hab_contacts USING btree (created_at DESC);
CREATE INDEX hab_intake_created_idx ON public.hab_intake USING btree (created_at DESC);
CREATE INDEX hab_intake_status_idx ON public.hab_intake USING btree (status);
CREATE INDEX hab_notes_day_idx ON public.hab_notes USING btree (day DESC);
CREATE INDEX library_kind_idx ON public.library USING btree (kind, published);
CREATE INDEX library_sessions_athlete_day_idx ON public.library_sessions USING btree (athlete_id, completed_on DESC);
CREATE INDEX messages_athlete_idx ON public.messages USING btree (athlete_id, created_at);
CREATE INDEX program_versions_athlete_saved_idx ON public.program_versions USING btree (athlete_id, saved_at DESC);
CREATE UNIQUE INDEX seasons_starts_on_key ON public.seasons USING btree (starts_on);
CREATE INDEX session_history_athlete_idx ON public.session_history USING btree (athlete_id, completed_on DESC);
CREATE INDEX spine_versions_row_idx ON public.spine_versions USING btree (tbl, row_id, id DESC);

CREATE TRIGGER affiliates_touch BEFORE UPDATE ON public.affiliates FOR EACH ROW EXECUTE FUNCTION touch_affiliates_updated_at();
CREATE TRIGGER assess_accounts_label_trg BEFORE INSERT OR UPDATE OF label ON public.assess_accounts FOR EACH ROW EXECUTE FUNCTION move_buyer_label('testing');
CREATE TRIGGER assess_players_touch BEFORE UPDATE ON public.assess_players FOR EACH ROW EXECUTE FUNCTION assess_touch();
CREATE TRIGGER assess_results_touch BEFORE UPDATE ON public.assess_results FOR EACH ROW EXECUTE FUNCTION assess_touch();
CREATE TRIGGER career_progress_trg AFTER INSERT OR DELETE OR UPDATE ON public.athlete_progress FOR EACH ROW EXECUTE FUNCTION career_on_progress();
CREATE TRIGGER call_logs_touch BEFORE UPDATE ON public.call_logs FOR EACH ROW EXECUTE FUNCTION touch_call_logs_updated_at();
CREATE TRIGGER coaching_logs_touch_trg BEFORE UPDATE ON public.coaching_logs FOR EACH ROW EXECUTE FUNCTION coaching_logs_touch();
CREATE TRIGGER coaching_logs_version_trg BEFORE UPDATE ON public.coaching_logs FOR EACH ROW EXECUTE FUNCTION coaching_logs_keep_version();
CREATE TRIGGER exercise_coach_version_trg BEFORE DELETE OR UPDATE ON public.exercise_coach FOR EACH ROW EXECUTE FUNCTION spine_keep_version();
CREATE TRIGGER exercises_touch_updated_at BEFORE UPDATE ON public.exercises FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER exercises_version_trg BEFORE DELETE OR UPDATE ON public.exercises FOR EACH ROW EXECUTE FUNCTION spine_keep_version();
CREATE TRIGGER hab_notes_prune_trg AFTER INSERT OR UPDATE ON public.hab_notes FOR EACH STATEMENT EXECUTE FUNCTION hab_notes_prune();
CREATE TRIGGER library_touch_trg BEFORE UPDATE ON public.library FOR EACH ROW EXECUTE FUNCTION library_touch();
CREATE TRIGGER career_library_trg AFTER INSERT OR DELETE OR UPDATE ON public.library_sessions FOR EACH ROW EXECUTE FUNCTION career_on_library();
CREATE TRIGGER career_programme_trg AFTER INSERT OR UPDATE OF data ON public.programs FOR EACH ROW EXECUTE FUNCTION career_on_programme();
CREATE TRIGGER programs_version_trg BEFORE UPDATE ON public.programs FOR EACH ROW EXECUTE FUNCTION programs_version_snapshot();
CREATE TRIGGER qualities_touch_updated_at BEFORE UPDATE ON public.qualities FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE TRIGGER qualities_version_trg BEFORE DELETE OR UPDATE ON public.qualities FOR EACH ROW EXECUTE FUNCTION spine_keep_version();
CREATE TRIGGER career_session_trg AFTER INSERT OR DELETE OR UPDATE ON public.session_history FOR EACH ROW EXECUTE FUNCTION career_on_session();
CREATE TRIGGER tps_accounts_label_trg BEFORE INSERT OR UPDATE OF label ON public.tps_accounts FOR EACH ROW EXECUTE FUNCTION move_buyer_label('course');

