-- ── 7. the trigger on the sign-in table (auth.users) that calls a public function ────────
CREATE TRIGGER clear_used_first_passwords_trg AFTER UPDATE OF last_sign_in_at ON auth.users FOR EACH ROW WHEN ((new.last_sign_in_at IS DISTINCT FROM old.last_sign_in_at)) EXECUTE FUNCTION clear_used_first_passwords();

reset check_function_bodies;
